 191	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
 192	static conn_slot_t* pool_acquire(const char* host, const char* port)
 193	{
 194	    pthread_mutex_lock(&s_pool_lock);
 195	
 196	    /* 1. Find an existing valid slot for this host:port */
 197	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 198	        conn_slot_t* s = &s_pool[i];
 199	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
 200	            s->in_use = true;
 201	            pthread_mutex_unlock(&s_pool_lock);
 202	            return s;
 203	        }
 204	    }
 205	
 206	    /* 2. Find an empty slot */
 207	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 208	        if (!s_pool[i].valid && !s_pool[i].in_use) {
 209	            s_pool[i].in_use = true;
 210	            pthread_mutex_unlock(&s_pool_lock);
 211	            return &s_pool[i];
 212	        }
 213	    }
 214	
 215	    /* 3. Evict the first non-in-use slot */
 216	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 217	        if (!s_pool[i].in_use) {
 218	            tls_ctx_free(&s_pool[i].ctx);
 219	            s_pool[i].valid = false;
 220	            s_pool[i].in_use = true;
 221	            pthread_mutex_unlock(&s_pool_lock);
 222	            return &s_pool[i];
 223	        }
 224	    }
 225	
 226	    pthread_mutex_unlock(&s_pool_lock);
 227	    return NULL; /* all slots busy — caller falls back to ephemeral */
 228	}
