 247	void vela_tls_pool_cleanup(void)
 248	{
 249	    pthread_mutex_lock(&s_pool_lock);
 250	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 251	        if (s_pool[i].in_use) {
 252	            syslog(LOG_WARNING,
 253	                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
