181	static void get_endpoint(char *host, size_t host_cap,
182	                         char *path, size_t path_cap)
183	{
184	    strncpy(host, AGENT_MIMO_VOICE_HOST, host_cap - 1);
185	    strncpy(path, AGENT_MIMO_VOICE_PATH, path_cap - 1);
186	
187	    /* ASR/TTS are served by the token-plan endpoint.  Do not inherit the
188	     * general LLM host: older MiMo presets used api.xiaomimimo.com. */
189	
190	    host[host_cap - 1] = '\0';
191	    path[path_cap - 1] = '\0';
