194	static int post_mimo(const char *body, char *response, size_t response_cap)
195	{
196	    char key[256] = { 0 };
197	    char host[128] = { 0 };
198	    char path[128] = { 0 };
199	    char auth[320];
200	    vela_header_t headers[2];
201	    int status;
202	
203	    if (get_api_key(key, sizeof(key)) < 0) {
204	        syslog(LOG_ERR, "[%s] No API key; use set_llm or set_mimo_key\n", TAG);
205	        return -EACCES;
206	    }
207	
208	    get_endpoint(host, sizeof(host), path, sizeof(path));
209	    snprintf(auth, sizeof(auth), "Bearer %s", key);
210	    headers[0].name = "Authorization";
211	    headers[0].value = auth;
212	    headers[1].name = NULL;
213	    headers[1].value = NULL;
214	
215	    status = vela_https_post_json(host, AGENT_MIMO_VOICE_PORT, path,
216	        headers, body, response, response_cap);
217	    memset(key, 0, sizeof(key));
218	
219	    if (status < 200 || status >= 300) {
220	        syslog(LOG_ERR, "[%s] HTTPS request status=%d\n", TAG, status);
221	        return status > 0 ? -EIO : status;
222	    }
223	
224	    return 0;
225	}
