 66	        if (c < 0x80) {
 67	            continue;
 68	        } else if (c >= 0xc2 && c <= 0xdf) {
 69	            need = 1;
 70	            code = c & 0x1f;
 71	        } else if (c >= 0xe0 && c <= 0xef) {
 72	            need = 2;
 73	            code = c & 0x0f;
 74	        } else if (c >= 0xf0 && c <= 0xf4) {
 75	            need = 3;
 76	            code = c & 0x07;
 77	        } else {
 78	            return i;
 79	        }
 80	
 81	        if (need > len - i - 1) {
 82	            return i;
 83	        }
 84	
 85	        for (size_t j = 1; j <= need; j++) {
 86	            if ((data[i + j] & 0xc0) != 0x80) {
 87	                return i + j;
 88	            }
 89	            code = (code << 6) | (data[i + j] & 0x3f);
 90	        }
 91	
 92	        if ((need == 1 && code < 0x80)
 93	            || (need == 2 && code < 0x800)
 94	            || (need == 3 && code < 0x10000)
 95	            || (code > 0x10ffff)
 96	            || (code >= 0xd800 && code <= 0xdfff)) {
 97	            return i;
 98	        }
 99	
100	        i += need;
101	    }
102	
103	    return len;
104	}
