106	static bool validate_request_json(const char *post_data)
107	{
108	    size_t len = post_data ? strlen(post_data) : 0;
109	    size_t bad = post_data ? first_invalid_utf8(
110	        (const unsigned char *)post_data, len) : 0;
111	
112	    if (!post_data || bad != len) {
113	        syslog(LOG_ERR,
114	            "[LLM-JSON] body bytes=%zu utf8=invalid offset=%zu value=0x%02x\n",
115	            len, bad, post_data ? (unsigned char)post_data[bad] : 0);
116	        return false;
117	    }
118	
119	    cJSON *root = cJSON_ParseWithLength(post_data, len);
120	    if (!root) {
121	        syslog(LOG_ERR, "[LLM-JSON] body bytes=%zu utf8=ok parse=fail\n", len);
122	        return false;
123	    }
124	
125	    cJSON_Delete(root);
126	    syslog(LOG_INFO, "[LLM-JSON] body bytes=%zu utf8=ok parse=ok\n", len);
127	    return true;
128	}
