139	int resp_buf_init(resp_buf_t* rb, size_t initial_cap)
140	{
141	    rb->data = calloc(1, initial_cap);
142	    if (!rb->data)
143	        return ERROR;
144	    rb->len = 0;
145	    rb->cap = initial_cap;
146	    return OK;
147	}
148	
149	int resp_buf_append(resp_buf_t* rb, const char* data, size_t len)
150	{
151	    while (rb->len + len >= rb->cap) {
152	        size_t new_cap = rb->cap * 2;
153	        if (new_cap > AGENT_LLM_MAX_RESP_SIZE) {
154	            syslog(LOG_ERR, "llm: resp_buf exceeded %d limit\n",
155	                AGENT_LLM_MAX_RESP_SIZE);
156	            return ERROR;
157	        }
158	        char* tmp = realloc(rb->data, new_cap);
159	        if (!tmp)
160	            return ERROR;
161	        rb->data = tmp;
162	        rb->cap = new_cap;
163	    }
164	    memcpy(rb->data + rb->len, data, len);
165	    rb->len += len;
166	    rb->data[rb->len] = '\0';
167	    return OK;
168	}
