645	/* Extract text from OpenAI response format: choices[0].message.content */
646	void extract_text(cJSON* root, char* buf, size_t size)
647	{
648	    buf[0] = '\0';
649	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
650	    if (!choices || !cJSON_IsArray(choices))
651	        return;
652	
653	    cJSON* first = choices->child;
654	    if (!first)
655	        return;
656	
657	    cJSON* message = cJSON_GetObjectItem(first, "message");
658	    if (!message)
659	        return;
660	
661	    cJSON* content = cJSON_GetObjectItem(message, "content");
662	    if (!content || !cJSON_IsString(content))
663	        return;
664	
665	    size_t tlen = strlen(content->valuestring);
666	    size_t copy = (tlen < size - 1) ? tlen : size - 1;
667	    memcpy(buf, content->valuestring, copy);
668	    buf[copy] = '\0';
669	}
