912	
913	    /* Bot-to-bot rate limiting */
914	    if (is_bot_sender && cJSON_IsString(chat_id_j)) {
915	        if (bot_rate_limited(chat_id_j->valuestring)) {
916	            goto cleanup;
917	        }
918	    }
919	
920	    if (filter_stale_message(msg)) {
921	        goto cleanup;
922	    }
923	
924	    if (!cJSON_IsString(chat_id_j)) {
925	        goto cleanup;
926	    }
