 43	static int append(struct rv_llm_sse_s *s, cJSON *object,
 44	                  const char *key, const cJSON *part)
 45	{
 46	  cJSON *old = cJSON_GetObjectItem(object, key);
 47	  size_t before = cJSON_IsString(old) ? strlen(old->valuestring) : 0;
 48	  size_t n;
 49	  char *joined;
 50	  if (!part) return 0;
 51	  if (!cJSON_IsString(part) || !part->valuestring) return -EPROTO;
 52	  n = strlen(part->valuestring);
 53	  if (n > s->limit - s->string_bytes) return -EOVERFLOW;
 54	  joined = malloc(before + n + 1);
 55	  if (!joined) return -ENOMEM;
 56	  if (before) memcpy(joined, old->valuestring, before);
 57	  memcpy(joined + before, part->valuestring, n + 1);
 58	  cJSON_DeleteItemFromObject(object, key);
 59	  old = cJSON_AddStringToObject(object, key, joined);
 60	  free(joined);
 61	  if (!old) return -ENOMEM;
 62	  s->string_bytes += n;
 63	  return 0;
 64	}
