 66	static int copy_field(cJSON *to, const cJSON *from, const char *name)
 67	{
 68	  cJSON *item = cJSON_GetObjectItem(from, name), *copy;
 69	  if (!item) return 0;
 70	  copy = cJSON_Duplicate(item, true);
 71	  if (!copy) return -ENOMEM;
 72	  cJSON_DeleteItemFromObject(to, name);
 73	  if (!cJSON_AddItemToObject(to, name, copy))
 74	    { cJSON_Delete(copy); return -ENOMEM; }
 75	  return 0;
 76	}
