 78	static int tools_delta(struct rv_llm_sse_s *s, cJSON *parts)
 79	{
 80	  cJSON *tools = cJSON_GetObjectItem(s->message, "tool_calls");
 81	  if (!cJSON_IsArray(parts)) return -EPROTO;
 82	  if (!tools)
 83	    {
 84	      tools = cJSON_CreateArray();
 85	      if (!tools) return -ENOMEM;
 86	      if (!cJSON_AddItemToObject(s->message, "tool_calls", tools))
 87	        { cJSON_Delete(tools); return -ENOMEM; }
 88	    }
 89	  for (int i = 0; i < cJSON_GetArraySize(parts); i++)
 90	    {
 91	      cJSON *p = cJSON_GetArrayItem(parts, i);
 92	      cJSON *index = cJSON_GetObjectItem(p, "index");
 93	      cJSON *call, *function, *f = cJSON_GetObjectItem(p, "function");
 94	      int ret;
 95	      if (!cJSON_IsNumber(index) || index->valuedouble != index->valueint ||
 96	          index->valueint < 0 || index->valueint >= 16) return -EPROTO;
 97	      while (cJSON_GetArraySize(tools) <= index->valueint)
 98	        {
 99	          call = cJSON_CreateObject();
100	          if (!call) return -ENOMEM;
101	          if (!cJSON_AddItemToArray(tools, call))
102	            { cJSON_Delete(call); return -ENOMEM; }
103	        }
104	      call = cJSON_GetArrayItem(tools, index->valueint);
105	      ret = append(s, call, "id", cJSON_GetObjectItem(p, "id"));
106	      if (ret < 0) return ret;
107	      ret = append(s, call, "type", cJSON_GetObjectItem(p, "type"));
108	      if (ret < 0) return ret;
109	      if (!f) continue;
110	      if (!cJSON_IsObject(f)) return -EPROTO;
111	      function = cJSON_GetObjectItem(call, "function");
112	      if (!function)
113	        {
114	          function = cJSON_CreateObject();
115	          if (!function) return -ENOMEM;
116	          if (!cJSON_AddItemToObject(call, "function", function))
117	            { cJSON_Delete(function); return -ENOMEM; }
118	        }
119	      ret = append(s, function, "name", cJSON_GetObjectItem(f, "name"));
120	      if (ret < 0) return ret;
121	      ret = append(s, function, "arguments", cJSON_GetObjectItem(f, "arguments"));
122	      if (ret < 0) return ret;
123	    }
124	  return 0;
125	}
