127	static int event(struct rv_llm_sse_s *s)
128	{
129	  char *line = s->event, *out = s->event;
130	  cJSON *root = NULL, *choices, *first, *delta, *text, *calls, *finish;
131	  bool found = false;
132	  int ret = 0;
133	  while (*line)
134	    {
135	      char *end = strchr(line, '\n');
136	      size_t n = end ? (size_t)(end - line) : strlen(line);
137	      if (n && line[n - 1] == '\r') n--;
138	      if (n >= 5 && !memcmp(line, "data:", 5))
139	        {
140	          size_t skip = n > 5 && line[5] == ' ' ? 6 : 5;
141	          if (found) *out++ = '\n';
142	          memmove(out, line + skip, n - skip);
143	          out += n - skip;
144	          found = true;
145	        }
146	      if (!end) break;
147	      line = end + 1;
148	    }
149	  *out = 0;
150	  if (!found || out == s->event) return 0;
151	  if (s->done) return -EPROTO;
152	  if (!strcmp(s->event, "[DONE]"))
153	    {
154	      if (!s->finished) return -EPROTO;
155	      s->done = true;
156	      return 0;
157	    }
158	  root = cJSON_Parse(s->event);
159	  if (!cJSON_IsObject(root)) { ret = -EPROTO; goto out; }
160	  if (cJSON_GetObjectItem(root, "error")) { ret = -EIO; goto out; }
161	  if ((ret = copy_field(s->root, root, "id")) < 0 ||
162	      (ret = copy_field(s->root, root, "model")) < 0 ||
163	      (ret = copy_field(s->root, root, "created")) < 0 ||
164	      (ret = copy_field(s->root, root, "usage")) < 0) goto out;
165	  choices = cJSON_GetObjectItem(root, "choices");
166	  if (!cJSON_IsArray(choices)) { ret = -EPROTO; goto out; }
167	  for (int i = 0; i < cJSON_GetArraySize(choices); i++)
168	    {
169	      first = cJSON_GetArrayItem(choices, i);
170	      cJSON *idx = cJSON_GetObjectItem(first, "index");
171	      if (idx && (!cJSON_IsNumber(idx) || idx->valuedouble != 0))
172	        { ret = -EPROTO; goto out; }
173	      if (s->finished) { ret = -EPROTO; goto out; }
174	      delta = cJSON_GetObjectItem(first, "delta");
175	      if (!cJSON_IsObject(delta)) { ret = -EPROTO; goto out; }
176	      calls = cJSON_GetObjectItem(delta, "tool_calls");
177	      /* Stop queued speech before accepting content in the same event. */
178	      if (calls && !cJSON_IsNull(calls) && !cJSON_IsArray(calls))
179	        { ret = -EPROTO; goto out; }
180	      if (cJSON_GetArraySize(calls) > 0)
181	        {
182	          if (!s->first_delta_ms) s->first_delta_ms = llm_now_ms();
183	          s->tools = true;
184	          if (s->delta) s->delta(s->arg, NULL, 0, true);
185	          ret = tools_delta(s, calls);
186	          if (ret < 0) goto out;
187	        }
188	      text = cJSON_GetObjectItem(delta, "content");
189	      if (text && !cJSON_IsNull(text))
190	        {
191	          if (!cJSON_IsString(text)) { ret = -EPROTO; goto out; }
192	          size_t n = strlen(text->valuestring);
193	          if (n >= ROBOT_VOICE_TEXT_CAP - s->text_bytes)
194	            { ret = -EOVERFLOW; goto out; }
195	          ret = append(s, s->message, "content", text);
196	          if (ret < 0) goto out;
197	          if (n && !s->first_delta_ms) s->first_delta_ms = llm_now_ms();
198	          s->text_bytes += n;
199	          if (n && s->delta) s->delta(s->arg, text->valuestring, n, s->tools);
200	        }
201	      text = cJSON_GetObjectItem(delta, "reasoning_content");
202	      if (text && !cJSON_IsNull(text))
203	        { ret = append(s, s->message, "reasoning_content", text); if (ret < 0) goto out; }
204	      finish = cJSON_GetObjectItem(first, "finish_reason");
205	      if (finish && !cJSON_IsNull(finish))
206	        {
207	          if (!cJSON_IsString(finish) ||
208	              (strcmp(finish->valuestring, "stop") &&
209	               strcmp(finish->valuestring, "length") &&
210	               strcmp(finish->valuestring, "tool_calls")))
211	            { ret = -EPROTO; goto out; }
212	          ret = copy_field(s->choice, first, "finish_reason");
213	          if (ret < 0) goto out;
214	          s->finished = true;
215	        }
216	    }
217	out:
218	  cJSON_Delete(root);
219	  return ret;
220	}
