222	int rv_llm_sse_init(struct rv_llm_sse_s *s, size_t limit,
223	                    void (*cb)(void *, const char *, size_t, bool), void *arg)
224	{
225	  cJSON *choices;
226	  memset(s, 0, sizeof(*s));
227	  s->limit = limit;
228	  s->delta = cb; s->arg = arg;
229	  s->root = cJSON_Parse("{\"object\":\"chat.completion\",\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"\"}}]}");
230	  if (!s->root) return -ENOMEM;
231	  choices = cJSON_GetObjectItem(s->root, "choices");
232	  s->choice = cJSON_GetArrayItem(choices, 0);
233	  s->message = cJSON_GetObjectItem(s->choice, "message");
234	  return 0;
