237	int rv_llm_sse_feed(const char *data, size_t len, void *arg)
238	{
239	  struct rv_llm_sse_s *s = arg;
240	  if (!s || (!data && len)) return -EINVAL;
241	  if (s->error) return s->error;
242	  for (size_t i = 0; i < len; i++)
243	    {
244	      if (!data[i]) return s->error = -EPROTO;
245	      if (s->used + 2 > s->capacity)
246	        {
247	          size_t cap = s->capacity ? s->capacity * 2 : 1024;
248	          char *p;
249	          if (cap > ROBOT_VOICE_LLM_SSE_MAX + 1) cap = ROBOT_VOICE_LLM_SSE_MAX + 1;
250	          if (cap <= s->used + 1) return s->error = -EOVERFLOW;
251	          p = realloc(s->event, cap);
252	          if (!p) return s->error = -ENOMEM;
253	          s->event = p; s->capacity = cap;
254	        }
255	      s->event[s->used++] = data[i]; s->event[s->used] = 0;
256	      if ((s->used >= 2 && !memcmp(s->event + s->used - 2, "\n\n", 2)) ||
257	          (s->used >= 3 && !memcmp(s->event + s->used - 3, "\n\r\n", 3)) ||
258	          (s->used >= 4 && !memcmp(s->event + s->used - 4, "\r\n\r\n", 4)))
259	        {
260	          int ret = event(s);
261	          s->used = 0;
262	          if (ret < 0) return s->error = ret;
263	        }
264	    }
265	  return 0;
266	}
