268	int rv_llm_sse_validate(struct rv_llm_sse_s *s)
269	{
270	  cJSON *tools = cJSON_GetObjectItem(s->message, "tool_calls");
271	  if (s->error) return s->error;
272	  if (!s->done || !s->finished || s->used) return -EPROTO;
273	  if (!s->text_bytes && !s->tools) return -ENODATA;
274	  cJSON *reason = cJSON_GetObjectItem(s->choice, "finish_reason");
275	  if (s->tools != !strcmp(reason->valuestring, "tool_calls")) return -EPROTO;
276	  if (s->tools)
277	    {
278	      if (!cJSON_GetArraySize(tools)) return -EPROTO;
279	      for (int i = 0; i < cJSON_GetArraySize(tools); i++)
280	        {
281	          cJSON *t = cJSON_GetArrayItem(tools, i);
282	          cJSON *id = cJSON_GetObjectItem(t, "id");
283	          cJSON *type = cJSON_GetObjectItem(t, "type");
284	          cJSON *f = cJSON_GetObjectItem(t, "function");
285	          cJSON *name = cJSON_GetObjectItem(f, "name");
286	          cJSON *args = cJSON_GetObjectItem(f, "arguments");
287	          if (!cJSON_IsString(id) || !id->valuestring[0] ||
288	              !cJSON_IsString(type) || strcmp(type->valuestring, "function") ||
289	              !cJSON_IsString(name) || !name->valuestring[0] ||
290	              !cJSON_IsString(args)) return -EPROTO;
291	        }
292	    }
293	  return 0;
294	}
