296	int rv_llm_sse_finish(struct rv_llm_sse_s *s, char *out, size_t cap)
297	{
298	  char *json;
299	  int ret;
300	  if (!out || !cap) return -EINVAL;
301	  out[0] = 0;
302	  ret = rv_llm_sse_validate(s);
303	  if (ret < 0) return ret;
304	  json = cJSON_PrintUnformatted(s->root);
305	  if (!json) return -ENOMEM;
306	  if (strlen(json) >= cap) { free(json); return -EOVERFLOW; }
307	  memcpy(out, json, strlen(json) + 1); free(json);
308	  return 0;
309	}
