314	static int http_feed(const char *p, size_t n, void *arg)
315	{
316	  struct rv_llm_sse_s *s = arg;
317	  if (!robot_voice_llm_request_current(s->request_token)) return -ECANCELED;
318	  int ret = rv_llm_sse_feed(p, n, s);
