323	{
324	  const char *host, *port, *path, *body;
325	  const vela_header_t *headers;
326	  char *response;
327	  size_t cap;
328	  void *voice;
329	  unsigned long token;
330	  size_t text_bytes;
331	  bool tools;
332	  unsigned long long first_delta_ms;
333	  int http_status;
