336	static void rv_llm_voice_delta(void *arg, const char *text, size_t n, bool tools)
337	{
338	  struct rv_llm_retry_s *ctx = arg;
339	  if (!robot_voice_llm_request_current(ctx->token)) return;
340	  if (tools || (text && n)) robot_voice_llm_reply_started(ctx->token);
341	  robot_voice_llm_stream_delta(ctx->voice, text, n, tools);
342	}
