344	static int rv_llm_retry_attempt(void *arg, unsigned int timeout_ms)
345	{
346	  struct rv_llm_retry_s *ctx = arg;
347	  struct rv_llm_sse_s s;
348	  int ret;
349	  ctx->response[0] = 0;
350	  robot_voice_llm_stream_retry_reset(ctx->voice);
351	  ret = rv_llm_sse_init(&s, ctx->cap - 1,
352	                        rv_llm_voice_delta, ctx);
353	  if (ret < 0) return ret;
354	  s.request_token = ctx->token;
355	  ret = robot_voice_http_request(ctx->host, ctx->port, "POST", ctx->path,
356	      ctx->headers, ctx->body, strlen(ctx->body), NULL, 0, http_feed, &s,
357	      timeout_ms);
358	  ctx->http_status = ret;
359	  if (ret >= 200 && ret < 300)
360	    {
361	      ret = rv_llm_sse_finish(&s, ctx->response, ctx->cap);
362	      if (ret == 0)
363	        {
364	          ctx->text_bytes = s.text_bytes;
365	          ctx->tools = s.tools;
366	          if (!ctx->first_delta_ms) ctx->first_delta_ms = s.first_delta_ms;
367	          robot_voice_llm_stream_commit(ctx->voice);
368	        }
369	    }
370	  else if (ret == 401 || ret == 403)
371	    ret = -EACCES;
372	  else if (ret == 429)
373	    ret = -EAGAIN;
374	  else if (ret >= 500)
375	    ret = -EIO;
376	  else if (ret >= 300)
377	    ret = -EPROTO;
378	  /* Feed normal Flash deltas immediately. Freeze only on a failed attempt
379	   * while a retry builds a replacement for its unsubmitted suffix. */
380	  if (!ctx->first_delta_ms) ctx->first_delta_ms = s.first_delta_ms;
381	  if (ret < 0) robot_voice_llm_stream_hold(ctx->voice);
382	  rv_llm_sse_destroy(&s);
383	  return ret;
384	}
