399	int mimo_llm_stream_request_timeout(const char *host, const char *port,
400	  const char *path, const vela_header_t *headers, const char *body,
401	  char *response, size_t cap, unsigned int timeout_ms)
402	{
403	  struct rv_llm_retry_s ctx = {
404	    .host = host, .port = port, .path = path, .body = body,
405	    .headers = headers, .response = response, .cap = cap,
406	  };
407	  int ret;
