 42	  if (!api_key || !body || !response || response_cap < 2)
 43	    {
 44	      return -EINVAL;
 45	    }
 46	  auth_len = snprintf(auth, sizeof(auth), "Bearer %s", api_key);
 47	  if (auth_len < 0 || (size_t)auth_len >= sizeof(auth))
 48	    {
 49	      memset(auth, 0, sizeof(auth));
 50	      return -EOVERFLOW;
 51	    }
 52	  headers[0].name = "Authorization";
 53	  headers[0].value = auth;
 54	  headers[1].name = "Accept";
 55	  headers[1].value = "text/event-stream, application/json";
 56	  headers[2].name = NULL;
 57	  headers[2].value = NULL;
