 61	                                ROBOT_VOICE_PATH, headers, body,
 62	                                response, response_cap, timeout_ms);
 63	  memset(auth, 0, sizeof(auth));
 64	  if (response_len != NULL)
 65	    {
 66	      *response_len = strnlen(response, response_cap);
 67	    }
 68	  RV_VERBOSE("[RV-NET] response status=%d bytes=%zu\n", status,
 69	         response_len ? *response_len : 0);
 70	  if (status < 0)
 71	    {
 72	      return status;
 73	    }
 74	  /* Let the monitor back off rather than hammering the account quota. */
 75	  if (status == 429)
