static void agent_sync_network_time(void)
{
    char time_output[128];

    for (int attempt = 1; attempt <= 3; attempt++) {
        int rc = tool_get_time_execute("{}", time_output,
            sizeof(time_output));
        if (rc == OK) {
            syslog(LOG_INFO, "[%s] Network time synchronized: %s\n", TAG,
                time_output);
            return;
        }

        syslog(LOG_WARNING,
            "[%s] Network time sync attempt %d/3 failed rc=%d\n", TAG,
            attempt, rc);
        if (attempt < 3) {
            sleep(1);
        }
    }
}

