static bool parse_and_set_time(const char *date_str, char *out, size_t out_size)
{
    int day, year, hour, min, sec;
    char mon_str[4] = {0};
    const char *date = strchr(date_str, ',');

    /* RFC 7231 normally includes a weekday, but some gateways omit it. */
    date = date ? date + 1 : date_str;
