 * network-dependent services. Main thread is NOT blocked.
 */
static void* network_watch_task(void* arg)
{
    (void)arg;
    syslog(LOG_INFO, "[%s] Network watcher started\n", TAG);

    /* Wait for an explicit set_wifi command. Do not restore saved credentials
     * automatically when ai_agent starts; the CLI owns Wi-Fi configuration. */
    syslog(LOG_INFO,
        "[%s] Waiting for explicit set_wifi before starting network services\n",
        TAG);
    bool ready = false;
    while (!g_shutdown_requested && !ready) {
        ready = network_wait_connected(1000) == OK;
    }
    if (ready && !g_shutdown_requested) {
        syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, network_get_ip());

        /* Set the clock before Feishu starts applying its timestamp window. */
        agent_sync_network_time();

#if AGENT_SKILL_SYNC_ENABLED
