        bool has_fmt = j_fmt && cJSON_IsString(j_fmt)
            && j_fmt->valuestring[0];
        bool has_rate = j_rate && cJSON_IsNumber(j_rate)
            && (int)j_rate->valuedouble > 0;
        bool has_ch = j_ch && cJSON_IsNumber(j_ch)
