    f = fopen(full_path, "r");
    if (!f || !fgets(first_line, sizeof(first_line), f))
    {
        if (f)
            fclose(f);
        return off;
    }

    extract_title(first_line, strlen(first_line), title, sizeof(title));
    extract_description(f, desc, sizeof(desc));
    fclose(f);

    n = snprintf(buf + off, size - off,
                 "- **%s**: %s (read with: read_file %s)\n",
                 title, desc, full_path);
    if (n < 0)
        return off;
    return (size_t)n >= size - off ? size - 1 : off + (size_t)n;
}

size_t skill_loader_build_summary(char *buf, size_t size)
{
    /*
     * On Vela/NuttX we have real directories, so we can simply opendir
     * on the skills directory and iterate over .md files.
     * (Original version used flat namespace readdir from mount root.)
     */
    DIR *dir = opendir(AGENT_SKILLS_DIR);
    if (!dir) {
        syslog(LOG_WARNING, "[%s] Cannot open skills directory for enumeration: %s\n", TAG, AGENT_SKILLS_DIR);
        buf[0] = '\0';
        return 0;
    }

    size_t off = 0;
    struct dirent *ent;

    /* Contest companion rules must remain visible even when the summary
     * buffer is smaller than the complete built-in skill directory. */
    static const char *const priority[] =
    {
        "feishu-send.md",
        "music-dj.md",
        "robot-music-companion.md",
        "robot-voice-companion.md",
        "robot-proactive-idle.md",
        "robot-meal-companion.md",
        "expressive-companion.md",
    };
    for (size_t i = 0; i < sizeof(priority) / sizeof(priority[0]) &&
                         off < size - 1; i++)
        off = append_skill_summary(priority[i], buf, size, off);

    rewinddir(dir);

    while ((ent = readdir(dir)) != NULL && off < size - 1) {
        const char *name = ent->d_name;
        size_t name_len = strlen(name);

        /* Match .md files only */
        if (name_len < 4) continue;
        if (strcmp(name + name_len - 3, ".md") != 0) continue;

        /* Skip hidden files */
        if (name[0] == '.') continue;

        /* The priority files were already emitted above. */
        if (skill_is_contest_priority(name)) continue;
        off = append_skill_summary(name, buf, size, off);
    }

    closedir(dir);

    buf[off] = '\0';
    syslog(LOG_INFO, "[%s] Skills summary: %d bytes\n", TAG, (int)off);
    return off;
}

