static int dispatch_voice_text(const char *text)
{
    agent_msg_t msg;

    if (!text || text[0] == '\0') {
        return 0;
    }

    memset(&msg, 0, sizeof(msg));
    strncpy(msg.channel, AGENT_CHAN_VOICE, sizeof(msg.channel) - 1);
    strncpy(msg.chat_id, "voice", sizeof(msg.chat_id) - 1);
    msg.content = strdup(text);
    if (!msg.content) {
        return -ENOMEM;
    }

    if (message_bus_push_inbound(&msg) < 0) {
        free(msg.content);
        return -EAGAIN;
    }

    return 0;
}

