{
    if (!ws->connected) {
        return -1;
    }

    uint8_t b0;
    uint8_t b1;

    if (ws_read_exact(ws, &b0, 1) < 0) {
        return -1;
    }
    if (ws_read_exact(ws, &b1, 1) < 0) {
        return -1;
