 158	static int msg_queue_pop(msg_queue_t *queue, agent_msg_t *msg,
 159	                         uint32_t timeout_ms)
 160	{
 161	    struct timespec ts;
 162	
 163	    pthread_mutex_lock(&queue->lock);
 164	
 165	    while (queue->count == 0 && queue->overflow_count == 0) {
 166	        if (g_bus_shutdown) {
 167	            pthread_mutex_unlock(&queue->lock);
 168	            return ERROR;
 169	        }
 170	        if (timeout_ms == UINT32_MAX) {
 171	            pthread_cond_wait(&queue->not_empty, &queue->lock);
 172	        } else {
 173	            clock_gettime(CLOCK_REALTIME, &ts);
 174	            ts.tv_sec += (time_t)(timeout_ms / 1000);
 175	            ts.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
 176	            if (ts.tv_nsec >= 1000000000L) {
 177	                ts.tv_sec++;
 178	                ts.tv_nsec -= 1000000000L;
 179	            }
 180	
 181	            if (pthread_cond_timedwait(&queue->not_empty, &queue->lock, &ts) != 0) {
 182	                pthread_mutex_unlock(&queue->lock);
 183	                return ERROR;
 184	            }
 185	        }
 186	    }
 187	
 188	    if (queue->count > 0) {
 189	        *msg = queue->items[queue->head];
 190	        queue->head = (queue->head + 1) % AGENT_BUS_QUEUE_LEN;
 191	        queue->count--;
 192	    } else {
 193	        msg_overflow_node_t *node = queue->overflow_head;
 194	        *msg = node->msg;
 195	        queue->overflow_head = node->next;
 196	        if (queue->overflow_head == NULL) {
 197	            queue->overflow_tail = NULL;
 198	        }
 199	        queue->overflow_count--;
 200	        free(node);
 201	    }
 202	
 203	    pthread_cond_signal(&queue->not_full);
 204	    pthread_mutex_unlock(&queue->lock);
 205	    return OK;
 206	}
