bool robot_voice_http_network_recovery_begin(void)
{
  pthread_mutex_lock(&pool_lock);
  bool idle = !network_recovering;
  for (unsigned int i = 0; i < 4; i++)
    if (pool[i].busy) idle = false;
  if (idle) {
    network_recovering = true;
    network_generation++;
