/* Read exactly `len` bytes from TLS stream; returns -1 on error. */
static int ws_read_exact(feishu_ws_t* ws, uint8_t* buf, size_t len)
{
    size_t total = 0;

    while (total < len) {
        int n = mbedtls_ssl_read(&ws->ssl, buf + total, len - total);
        if (n == MBEDTLS_ERR_SSL_WANT_READ) {
            continue;
        }
        if (n <= 0) {
            return -1;
        }
        total += (size_t)n;
    }
    return (int)total;
}

