typedef struct {
    mbedtls_ssl_context ssl;
    mbedtls_ssl_config cfg;
    mbedtls_net_context net;
    mbedtls_ctr_drbg_context ctr_drbg;
} tls_ctx_t;

static void tls_ctx_free(tls_ctx_t* ctx)
{
    static uint32_t free_seq;
    uint32_t seq = ++free_seq;

    syslog(LOG_INFO, "[TLS-FREE] seq=%" PRIu32
        " phase=begin ctx=%p fd=%d\n", seq, ctx, ctx->net.fd);
    mbedtls_ssl_close_notify(&ctx->ssl);
    syslog(LOG_INFO, "[TLS-FREE] seq=%" PRIu32 " phase=close_notify\n",
        seq);
    mbedtls_net_free(&ctx->net);
    syslog(LOG_INFO, "[TLS-FREE] seq=%" PRIu32 " phase=net_free\n", seq);
    mbedtls_ssl_free(&ctx->ssl);
    syslog(LOG_INFO, "[TLS-FREE] seq=%" PRIu32 " phase=ssl_free\n", seq);
    mbedtls_ssl_config_free(&ctx->cfg);
    syslog(LOG_INFO, "[TLS-FREE] seq=%" PRIu32 " phase=config_free\n",
        seq);
    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
    syslog(LOG_INFO, "[TLS-FREE] seq=%" PRIu32 " phase=done\n", seq);

