    bool valid; /* connection is alive */
} conn_slot_t;

static conn_slot_t s_pool[CONN_POOL_SIZE];
static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;

/* The ESP32-S3 WLAN/TLS stack is not stable with overlapping handshakes.
 * Keep the pool metadata lock short, but serialize the complete request
 * lifecycle below so every caller shares one transport at a time. */
static pthread_mutex_t s_transport_lock = PTHREAD_MUTEX_INITIALIZER;

/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
static conn_slot_t* pool_acquire(const char* host, const char* port)
{
    pthread_mutex_lock(&s_pool_lock);

    /* 1. Find an existing valid slot for this host:port */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        conn_slot_t* s = &s_pool[i];
        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
            s->in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return s;
        }
    }

    /* 2. Find an empty slot */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (!s_pool[i].valid && !s_pool[i].in_use) {
            s_pool[i].in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return &s_pool[i];
        }
    }

    /* 3. Evict the first non-in-use slot */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (!s_pool[i].in_use) {
            tls_ctx_free(&s_pool[i].ctx);
            s_pool[i].valid = false;
            s_pool[i].in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return &s_pool[i];
        }
    }

    pthread_mutex_unlock(&s_pool_lock);
    return NULL; /* all slots busy — caller falls back to ephemeral */
}

/* Return a slot to the pool.  keep=true means the connection is still alive. */
static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
{
    pthread_mutex_lock(&s_pool_lock);
    if (keep) {
        strncpy(s->host, host, sizeof(s->host) - 1);
        strncpy(s->port, port, sizeof(s->port) - 1);
        s->valid = true;
    } else {
        tls_ctx_free(&s->ctx);
        s->valid = false;
        s->host[0] = '\0';
    }
    s->in_use = false;
    pthread_mutex_unlock(&s_pool_lock);
}

void vela_tls_pool_cleanup(void)
{
    pthread_mutex_lock(&s_pool_lock);
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        return ret;
    }

    /* Connect into the slot */
    if ((ret = tls_ctx_connect(&slot->ctx, host, port)) != 0) {
        pool_release(slot, host, port, false);
        return ret;
    }

    if ((ret = tls_write_request(&slot->ctx, method, host, path,
             headers, body, body_len))
        != 0) {
        syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
        pool_release(slot, host, port, false);
        return ret;
    }

    bool keep = false;
    ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, out_body_len, &keep);
    pool_release(slot, host, port, ret > 0 && keep);
    return ret;
}

int vela_https_request(
    const char* host,
    const char* port,
    const char* method,
    const char* path,
    const vela_header_t* headers,
    const char* body,
    size_t body_len,
    char* resp_buf,
    size_t resp_cap,
    size_t* out_body_len)
{
    int ret;

    ret = network_acquire_http_transport(30000);
    if (ret < 0) {
        syslog(LOG_WARNING, "[%s] HTTPS transport busy rc=%d\n", TAG, ret);
        return ret;
    }

    pthread_mutex_lock(&s_transport_lock);
    syslog(LOG_INFO, "[%s] transport enter: %s:%s\n", TAG, host, port);
    ret = vela_https_request_locked(host, port, method, path, headers,
        body, body_len, resp_buf, resp_cap, out_body_len);
    syslog(LOG_INFO, "[%s] transport leave: %s:%s rc=%d\n", TAG, host,
        port, ret);
    pthread_mutex_unlock(&s_transport_lock);
    network_release_http_transport();
    return ret;
}

int vela_https_get(const char* host, const char* port, const char* path,
    char* resp_buf, size_t resp_cap)
{
    return vela_https_request(host, port, "GET", path, NULL, NULL, 0,
        resp_buf, resp_cap, NULL);
}

int vela_https_post_json(const char* host, const char* port, const char* path,
    const vela_header_t* extra_headers,
    const char* json_body,
    char* resp_buf, size_t resp_cap)
{
    /* Build a merged header list: Content-Type first, then caller extras */
    const int MAX_HDRS = 32;
    vela_header_t merged[MAX_HDRS];
    int n = 0;

    merged[n++] = (vela_header_t) { "Content-Type", "application/json" };

    if (extra_headers) {
        for (const vela_header_t* h = extra_headers; h->name && n < MAX_HDRS - 1; h++) {
            merged[n++] = *h;
        }
    }
    merged[n] = (vela_header_t) { NULL, NULL };

    size_t body_len = json_body ? strlen(json_body) : 0;
    return vela_https_request(host, port, "POST", path, merged,
        json_body, body_len, resp_buf, resp_cap, NULL);
}

static int vela_https_stream_request_locked(
    const char *host, const char *port, const char *method,
    const char *path, const vela_header_t *headers, const char *body,
    size_t body_len, vela_https_body_cb_t body_cb, void *user_data)
{
    conn_slot_t *slot;
    int ret;

    slot = pool_acquire(host, port);
    if (slot && slot->valid) {
        /* A previous buffered request may have been truncated.  Drain any
         * unread bytes before reusing the persistent TLS connection. */
        if (slot->ctx.net.fd >= 0) {
            unsigned char drain[512];
            int dr;
            struct timeval tv_drain = { .tv_sec = 0, .tv_usec = 10000 };
            struct timeval tv_orig = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
                .tv_usec = 0 };
            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
                &tv_drain, sizeof(tv_drain));
            while ((dr = mbedtls_ssl_read(&slot->ctx.ssl, drain,
                        sizeof(drain))) > 0) {
                ;
            }
            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
                &tv_orig, sizeof(tv_orig));
            if (dr == 0 || dr == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
                goto stream_pool_reconnect;
            }
        } else {
            goto stream_pool_reconnect;
        }

        ret = tls_write_request(&slot->ctx, method, host, path, headers,
            body, body_len);
        if (ret == 0) {
            bool keep = false;
            ret = tls_read_response_stream(&slot->ctx, body_cb, user_data,
                &keep);
            if (ret > 0) {
                pool_release(slot, host, port, keep);
                return ret;
            }
        }

stream_pool_reconnect:
        tls_ctx_free(&slot->ctx);
        slot->valid = false;
    }

    if (!slot) {
        tls_ctx_t tmp_ctx;
        ret = tls_ctx_connect(&tmp_ctx, host, port);
        if (ret != 0) {
            tls_ctx_free(&tmp_ctx);
            return ret;
        }
        ret = tls_write_request(&tmp_ctx, method, host, path, headers,
            body, body_len);
        if (ret == 0) {
            ret = tls_read_response_stream(&tmp_ctx, body_cb, user_data,
                NULL);
        }
        tls_ctx_free(&tmp_ctx);
        return ret;
    }

    ret = tls_ctx_connect(&slot->ctx, host, port);
    if (ret != 0) {
        pool_release(slot, host, port, false);
        return ret;
    }
    ret = tls_write_request(&slot->ctx, method, host, path, headers,
        body, body_len);
    if (ret != 0) {
        pool_release(slot, host, port, false);
        return ret;
    }

    {
        bool keep = false;
        ret = tls_read_response_stream(&slot->ctx, body_cb, user_data,
            &keep);
        pool_release(slot, host, port, ret > 0 && keep);
    }
    return ret;
}

int vela_https_post_json_stream(const char *host, const char *port,
    const char *path, const vela_header_t *extra_headers,
    const char *json_body, vela_https_body_cb_t body_cb, void *user_data)
{
    const int max_headers = 32;
    vela_header_t merged[max_headers];
    int n = 0;
    size_t body_len = json_body ? strlen(json_body) : 0;
    int ret;

    if (!host || !port || !path || !body_cb) {
        return VELA_TLS_ERR_READ;
    }

    merged[n++] = (vela_header_t) { "Content-Type", "application/json" };
    if (extra_headers) {
        for (const vela_header_t *h = extra_headers;
             h->name && n < max_headers - 1; h++) {
            merged[n++] = *h;
        }
    }
    merged[n] = (vela_header_t) { NULL, NULL };

    pthread_mutex_lock(&s_transport_lock);
    syslog(LOG_INFO, "[%s] streaming transport enter: %s:%s\n", TAG,
        host, port);
    ret = vela_https_stream_request_locked(host, port, "POST", path,
        merged, json_body, body_len, body_cb, user_data);
    syslog(LOG_INFO, "[%s] streaming transport leave: %s:%s rc=%d\n", TAG,
        host, port, ret);
    pthread_mutex_unlock(&s_transport_lock);
    return ret;
}

int vela_https_head_date(const char* host, const char* port, const char* path,
    char* date_out, size_t date_cap)
{
    tls_ctx_t ctx;
    int ret;

    if ((ret = tls_ctx_connect(&ctx, host, port)) != 0) {
        tls_ctx_free(&ctx);
        return ret;
    }

    if ((ret = tls_write_request(&ctx, "HEAD", host, path, NULL, NULL, 0)) != 0) {
        tls_ctx_free(&ctx);
        return ret;
    }

    /* Read raw response until end of headers (\r\n\r\n) */
    char hdr_buf[2048];
    int total = 0;
    while (total < (int)sizeof(hdr_buf) - 1) {
        ret = mbedtls_ssl_read(&ctx.ssl,
            (unsigned char*)hdr_buf + total,
            sizeof(hdr_buf) - 1 - total);
        if (ret == MBEDTLS_ERR_SSL_WANT_READ)
            continue;
        if (ret <= 0)
            break;
        total += ret;
        hdr_buf[total] = '\0';
        if (strstr(hdr_buf, "\r\n\r\n"))
            break;
    }
    tls_ctx_free(&ctx);


    if (total <= 0)
        return VELA_TLS_ERR_READ;

    /* Find Date: header, accepting CRLF/LF line endings and a header at the
     * beginning of the buffer. */
    char* p = strcasestr(hdr_buf, "\r\nDate:");
    if (!p) p = strcasestr(hdr_buf, "\nDate:");
    if (!p && strncasecmp(hdr_buf, "Date:", 5) == 0) p = hdr_buf;
    if (!p)
        return VELA_TLS_ERR_READ;
    p = strchr(p, ':') + 1;
    while (*p == ' ' || *p == '\t') p++;
    char* eol = strstr(p, "\r\n");
    if (!eol) eol = strchr(p, '\n');
    if (!eol)
        return VELA_TLS_ERR_READ;

    size_t dlen = (size_t)(eol - p);
    if (dlen >= date_cap)
        dlen = date_cap - 1;
    memcpy(date_out, p, dlen);
    date_out[dlen] = '\0';
    return 0;
}

