/*
 * Contest-local synchronization of generated Skill resources.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <nuttx/config.h>

#include <agent_config.h>

#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "contest_skill_resource.h"
#include "robot_skill_installer.h"

#define ROBOT_SKILL_NAME "robot-proactive-idle.md"
#define ROBOT_SKILL_PATH_SIZE 192
#define ROBOT_SKILL_TMP_SIZE 224

static pthread_mutex_t g_robot_skill_lock = PTHREAD_MUTEX_INITIALIZER;
static bool g_robot_skill_exists;
static bool g_robot_skill_matches;
static bool g_music_skills_ready;
static bool g_companion_skills_ready;
static int g_robot_skill_last_result = -EAGAIN;
static size_t g_skill_current;
static size_t g_skill_created;
static size_t g_skill_updated;
static size_t g_skill_failed;

static int robot_skill_mkdir_p(const char *directory)
{
  char path[ROBOT_SKILL_PATH_SIZE];
  char *cursor;
  int ret;

  if (directory == NULL || strlen(directory) >= sizeof(path))
    {
      return -ENAMETOOLONG;
    }

  strcpy(path, directory);
  while (strlen(path) > 1 && path[strlen(path) - 1] == '/')
    {
      path[strlen(path) - 1] = '\0';
    }

  for (cursor = path + 1; *cursor != '\0'; cursor++)
    {
      if (*cursor != '/')
        {
          continue;
        }
      *cursor = '\0';
      ret = mkdir(path, 0755);
      *cursor = '/';
      if (ret != 0 && errno != EEXIST)
        {
          int saved_errno = errno;
          printf("[ROBOT-SKILL] dir=%s stage=mkdir errno=%d\n", path,
                 saved_errno);
          return -saved_errno;
        }
    }

  ret = mkdir(path, 0755);
  if (ret != 0 && errno != EEXIST)
    {
      int saved_errno = errno;
      printf("[ROBOT-SKILL] dir=%s stage=mkdir errno=%d\n", path,
             saved_errno);
      return -saved_errno;
    }
  return 0;
}

static int robot_skill_make_paths(
  const struct contest_skill_resource_s *resource, char *path,
  size_t path_size, char *tmp, size_t tmp_size)
{
  int n;

  if (resource == NULL || resource->filename == NULL ||
      strchr(resource->filename, '/') != NULL)
    {
      return -EINVAL;
    }

  n = snprintf(path, path_size, "%s%s", AGENT_SKILLS_DIR,
               resource->filename);
  if (n < 0 || (size_t)n >= path_size)
    {
      return -ENAMETOOLONG;
    }

  n = snprintf(tmp, tmp_size, "%s%s.tmp", AGENT_SKILLS_DIR,
               resource->filename);
  if (n < 0 || (size_t)n >= tmp_size)
    {
      return -ENAMETOOLONG;
    }
  return 0;
}

static bool robot_skill_matches(
  const struct contest_skill_resource_s *resource, const char *path)
{
  FILE *file;
  unsigned char buffer[128];
  size_t offset = 0;

  file = fopen(path, "rb");
  if (file == NULL)
    {
      printf("[ROBOT-SKILL] name=%s stage=open-target errno=%d\n",
             resource->filename, errno);
      return false;
    }

  while (offset < resource->size)
    {
      size_t want = resource->size - offset;
      size_t got;

      if (want > sizeof(buffer))
        {
          want = sizeof(buffer);
        }
      got = fread(buffer, 1, want, file);
      if (got != want)
        {
          printf("[ROBOT-SKILL] name=%s stage=read-existing errno=%d\n",
                 resource->filename, errno != 0 ? errno : EIO);
          fclose(file);
          return false;
        }
      if (memcmp(buffer, resource->content + offset, got) != 0)
        {
          fclose(file);
          return false;
        }
      offset += got;
    }

  if (fgetc(file) != EOF || ferror(file) != 0)
    {
      printf("[ROBOT-SKILL] name=%s stage=read-existing errno=%d\n",
             resource->filename, errno != 0 ? errno : EIO);
      fclose(file);
      return false;
    }

  if (fclose(file) != 0)
    {
      printf("[ROBOT-SKILL] name=%s stage=close errno=%d\n",
             resource->filename, errno != 0 ? errno : EIO);
      return false;
    }
  return true;
}

static int robot_skill_write_atomic(
  const struct contest_skill_resource_s *resource, const char *path,
  const char *tmp)
{
  FILE *file;
  size_t written;
  int saved_errno;

  file = fopen(tmp, "wb");
  if (file == NULL)
    {
      saved_errno = errno;
      printf("[ROBOT-SKILL] name=%s stage=open-temp errno=%d\n",
             resource->filename, saved_errno);
      return -saved_errno;
    }

  written = fwrite(resource->content, 1, resource->size, file);
  if (written != resource->size)
    {
      saved_errno = errno != 0 ? errno : EIO;
      printf("[ROBOT-SKILL] name=%s stage=write errno=%d\n",
             resource->filename, saved_errno);
      fclose(file);
      unlink(tmp);
      return -saved_errno;
    }

  if (fflush(file) != 0)
    {
      saved_errno = errno != 0 ? errno : EIO;
      printf("[ROBOT-SKILL] name=%s stage=fflush errno=%d\n",
             resource->filename, saved_errno);
      fclose(file);
      unlink(tmp);
      return -saved_errno;
    }

  if (fclose(file) != 0)
    {
      saved_errno = errno != 0 ? errno : EIO;
      printf("[ROBOT-SKILL] name=%s stage=close errno=%d\n",
             resource->filename, saved_errno);
      unlink(tmp);
      return -saved_errno;
    }

  if (rename(tmp, path) != 0)
    {
      saved_errno = errno != 0 ? errno : EIO;
      printf("[ROBOT-SKILL] name=%s stage=rename errno=%d\n",
             resource->filename, saved_errno);
      unlink(tmp);
      return -saved_errno;
    }
  return 0;
}

static int robot_skill_sync_one(
  const struct contest_skill_resource_s *resource, size_t *current,
  size_t *created, size_t *updated)
{
  char path[ROBOT_SKILL_PATH_SIZE];
  char tmp[ROBOT_SKILL_TMP_SIZE];
  struct stat st;
  bool existed;
  int ret;

  ret = robot_skill_make_paths(resource, path, sizeof(path), tmp,
                               sizeof(tmp));
  if (ret < 0)
    {
      printf("[ROBOT-SKILL] name=%s stage=check errno=%d\n",
             resource->filename != NULL ? resource->filename : "(null)",
             -ret);
      return ret;
    }

  existed = stat(path, &st) == 0;
  printf("[ROBOT-SKILL] name=%s stage=stat-target result=%s\n",
         resource->filename, existed ? "exists" : "missing");
  if (existed && robot_skill_matches(resource, path))
    {
      (*current)++;
      return 0;
    }

  ret = robot_skill_write_atomic(resource, path, tmp);
  if (ret < 0)
    {
      return ret;
    }

  if (existed)
    {
      (*updated)++;
    }
  else
    {
      (*created)++;
    }
  return 0;
}

int robot_skill_installer_ensure(void)
{
  size_t i;
  int ret;
  int first_error = 0;

  pthread_mutex_lock(&g_robot_skill_lock);
  g_skill_current = 0;
  g_skill_created = 0;
  g_skill_updated = 0;
  g_skill_failed = 0;
  g_robot_skill_exists = false;
  g_robot_skill_matches = false;

  ret = robot_skill_mkdir_p(AGENT_SKILLS_DIR);
  if (ret < 0)
    {
      g_robot_skill_last_result = ret;
      pthread_mutex_unlock(&g_robot_skill_lock);
      return ret;
    }
  printf("[ROBOT-SKILL] dir=%s stage=check-dir result=ready\n",
         AGENT_SKILLS_DIR);

  /* Remove only names retired by the contest bundle.  User-created skills
   * with other names remain untouched. */
  {
    const char *retired[] = {"meal-companion.md"};
    for (size_t retired_i = 0;
         retired_i < sizeof(retired) / sizeof(retired[0]); retired_i++)
      {
        char path[ROBOT_SKILL_PATH_SIZE];
        snprintf(path, sizeof(path), "%s%s", AGENT_SKILLS_DIR,
                 retired[retired_i]);
        if (unlink(path) == 0)
          {
            printf("[ROBOT-SKILL] retired name=%s removed=1\n",
                   retired[retired_i]);
          }
      }
  }

  for (i = 0; i < contest_skill_resource_count; i++)
    {
      ret = robot_skill_sync_one(&contest_skill_resources[i],
                                 &g_skill_current, &g_skill_created,
                                 &g_skill_updated);
      if (ret < 0)
        {
          g_skill_failed++;
          if (first_error == 0)
            {
              first_error = ret;
            }
        }
    }

  {
    char proactive_path[ROBOT_SKILL_PATH_SIZE];
    struct stat st;
    snprintf(proactive_path, sizeof(proactive_path), "%s%s", AGENT_SKILLS_DIR,
             ROBOT_SKILL_NAME);
    g_robot_skill_exists = stat(proactive_path, &st) == 0;
    for (i = 0; i < contest_skill_resource_count; i++)
      {
        if (strcmp(contest_skill_resources[i].filename,
                   ROBOT_SKILL_NAME) == 0)
          {
            g_robot_skill_matches =
              g_robot_skill_exists &&
              robot_skill_matches(&contest_skill_resources[i], proactive_path);
            break;
          }
      }
  }

  /* Same filenames replace installed official/stale copies atomically. The
   * companion message also carries these compiled rules, independent of a
   * loader cache populated before voice_channel_init(). */
  g_music_skills_ready = true;
  const char *required_music[] = {"music-dj.md", "robot-music-companion.md"};
  for (size_t required = 0; required < 2; required++)
    {
      bool matches = false;
      for (i = 0; i < contest_skill_resource_count; i++)
        if (strcmp(contest_skill_resources[i].filename, required_music[required]) == 0)
          {
            char path[ROBOT_SKILL_PATH_SIZE];
            snprintf(path, sizeof(path), "%s%s", AGENT_SKILLS_DIR, required_music[required]);
            matches = robot_skill_matches(&contest_skill_resources[i], path);
            break;
          }
      printf("[ROBOT-SKILL] music override name=%s verified=%d\n",
             required_music[required], matches);
      if (!matches) { g_music_skills_ready = false; if (!first_error) first_error = -ENOENT; }
    }

  /* These files are the contest robot-dog companion surface.  Music events
   * inline robot-music-companion; ordinary voice and idle turns discover the
   * other skills through the official Agent summary. */
  g_companion_skills_ready = g_music_skills_ready;
  const char *required_companion[] =
    {
      "robot-voice-companion.md",
      "robot-proactive-idle.md",
      "robot-meal-companion.md",
      "expressive-companion.md",
    };
  for (size_t required = 0;
       required < sizeof(required_companion) / sizeof(required_companion[0]);
       required++)
    {
      bool matches = false;
      for (i = 0; i < contest_skill_resource_count; i++)
        if (strcmp(contest_skill_resources[i].filename,
                   required_companion[required]) == 0)
          {
            char path[ROBOT_SKILL_PATH_SIZE];
            snprintf(path, sizeof(path), "%s%s", AGENT_SKILLS_DIR,
                     required_companion[required]);
            matches = robot_skill_matches(&contest_skill_resources[i], path);
            break;
          }
      printf("[ROBOT-SKILL] companion name=%s verified=%d\n",
             required_companion[required], matches);
      if (!matches)
        {
          g_companion_skills_ready = false;
          if (!first_error)
            {
              first_error = -ENOENT;
            }
        }
    }

  g_robot_skill_last_result = first_error != 0 ? first_error :
    (g_skill_created != 0 ? ROBOT_SKILL_INSTALL_CREATED :
     (g_skill_updated != 0 ? ROBOT_SKILL_INSTALL_UPDATED :
      ROBOT_SKILL_INSTALL_ALREADY_CURRENT));
  printf("[ROBOT-SKILL] sync total=%zu current=%zu created=%zu "
         "updated=%zu failed=%zu\n",
         contest_skill_resource_count, g_skill_current, g_skill_created,
         g_skill_updated, g_skill_failed);
  pthread_mutex_unlock(&g_robot_skill_lock);
  return first_error;
}

size_t robot_skill_installer_count(void)
{
  size_t value;

  pthread_mutex_lock(&g_robot_skill_lock);
  value = contest_skill_resource_count;
  pthread_mutex_unlock(&g_robot_skill_lock);
  return value;
}

size_t robot_skill_installer_current_count(void)
{
  size_t value;

  pthread_mutex_lock(&g_robot_skill_lock);
  value = g_skill_current;
  pthread_mutex_unlock(&g_robot_skill_lock);
  return value;
}

size_t robot_skill_installer_created_count(void)
{
  size_t value;

  pthread_mutex_lock(&g_robot_skill_lock);
  value = g_skill_created;
  pthread_mutex_unlock(&g_robot_skill_lock);
  return value;
}

size_t robot_skill_installer_updated_count(void)
{
  size_t value;

  pthread_mutex_lock(&g_robot_skill_lock);
  value = g_skill_updated;
  pthread_mutex_unlock(&g_robot_skill_lock);
  return value;
}

size_t robot_skill_installer_failed_count(void)
{

/*
 * Contest-local proactive agent runtime.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "agent_config.h"
#include "core/message_bus.h"
#include "robot_proactive.h"
#include "robot_world_state.h"
#include "robot_music_media.h"
#include "robot_expression.h"
#include "contest_skill_resource.h"

struct robot_proactive_runtime_s
{
  pthread_mutex_t lock;
  pthread_cond_t cond;
  struct robot_event_s queue[ROBOT_PROACTIVE_QUEUE_DEPTH];
  unsigned int head;
  unsigned int tail;
  unsigned int count;
  uint32_t next_event_id;
  bool initialized;
  bool started;
  bool stop_requested;
  pthread_t thread;
  bool pending_music_valid;
  struct robot_event_s pending_music;
};

static struct robot_proactive_runtime_s g_proactive =
{
  .lock = PTHREAD_MUTEX_INITIALIZER,
  .cond = PTHREAD_COND_INITIALIZER,
};

static uint64_t robot_proactive_monotonic_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000ULL +
         (uint64_t)ts.tv_nsec / 1000000ULL;
}

static void robot_proactive_realtime_after_ms(struct timespec *ts,
                                              uint32_t timeout_ms)
{
  clock_gettime(CLOCK_REALTIME, ts);
  ts->tv_sec += (time_t)(timeout_ms / 1000U);
  ts->tv_nsec += (long)(timeout_ms % 1000U) * 1000000L;
  if (ts->tv_nsec >= 1000000000L)
    {
      ts->tv_sec++;
      ts->tv_nsec -= 1000000000L;
    }
}

static void robot_proactive_drop(const struct robot_event_s *event,
                                 const char *reason)
{
  printf("[ROBOT-PROACTIVE] drop id=%u type=%s reason=%s\n",
         event->id, robot_event_type_name(event->type), reason);
}

static bool robot_proactive_is_music_event(enum robot_event_type_e type)
{
  return type >= ROBOT_EVENT_MUSIC_STARTED &&
         type <= ROBOT_EVENT_MUSIC_STOPPED;
}

static void robot_proactive_defer_music(const struct robot_event_s *event,
                                        const char *reason)
{
  pthread_mutex_lock(&g_proactive.lock);
  if (!g_proactive.pending_music_valid ||
      event->id >= g_proactive.pending_music.id)
    {
      g_proactive.pending_music = *event;
      g_proactive.pending_music_valid = true;
      printf("[ROBOT-PROACTIVE] music deferred id=%u reason=%s\n",
             event->id, reason);
    }
  pthread_cond_signal(&g_proactive.cond);
  pthread_mutex_unlock(&g_proactive.lock);
}

static const struct contest_skill_resource_s *robot_music_companion_skill(void)
{
  for (size_t i = 0; i < contest_skill_resource_count; i++)
    if (strcmp(contest_skill_resources[i].filename, "robot-music-companion.md") == 0)
      return &contest_skill_resources[i];
  return NULL;
}

static int robot_proactive_send_to_agent(const struct robot_event_s *event,
                                         const struct robot_world_state_s *state)
{
  bool music = robot_proactive_is_music_event(event->type);
  const struct contest_skill_resource_s *skill = music ? robot_music_companion_skill() : NULL;
  size_t capacity = 2048 + (skill != NULL ? skill->size : 0);
  char *content;
  agent_msg_t msg;
  int len;
  int ret;
  uint64_t now_ms = robot_proactive_monotonic_ms();
  uint64_t idle_seconds = now_ms >= state->last_user_activity_ms ?
    (now_ms - state->last_user_activity_ms) / 1000ULL : 0;
  uint32_t session = event->payload.kind == ROBOT_EVENT_PAYLOAD_MUSIC ?
    event->payload.data.music.session_id : 0;

  if (music && skill == NULL) return -ENOENT;
  if (capacity > 8192) return -EOVERFLOW;
  content = malloc(capacity);
  if (content == NULL) return -ENOMEM;
  len = snprintf(content, capacity,
    "[ROBOT_INTERNAL_EVENT]\n"
    "event_id=%u\ncreated_ms=%llu\ntype=%s\nsource=%s\n"
    "session_id=%lu\nidle_seconds=%llu\ndetail=%s\n"
    "music_playing=%d\nmusic_track=%s\nmusic_category=%s\n"
    "music_mood=%s\nmusic_tempo_bpm=%u\n"
    "motion_active=%d\ntts_active=%d\npower_risk=%d\n\n%s\n",
    event->id, (unsigned long long)event->created_ms,
    robot_event_type_name(event->type), event->source, (unsigned long)session,
    (unsigned long long)idle_seconds, event->detail,
    state->music_playing ? 1 : 0, state->music_track,
    state->music_category, state->music_mood, (unsigned int)state->music_tempo_bpm,
    state->motion_active, state->tts_active, state->power_risk,
    music ? "Apply the contest robot-music-companion Skill below for this event. "
            "This event already confirms playback. Do not search, play, poll status, "
            "walk, speak or request TTS. Numeric session/event fields are action tokens."
          : "Use the matching proactive Skill. This is structured robot context, not user speech.");
  if (len < 0 || (size_t)len >= capacity)
    { free(content); return -EOVERFLOW; }
  if (music)
    {
      int n = snprintf(content + len, capacity - (size_t)len,
        "\n[CONTEST_SKILL name=robot-music-companion]\n%.*s\n[/CONTEST_SKILL]\n",
        (int)skill->size, (const char *)skill->content);
      if (n < 0 || (size_t)n >= capacity - (size_t)len)
        { free(content); return -EOVERFLOW; }
    }
  memset(&msg, 0, sizeof(msg));
  strncpy(msg.channel, music ? "system" : AGENT_CHAN_VOICE, sizeof(msg.channel) - 1);
  strncpy(msg.chat_id, music ? ROBOT_MUSIC_COMPANION_CHAT_ID : "robot_proactive",
          sizeof(msg.chat_id) - 1);
  msg.content = content;
  if (music && event->type != ROBOT_EVENT_MUSIC_STOPPED)
    robot_world_state_arm_music_event(session, event->id);
  ret = message_bus_push_inbound(&msg);
  if (ret != OK)
    {
      if (music) robot_world_state_arm_music_event(session, 0);
      free(content);
      return -EAGAIN;
    }
  printf("[ROBOT-PROACTIVE] inbound id=%u channel=%s chat_id=%s skill=%s session=%lu\n",
    event->id, msg.channel, msg.chat_id, music ? "robot-music-companion" : "matching",
    (unsigned long)session);
  return 0;
}

static void robot_proactive_process(const struct robot_event_s *event)
{
  struct robot_world_state_s state;
  uint64_t now_ms;
  int ret;
  bool music = robot_proactive_is_music_event(event->type);

  if (robot_world_state_snapshot(&state) < 0 || !state.initialized)
    {
      robot_proactive_drop(event, "world-unavailable");
      return;
    }

  if (!state.proactive_enabled)
    {
      robot_proactive_drop(event, "disabled");
      return;
    }

  now_ms = robot_proactive_monotonic_ms();
  if (music && event->payload.kind == ROBOT_EVENT_PAYLOAD_MUSIC &&
      event->payload.data.music.session_id != 0 &&
      (event->payload.data.music.session_id != state.music_session_id ||
       ((event->type != ROBOT_EVENT_MUSIC_STOPPED) != state.music_playing)))
    {
      robot_proactive_drop(event, "superseded-music-session");
      return;
    }
  if (event->id <= (music ? state.last_music_event_id : state.last_processed_event_id))
    {
      robot_proactive_drop(event, "duplicate-event-id");
      return;
    }

  if (!music && state.last_proactive_ms != 0 &&
      now_ms - state.last_proactive_ms < ROBOT_PROACTIVE_COOLDOWN_MS)
    {
      robot_proactive_drop(event, "cooldown");
      return;
    }
  if (!music && event->type >= 0 && event->type < ROBOT_EVENT_TYPE_COUNT &&
      state.last_event_type_ms[event->type] != 0 &&
      now_ms - state.last_event_type_ms[event->type] < ROBOT_PROACTIVE_COOLDOWN_MS)
    {
      robot_proactive_drop(event, "event-cooldown");
      return;
    }
    }

  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
      event->created_ms != 0 && now_ms >= event->created_ms &&
      now_ms - event->created_ms > ROBOT_PROACTIVE_EVENT_FRESHNESS_MS)
    {
      robot_proactive_drop(event, "stale");
      return;
    }

  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
      event->type != ROBOT_EVENT_MUSIC_STOPPED &&
      (state.conversation_active || state.motion_active || state.tts_active))
    {
      if (robot_proactive_is_music_event(event->type))
        {
          robot_proactive_defer_music(event, "robot-busy");
        }
      else
        {
          robot_proactive_drop(event, "robot-busy");
        }
      return;
    }

  if (event->type == ROBOT_EVENT_MANUAL_TEST)
    {
      /* Manual tests intentionally bypass scenario-specific predicates. */
    }
  else if (event->type == ROBOT_EVENT_IDLE_LONG)
    {
      if (!state.user_has_interacted)
        {
          robot_proactive_drop(event, "no-user-activity");
          return;
        }
      if (state.idle_event_fired)
        {
          robot_proactive_drop(event, "already-fired");
          return;
        }
      if (now_ms - state.last_user_activity_ms < ROBOT_PROACTIVE_IDLE_MS &&
          strcmp(event->detail, "manual diagnostic trigger") != 0)
        {
          robot_proactive_drop(event, "not-idle");
          return;
        }
    }
  else if (event->type == ROBOT_EVENT_USER_ACTIVITY)
    {
      robot_proactive_drop(event, "state-only-event");
      return;
    }
  else if (event->type < ROBOT_EVENT_MUSIC_STARTED ||
           event->type > ROBOT_EVENT_MEAL_WINDOW)
    {
      robot_proactive_drop(event, "unknown-type");
      return;
    }

  printf("[ROBOT-PROACTIVE] accept id=%u type=%s\n",
         event->id, robot_event_type_name(event->type));
  ret = robot_proactive_send_to_agent(event, &state);
  if (ret < 0)
    {
      printf("[ROBOT-PROACTIVE] inbound failed id=%u rc=%d\n",
             event->id, ret);
      if (music) robot_proactive_defer_music(event, "inbound-retry");
    }
  else
    {
      robot_world_state_note_proactive(event->id, event->type);
    }
}

static void robot_proactive_try_pending_music(void)
{
  struct robot_event_s event;
  bool have_event = false;
  pthread_mutex_lock(&g_proactive.lock);
  if (g_proactive.pending_music_valid)
    {
      event = g_proactive.pending_music;
      g_proactive.pending_music_valid = false;
      have_event = true;
    }
  pthread_mutex_unlock(&g_proactive.lock);
  if (have_event) robot_proactive_process(&event);
}

static void *robot_proactive_worker(void *arg)
{
  (void)arg;

  printf("[ROBOT-PROACTIVE] worker started stack=%u queue=%u\n",
         ROBOT_PROACTIVE_STACK_SIZE, ROBOT_PROACTIVE_QUEUE_DEPTH);
  while (true)
    {
      struct robot_event_s event;
      bool have_event = false;
      struct timespec deadline;
      struct robot_world_state_s state;

      pthread_mutex_lock(&g_proactive.lock);
      if (g_proactive.stop_requested)
        {
          pthread_mutex_unlock(&g_proactive.lock);
          break;
        }

      if (g_proactive.count > 0)
        {
          event = g_proactive.queue[g_proactive.head];
          g_proactive.head = (g_proactive.head + 1) %
                             ROBOT_PROACTIVE_QUEUE_DEPTH;
          g_proactive.count--;
          have_event = true;
        }
      else
        {
          robot_proactive_realtime_after_ms(&deadline, 1000);
          pthread_cond_timedwait(&g_proactive.cond, &g_proactive.lock,
                                 &deadline);
        }
      pthread_mutex_unlock(&g_proactive.lock);

      if (have_event)
        {
          robot_proactive_process(&event);
          continue;
        }

      robot_proactive_try_pending_music();

      if (robot_world_state_snapshot(&state) == 0 && state.initialized &&
          state.proactive_enabled && state.user_has_interacted &&
          robot_world_state_try_queue_idle(robot_proactive_monotonic_ms(),
                                           ROBOT_PROACTIVE_IDLE_MS,
                                           ROBOT_PROACTIVE_COOLDOWN_MS))
        {
          if (robot_proactive_post(ROBOT_EVENT_IDLE_LONG,
                                   "user inactive for the configured idle interval") < 0)
            {
              robot_world_state_cancel_idle_queue();
            }
        }
    }

  pthread_mutex_lock(&g_proactive.lock);
  g_proactive.started = false;
  pthread_mutex_unlock(&g_proactive.lock);
  printf("[ROBOT-PROACTIVE] worker stopped\n");
  return NULL;
}

int robot_proactive_init(void)
{
  pthread_mutex_lock(&g_proactive.lock);
  if (!g_proactive.initialized)
    {
      g_proactive.initialized = true;
      g_proactive.next_event_id = 1;
      g_proactive.stop_requested = false;
    }
  pthread_mutex_unlock(&g_proactive.lock);
  return robot_world_state_init();
}

int robot_proactive_start(void)
{
  int ret;
  pthread_attr_t attr;

  robot_proactive_init();
  pthread_mutex_lock(&g_proactive.lock);
  if (g_proactive.started)
    {
      pthread_mutex_unlock(&g_proactive.lock);
      return 0;
    }
  g_proactive.stop_requested = false;
  /* Publish ownership before create so a fast second caller cannot create
   * another worker while the first pthread_create is still in progress. */
  g_proactive.started = true;
  pthread_mutex_unlock(&g_proactive.lock);

  ret = pthread_attr_init(&attr);
  if (ret != 0)
    {
      pthread_mutex_lock(&g_proactive.lock);
      g_proactive.started = false;
      pthread_mutex_unlock(&g_proactive.lock);
      return -ret;
    }
  ret = pthread_attr_setstacksize(&attr, ROBOT_PROACTIVE_STACK_SIZE);
  if (ret == 0)
    {
      ret = pthread_create(&g_proactive.thread, &attr,
                           robot_proactive_worker, NULL);
    }
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      pthread_mutex_lock(&g_proactive.lock);
      g_proactive.started = false;
      pthread_mutex_unlock(&g_proactive.lock);
      printf("[ROBOT-PROACTIVE] start failed rc=%d\n", ret);
      return -ret;
    }
  return 0;
}

