}

static void cmd_clear_proxy(void)
{
    http_proxy_clear();
    printf("Proxy cleared. Restart to apply.\n");
}

static void cmd_set_wifi(int argc, char** argv)
{
    if (argc < 3) {
        printf("Usage: set_wifi <ssid> <password>\n");
        return;
    }
    printf("Connecting to '%s' ...\n", argv[1]);
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_ROBOT_VOICE
    int voice_token = voice_channel_pause_for_wifi();
    if (voice_token < 0) {
        printf("Cannot stop voice workers: rc=%d\n", voice_token);
        return;
    }
#endif
    int err = network_wifi_connect(NULL, argv[1], argv[2]);
    if (err == OK)
        printf("WiFi connected: %s\n", network_get_ip());
    else
        printf("WiFi failed: rc=%d (%s). Run net_status for the failed stage.\n",
               err, network_wifi_error_name(err));
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_ROBOT_VOICE
    voice_channel_resume_after_wifi(voice_token);
#endif
}

static void cmd_wifi_reconnect(void)
{
    printf("Reconnecting WiFi ...\n");
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_ROBOT_VOICE
    int voice_token = voice_channel_pause_for_wifi();
    if (voice_token < 0) {
        printf("Cannot stop voice workers: rc=%d\n", voice_token);
        return;
    }
#endif
    int err = network_wifi_reconnect();
    if (err == OK)
        printf("Reconnected: %s\n", network_get_ip());
    else if (err == -ENOENT)
        printf("No saved credentials. Use: set_wifi <ssid> <pass>\n");
    else
        printf("WiFi reconnect failed: rc=%d (%s).\n", err, network_wifi_error_name(err));
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_ROBOT_VOICE
    voice_channel_resume_after_wifi(voice_token);
#endif
}

