        else if (strcmp(cmd, "quit") == 0) {
            cmd_quit();
            break;
        } else if (strcmp(cmd, "set_mqtt") == 0)
            cmd_set_mqtt(argc, argv);
        else if (strcmp(cmd, "set_volc_key") == 0)
