    pthread_mutex_lock(&s_chat_id_mutex);
    strncpy(s_last_chat_id, chat_id, sizeof(s_last_chat_id) - 1);
    s_last_chat_id[sizeof(s_last_chat_id) - 1] = '\0';
    pthread_mutex_unlock(&s_chat_id_mutex);
    return OK;
}

int feishu_get_last_chat_id(char* chat_id, size_t chat_id_size)
{
    if (!chat_id || chat_id_size == 0) {
        return ERROR;
    }

    pthread_mutex_lock(&s_chat_id_mutex);
    strncpy(chat_id, s_last_chat_id, chat_id_size - 1);
    chat_id[chat_id_size - 1] = '\0';
    pthread_mutex_unlock(&s_chat_id_mutex);
    return chat_id[0] ? OK : ERROR;
