/**
 * network_manager.h — Vela network status helper
 *
 * managed by the system (netinit / board BSP).  This module simply
 * waits for any non-loopback interface to get an IPv4 address.
 */

#include "agent_compat.h"

/** Check usable interface IPv4/link state; does not prove Internet access. */
bool network_is_connected(void);

/**
 * Block until connected (or timeout).
 * @param timeout_ms  0 = check once, UINT32_MAX = wait forever.
 * @return OK on success, ERROR otherwise.
 */
int network_wait_connected(uint32_t timeout_ms);

/** Return a static string with the first non-loopback IPv4 address. */
const char *network_get_ip(void);

/**
 * Connect through checked WAPI and DHCP APIs with serialized transactions.
 * On QEMU this is a no-op (network is provided by virtio-net).
 * Saves credentials to config_store for persistence across reboots.
 * @param iface  WiFi interface name e.g. "wlan0" (NULL = use "wlan0")
 */
int network_wifi_connect(const char *iface, const char *ssid, const char *pass);

/** Re-connect using credentials saved in config_store (called at startup). */
int network_wifi_reconnect(void);

/** Compatibility wrapper used by contest applications. */
int network_wifi_configure(const char *iface, const char *ssid,
                           const char *pass);

/** Restore the saved Wi-Fi configuration. */
int network_wifi_restore(void);

/** Print a read-only Wi-Fi/network status snapshot. */
void network_wifi_diag(void);

/** Stable diagnostic labels, including legacy generic driver -1. */
const char *network_wifi_error_name(int rc);

/** Resolve a hostname using the system resolver; never overrides DHCP DNS. */
int network_dns_probe(const char *host);

/** Serialize HTTPS request lifecycles across Agent and contest voice paths. */
int network_acquire_http_transport(uint32_t timeout_ms);
void network_release_http_transport(void);

