} net_state_t;

/** Network state change callback */
typedef void (*net_state_cb_t)(net_state_t state, void* arg);

/** Internal network status structure */
typedef struct {
    net_state_t state;
    char ip_addr[INET_ADDRSTRLEN];
    char iface_name[16];
    bool ble_connected;
    int active_conns;
    int iob_usage_pct;
    time_t last_check;
    time_t connected_since;
} net_status_t;

/* Resource constraint macros */
