/**
 * Runs in a background thread: waits for network, then starts all
 * network-dependent services. Main thread is NOT blocked.
 */
static void* network_watch_task(void* arg)
{
    (void)arg;
    syslog(LOG_INFO, "[%s] Network watcher started\n", TAG);

    /* Wait for the ordered startup transaction (or an explicit set_wifi when
     * automatic startup is disabled) before starting network services. */
    syslog(LOG_INFO,
        "[%s] Waiting for Wi-Fi startup transaction before network services\n",
        TAG);
    bool ready = false;
    while (!g_shutdown_requested && !ready) {
        ready = network_wait_connected(1000) == OK;
    }
    if (ready && !g_shutdown_requested) {
#ifdef CONFIG_AI_AGENT_AUTOSTART
        /* Do not let Feishu or Agent services consume the link until the
         * ordered boot transaction has installed all runtime credentials. */
        agent_autostartup_wait_network_release();
#endif
        syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, network_get_ip());

        /* Set the clock before Feishu starts applying its timestamp window. */
        agent_sync_network_time();

#if AGENT_SKILL_SYNC_ENABLED
        /* Sync skills from Bitable before starting agent loop */
        if (skill_sync_from_bitable() != OK) {
            syslog(LOG_WARNING, "[%s] Bitable skill sync failed, using local skills\n", TAG);
        }
#endif

