        notify.content = strdup("网络请求失败，请检查蓝牙连接");
        if (notify.content) {
            if (message_bus_push_outbound(&notify) != OK) {
                free(notify.content);
            }
        }
    }
    return ERROR;
#else
    /* A transient Wi-Fi/TLS reset is common while the Feishu WebSocket is
     * active.  Keep the retry local to the request so the caller can still
     * report a real failure after the bounded attempts are exhausted. */
    int ret = ERROR;
    const int retry_max = 2;

    for (int attempt = 0; attempt <= retry_max; attempt++) {
        if (attempt > 0) {
            unsigned int delay = 1U << (attempt - 1);
            syslog(LOG_WARNING,
                "[llm] HTTP transport retry %d/%d after %us\n",
                attempt, retry_max, delay);
            sleep(delay);
        }

        if (use_tls && http_proxy_is_enabled()) {
            ret = llm_http_via_proxy(post_data, rb, out_status);
        } else {
            ret = llm_http_direct(post_data, rb, out_status);
        }

        if (ret == OK) {
            return OK;
        }

        resp_buf_free(rb);
    }

    syslog(LOG_ERR, "[llm] HTTP transport failed after %d attempts\n",
        retry_max + 1);
    return ret;
#endif
}

