   * while a retry builds a replacement for its unsubmitted suffix. */
  if (!ctx->first_delta_ms) ctx->first_delta_ms = s.first_delta_ms;
  if (ret < 0) robot_voice_llm_stream_hold(ctx->voice);
  rv_llm_sse_destroy(&s);
  return ret;
}

