 44	static int wait_wifi(void)
 45	{
 46	    unsigned int attempt = 0;
 47	
 48	    for (;;) {
 49	        int ret;
 50	
 51	        attempt++;
 52	        syslog(LOG_INFO, "[%s] step=set_wifi attempt=%u\n", TAG, attempt);
 53	        ret = network_wifi_connect(NULL,
 54	            CONFIG_AI_AGENT_AUTOSTART_WIFI_SSID,
 55	            CONFIG_AI_AGENT_AUTOSTART_WIFI_PASSWORD);
 56	        if (ret == OK && network_wait_connected(5000) == OK) {
 57	            syslog(LOG_INFO, "[%s] step=set_wifi ready ip=%s\n", TAG,
 58	                network_get_ip());
 59	            return OK;
 60	        }
 61	
 62	        syslog(LOG_WARNING, "[%s] step=set_wifi failed rc=%d; retrying\n",
 63	            TAG, ret);
 64	        retry_delay();
 65	    }
 66	}
