 68	static int parse_endpoint(const char *endpoint, char *host, size_t host_cap,
 69	    char *path, size_t path_cap)
 70	{
 71	    const char *begin;
 72	    const char *slash;
 73	    size_t host_len;
 74	
 75	    if (!endpoint || !host || host_cap == 0 || !path || path_cap == 0) {
 76	        return -EINVAL;
 77	    }
 78	
 79	    if (strncmp(endpoint, "https://", 8) == 0) {
 80	        begin = endpoint + 8;
 81	    } else if (strncmp(endpoint, "http://", 7) == 0) {
 82	        begin = endpoint + 7;
 83	    } else {
 84	        return -EINVAL;
 85	    }
 86	
 87	    slash = strchr(begin, '/');
 88	    host_len = slash ? (size_t)(slash - begin) : strlen(begin);
 89	    if (host_len == 0 || host_len >= host_cap) {
 90	        return -EINVAL;
 91	    }
 92	
 93	    memcpy(host, begin, host_len);
 94	    host[host_len] = '\0';
 95	
 96	    if (!slash || slash[1] == '\0' || strcmp(slash, "/v1") == 0 ||
 97	        strcmp(slash, "/v1/") == 0) {
 98	        snprintf(path, path_cap, "/v1/chat/completions");
 99	    } else {
100	        if (strlen(slash) >= path_cap) {
101	            return -EINVAL;
102	        }
103	        snprintf(path, path_cap, "%s", slash);
104	    }
105	
106	    return OK;
107	}
