109	static int apply_llm(void)
110	{
111	    char host[128];
112	    char path[256];
113	    llm_backend_t backend;
114	    llm_backend_t applied;
115	    int ret;
116	
117	    ret = parse_endpoint(CONFIG_AI_AGENT_AUTOSTART_LLM_ENDPOINT, host,
118	        sizeof(host), path, sizeof(path));
119	    if (ret < 0) {
120	        return ret;
121	    }
122	
123	    memset(&backend, 0, sizeof(backend));
124	    snprintf(backend.host, sizeof(backend.host), "%s", host);
125	    snprintf(backend.path, sizeof(backend.path), "%s", path);
126	    snprintf(backend.port, sizeof(backend.port), "443");
127	    snprintf(backend.model, sizeof(backend.model), "%s",
128	        CONFIG_AI_AGENT_AUTOSTART_LLM_MODEL);
129	    snprintf(backend.api_key, sizeof(backend.api_key), "%s",
130	        CONFIG_AI_AGENT_AUTOSTART_LLM_API_KEY);
131	    backend.priority = 0;
132	    backend.cost_tier = 1;
133	    backend.enabled = true;
134	
135	    ret = llm_router_set_backend(0, &backend);
136	    if (ret == OK) {
137	        ret = llm_router_apply(0);
138	    }
139	    if (ret != OK || llm_router_get_backend(0, &applied) != OK ||
140	        strcmp(applied.host, backend.host) != 0 ||
141	        strcmp(applied.model, backend.model) != 0 ||
142	        strcmp(applied.path, backend.path) != 0 ||
143	        strcmp(applied.api_key, backend.api_key) != 0) {
144	        return ret == OK ? -EIO : ret;
145	    }
146	
147	    return OK;
148	}
