150	static int wait_llm(void)
151	{
152	    unsigned int attempt = 0;
153	
154	    for (;;) {
155	        int ret;
156	
157	        attempt++;
158	        syslog(LOG_INFO, "[%s] step=set_llm attempt=%u\n", TAG, attempt);
159	        ret = apply_llm();
160	        if (ret == OK) {
161	            syslog(LOG_INFO, "[%s] step=set_llm ready\n", TAG);
162	            return OK;
163	        }
164	
165	        syslog(LOG_WARNING, "[%s] step=set_llm failed rc=%d; retrying\n",
166	            TAG, ret);
167	        retry_delay();
168	    }
169	}
