181	        ret = set_backend(name);
182	        if (ret == OK && get_backend() && strcmp(get_backend(), name) == 0) {
183	            syslog(LOG_INFO, "[%s] step=%s ready\n", TAG, step);
184	            return OK;
185	        }
186	
187	        syslog(LOG_WARNING, "[%s] step=%s failed rc=%d; retrying\n", TAG,
188	            step, ret);
189	        retry_delay();
190	    }
191	}
