245	int agent_autostartup_run(void)
246	{
247	    int ret;
248	
249	    ret = wait_wifi();
250	    if (ret != OK) {
251	        return ret;
252	    }
253	
254	    ret = wait_llm();
255	    if (ret != OK) {
256	        return ret;
257	    }
258	
259	    ret = wait_voice_backend("set_voice_asr",
260	        CONFIG_AI_AGENT_AUTOSTART_ASR_BACKEND,
261	        voice_asr_set_backend, voice_asr_get_backend);
262	    if (ret != OK) {
263	        return ret;
264	    }
265	
266	    ret = wait_voice_backend("set_voice_tts",
267	        CONFIG_AI_AGENT_AUTOSTART_TTS_BACKEND,
268	        voice_tts_set_backend, voice_tts_get_backend);
269	    if (ret != OK) {
270	        return ret;
271	    }
272	
273	    ret = wait_feishu();
274	    if (ret != OK) {
275	        return ret;
276	    }
277	
278	    /* Let the network watcher start Feishu/Agent services only now. */
279	    agent_autostartup_release_network();
280	
281	    return wait_voice_start();
282	}
