284	void agent_autostartup_release_network(void)
285	{
286	    g_network_released = true;
287	}
288	
289	void agent_autostartup_wait_network_release(void)
290	{
291	    while (!g_network_released) {
292	        usleep(100000);
293	    }
294	}
