static const char stream[] =
 ": heartbeat\r\n\r\n"
 "data: {\"id\":\"chat-1\",\"model\":\"mimo-v2.6-flash\",\"created\":123,\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\",\"content\":\"第一句。\"}}]}\r\n\r\n"
 "data: {\"choices\":[{\"index\":0,\"delta\":{\"content\":\"第二句。\",\"tool_calls\":[]},\"finish_reason\":null}]}\n\n"
 "data: {\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"stop\"}]}\n\r\n"
 "data: {\"choices\":[],\"usage\":{\"total_tokens\":12}}\n\n"
 "data: [DONE]\n\n";
static unsigned int callbacks, tool_events;
static char observed[4096];
static void delta(void *arg, const char *p, size_t n, bool tools)
{
 (void)arg;
 if (tools) { tool_events++; return; }
 if (n) { assert(strlen(observed)+n<sizeof(observed)); strncat(observed,p,n);callbacks++; }
}
static void fragmentation(void)
{
 for (size_t stride=1;stride<=strlen(stream);stride++) {
  struct rv_llm_sse_s s; char out[4096];
  callbacks=tool_events=0;observed[0]=0;
  assert(rv_llm_sse_init(&s,sizeof(out)-1,delta,NULL)==0);
  for(size_t i=0;i<strlen(stream);i+=stride) {
   size_t n=strlen(stream)-i;if(n>stride)n=stride;
   assert(rv_llm_sse_feed(stream+i,n,&s)==0);
  }
  assert(rv_llm_sse_finish(&s,out,sizeof(out))==0);
  cJSON *root=cJSON_Parse(out),*choice=cJSON_GetArrayItem(cJSON_GetObjectItem(root,"choices"),0);
  cJSON *message=cJSON_GetObjectItem(choice,"message");
  assert(!strcmp(cJSON_GetObjectItem(message,"content")->valuestring,"第一句。第二句。"));
  assert(!strcmp(cJSON_GetObjectItem(root,"id")->valuestring,"chat-1"));
  assert(cJSON_GetObjectItem(cJSON_GetObjectItem(root,"usage"),"total_tokens")->valueint==12);
  assert(s.first_delta_ms>0);
  assert(callbacks==2&&tool_events==0&&!strcmp(observed,"第一句。第二句。"));
  cJSON_Delete(root);rv_llm_sse_destroy(&s);
 }
}
static void tool_arguments(void)
{
