  "data: {\"choices\":[{\"delta\":{\"reasoning_content\":\"hidden\",\"tool_calls\":[{\"index\":0,\"id\":\"call_A\",\"type\":\"function\",\"function\":{\"name\":\"get_weather\",\"arguments\":\"{\\\"city\\\":\"}}]}}]}\n\n",
  "data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":1,\"id\":\"call_B\",\"type\":\"function\",\"function\":{\"name\":\"robot_move\",\"arguments\":\"{}\"}},{\"index\":0,\"function\":{\"arguments\":\"\\\"北京\\\"}\"}}]}}]}\n\n",
  "data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"tool_calls\"}]}\n\ndata: [DONE]\n\n"};
 struct rv_llm_sse_s s;char out[4096];
 callbacks=tool_events=0;assert(rv_llm_sse_init(&s,sizeof(out)-1,delta,NULL)==0);
 for(size_t i=0;i<sizeof(parts)/sizeof(parts[0]);i++)
  for(size_t j=0;j<strlen(parts[i]);j++)assert(rv_llm_sse_feed(parts[i]+j,1,&s)==0);
 assert(rv_llm_sse_finish(&s,out,sizeof(out))==0);
 cJSON *r=cJSON_Parse(out),*m=cJSON_GetObjectItem(cJSON_GetArrayItem(cJSON_GetObjectItem(r,"choices"),0),"message");
 cJSON *calls=cJSON_GetObjectItem(m,"tool_calls");assert(cJSON_GetArraySize(calls)==2);
 cJSON *f=cJSON_GetObjectItem(cJSON_GetArrayItem(calls,0),"function");
 assert(!strcmp(cJSON_GetObjectItem(f,"arguments")->valuestring,"{\"city\":\"北京\"}"));
 assert(s.first_delta_ms>0);
 assert(callbacks==0&&tool_events==2);
 assert(!strcmp(cJSON_GetObjectItem(m,"reasoning_content")->valuestring,"hidden"));
 cJSON_Delete(r);rv_llm_sse_destroy(&s);
}
static void failures(void)
{
