  "data: {\"choices\":[{\"index\":1,\"delta\":{\"content\":\"wrong-choice\"}}]}\n\n",
  "data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":-1}]}}]}\n\n",
  "data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":16}]}}]}\n\n",
  "data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0}]},\"finish_reason\":\"tool_calls\"}]}\n\ndata: [DONE]\n\n",
  "data: {\"choices\":[{\"delta\":{\"content\":\"x\"},\"finish_reason\":\"content_filter\"}]}\n\n",
 };
 for(size_t i=0;i<sizeof(bad)/sizeof(bad[0]);i++) {
  struct rv_llm_sse_s s;char out[4096]="old";int rc;
  assert(rv_llm_sse_init(&s,sizeof(out)-1,NULL,NULL)==0);
  rc=rv_llm_sse_feed(bad[i],strlen(bad[i]),&s);
  assert(rc<0||rv_llm_sse_finish(&s,out,sizeof(out))<0);
  rv_llm_sse_destroy(&s);
 }
 struct rv_llm_sse_s s;char small[8]="old";
 assert(rv_llm_sse_init(&s,4095,NULL,NULL)==0);
 assert(rv_llm_sse_feed(stream,strlen(stream),&s)==0);
 assert(rv_llm_sse_finish(&s,small,sizeof(small))==-EOVERFLOW&&small[0]==0);
 rv_llm_sse_destroy(&s);
 char *large=malloc(ROBOT_VOICE_LLM_SSE_MAX+1);memset(large,'x',ROBOT_VOICE_LLM_SSE_MAX+1);
 assert(rv_llm_sse_init(&s,4095,NULL,NULL)==0);
 assert(rv_llm_sse_feed(large,ROBOT_VOICE_LLM_SSE_MAX+1,&s)==-EOVERFLOW);
 free(large);rv_llm_sse_destroy(&s);
}
static void text_limit(void)
{
 for(size_t n=ROBOT_VOICE_TEXT_CAP-1;n<=ROBOT_VOICE_TEXT_CAP;n++) {
  char *text=malloc(n+1);assert(text);memset(text,'a',n);text[n]=0;
  cJSON *r=cJSON_Parse("{\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}");
  cJSON *d=cJSON_GetObjectItem(cJSON_GetArrayItem(cJSON_GetObjectItem(r,"choices"),0),"delta");
  assert(cJSON_AddStringToObject(d,"content",text));
  char *j=cJSON_PrintUnformatted(r);assert(j);
  size_t cap=strlen(j)+32;char *frame=malloc(cap),out[8192];assert(frame);
  snprintf(frame,cap,"data: %s\n\ndata: [DONE]\n\n",j);
  struct rv_llm_sse_s s;assert(rv_llm_sse_init(&s,sizeof(out)-1,NULL,NULL)==0);
  int rc=rv_llm_sse_feed(frame,strlen(frame),&s);
  if(n<ROBOT_VOICE_TEXT_CAP){assert(rc==0);assert(rv_llm_sse_finish(&s,out,sizeof(out))==0);}
  else assert(rc==-EOVERFLOW);
  free(text);free(j);free(frame);cJSON_Delete(r);rv_llm_sse_destroy(&s);
 }
}
