492	static int llm_http_via_proxy(const char* post_data, resp_buf_t* rb,
493	    int* out_status)
494	{
495	    /* Snapshot config under lock */
496	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
497	    pthread_mutex_lock(&s_llm_lock);
498	    memcpy(api_key, s_api_key, sizeof(api_key));
499	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
500	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
501	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
502	    memcpy(model, s_model, sizeof(model));
503	    pthread_mutex_unlock(&s_llm_lock);
504	
505	    int port = atoi(llm_port);
506	    if (port <= 0)
507	        port = 443;
508	
509	    proxy_conn_t* conn = proxy_conn_open(llm_host, port, 30000);
510	    if (!conn)
511	        return ERROR;
512	
513	    int body_len = (int)strlen(post_data);
514	    char auth_header[256];
515	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
516	
517	    /* Extract provider ID from model (e.g. "xiaomi/mimo-claw-0301" → "xiaomi") */
518	    char provider_hdr[128] = { 0 };
519	    const char* slash = strchr(model, '/');
520	    if (slash) {
521	        char provider[64] = { 0 };
522	        size_t plen = (size_t)(slash - model);
523	        if (plen >= sizeof(provider))
524	            plen = sizeof(provider) - 1;
525	        memcpy(provider, model, plen);
526	        snprintf(provider_hdr, sizeof(provider_hdr), "X-Model-Provider-Id: %s\r\n",
527	            provider);
528	    }
529	
530	    char header[1024];
531	    int hlen = snprintf(header, sizeof(header),
532	        "POST %s HTTP/1.1\r\n"
533	        "Host: %s\r\n"
534	        "Content-Type: application/json\r\n"
535	        "Authorization: %s\r\n"
536	        "%s"
537	        "Content-Length: %d\r\n"
538	        "Connection: close\r\n\r\n",
539	        llm_path, llm_host, auth_header, provider_hdr, body_len);
540	
541	    if (proxy_conn_write(conn, header, hlen) < 0 || proxy_conn_write(conn, post_data, body_len) < 0) {
542	        proxy_conn_close(conn);
543	        return ERROR;
544	    }
545	
546	    if (resp_buf_init(rb, AGENT_LLM_STREAM_BUF_SIZE) != OK) {
547	        proxy_conn_close(conn);
548	        return ERROR;
549	    }
550	
551	    char tmp[4096];
552	    while (1) {
553	        int n = proxy_conn_read(conn, tmp, sizeof(tmp), 120000);
554	        if (n <= 0)
555	            break;
556	        if (resp_buf_append(rb, tmp, (size_t)n) != OK) {
557	            syslog(LOG_ERR, "[%s] resp_buf_append OOM, truncating\n", TAG);
558	            break;
559	        }
560	    }
561	    proxy_conn_close(conn);
562	
563	    /* Parse status from raw HTTP response */
564	    *out_status = 0;
565	    if (rb->len > 5 && strncmp(rb->data, "HTTP/", 5) == 0) {
566	        const char* sp = strchr(rb->data, ' ');
567	        if (sp)
568	            *out_status = atoi(sp + 1);
569	    }
570	
571	    /* Strip HTTP header, keep body */
572	    char* body = strstr(rb->data, "\r\n\r\n");
573	    if (body) {
574	        body += 4;
575	        size_t blen = rb->len - (size_t)(body - rb->data);
576	        memmove(rb->data, body, blen);
577	        rb->len = blen;
578	        rb->data[rb->len] = '\0';
579	    }
580	
581	    return OK;
582	}
