584	int llm_http_call(const char* post_data, resp_buf_t* rb,
585	    int* out_status)
586	{
587	    /* For plain HTTP endpoints (port != 443), always use direct path.
588	     * The proxy does CONNECT + TLS which fails on non-TLS endpoints.
589	     * Non-TLS HTTP endpoints (port != 443) are reachable
590	     * directly without a proxy anyway. */
591	    int use_tls;
592	    pthread_mutex_lock(&s_llm_lock);
593	    use_tls = (strcmp(s_llm_port, "443") == 0);
594	    pthread_mutex_unlock(&s_llm_lock);
595	
596	#ifdef CONFIG_AI_AGENT_NET_RPMSG
597	    int retry_max = network_get_retry_max();
598	    int retry_base = network_get_retry_base_sec();
599	    int ret = ERROR;
600	
601	    for (int attempt = 0; attempt <= retry_max; attempt++) {
602	        if (attempt > 0) {
603	            /* Check network state before retrying */
604	            if (network_get_state() != NET_STATE_CONNECTED) {
605	                syslog(LOG_WARNING, "[llm] Network down, skip retry %d\n", attempt);
606	                break;
607	            }
608	            int delay = retry_base * (1 << (attempt - 1));
609	            syslog(LOG_INFO, "[llm] Retry %d/%d after %ds\n", attempt, retry_max, delay);
610	            sleep(delay);
611	        }
612	
613	        if (use_tls && http_proxy_is_enabled()) {
614	            ret = llm_http_via_proxy(post_data, rb, out_status);
615	        } else {
616	            ret = llm_http_direct(post_data, rb, out_status);
617	        }
618	
619	        if (ret == OK) {
620	            return OK;
621	        }
622	
623	        if (ret == -EPROTO || ret == -EOVERFLOW) {
624	            resp_buf_free(rb);
625	            return ret;
626	        }
627	
628	        syslog(LOG_WARNING, "[llm] HTTP call failed (attempt %d/%d)\n",
629	            attempt + 1, retry_max + 1);
630	    }
631	
632	    /* All retries failed — notify user */
633	    syslog(LOG_ERR, "[llm] All %d retries failed\n", retry_max + 1);
634	    {
635	        agent_msg_t notify;
636	        memset(&notify, 0, sizeof(notify));
637	        strncpy(notify.channel, "cli", sizeof(notify.channel) - 1);
638	        notify.content = strdup("网络请求失败，请检查蓝牙连接");
639	        if (notify.content) {
640	            if (message_bus_push_outbound(&notify) != OK) {
641	                free(notify.content);
642	            }
643	        }
644	    }
645	    return ERROR;
646	#else
647	    /* A transient Wi-Fi/TLS reset is common while the Feishu WebSocket is
648	     * active.  Keep the retry local to the request so the caller can still
649	     * report a real failure after the bounded attempts are exhausted. */
650	    int ret = ERROR;
651	    const int retry_max = 2;
652	
653	    for (int attempt = 0; attempt <= retry_max; attempt++) {
654	        if (attempt > 0) {
655	            unsigned int delay = 1U << (attempt - 1);
656	            syslog(LOG_WARNING,
657	                "[llm] HTTP transport retry %d/%d after %us\n",
658	                attempt, retry_max, delay);
659	            sleep(delay);
660	        }
661	
662	        if (use_tls && http_proxy_is_enabled()) {
663	            ret = llm_http_via_proxy(post_data, rb, out_status);
664	        } else {
665	            ret = llm_http_direct(post_data, rb, out_status);
666	        }
667	
668	        if (ret == OK) {
669	            return OK;
670	        }
671	
672	        if (ret == -EPROTO || ret == -EOVERFLOW) {
673	            resp_buf_free(rb);
674	            return ret;
675	        }
676	
677	        resp_buf_free(rb);
678	    }
679	
680	    syslog(LOG_ERR, "[llm] HTTP transport failed after %d attempts\n",
681	        retry_max + 1);
682	    return ret;
683	#endif
684	}
