 43	  robot_voice_retry_cancel_t cancelled, void *cancel_arg,
 44	  unsigned int *retries_out)
 45	{
 46	  unsigned long long start, deadline;
 47	  unsigned int retry;
 48	
 49	  if (retries_out) *retries_out = 0;
 50	  if (!robot_voice_retryable(last_result) || !attempt) return last_result;
 51	  start = robot_voice_retry_now_ms();
 52	  deadline = start + ROBOT_VOICE_RETRY_BUDGET_MS;
 53	
 54	  for (retry = 1; retry <= ROBOT_VOICE_RETRY_MAX; retry++)
 55	    {
 56	      unsigned long long now;
 57	      unsigned int delay = ROBOT_VOICE_RETRY_DELAY_MS * retry;
 58	      if (cancelled && cancelled(cancel_arg)) return -ECANCELED;
 59	      now = robot_voice_retry_now_ms();
 60	      if (now >= deadline) break;
 61	      if (delay > deadline - now) delay = (unsigned int)(deadline - now);
 62	
 63	      while (robot_voice_retry_now_ms() - now < delay)
 64	        {
 65	          struct timespec nap = { .tv_sec = 0, .tv_nsec = 20000000L };
 66	          unsigned long long current = robot_voice_retry_now_ms();
 67	          if (cancelled && cancelled(cancel_arg)) return -ECANCELED;
 68	          if (current >= deadline || current - now >= delay) break;
 69	          if (deadline - current < 20) nap.tv_nsec = (long)(deadline - current) * 1000000L;
 70	          (void)nanosleep(&nap, NULL);
