 72	
 73	      now = robot_voice_retry_now_ms();
 74	      if (cancelled && cancelled(cancel_arg)) return -ECANCELED;
 75	      if (now >= deadline) break;
 76	      last_result = attempt(attempt_arg, (unsigned int)(deadline - now));
 77	      if (retries_out) *retries_out = retry;
 78	      if (last_result == 0 || !robot_voice_retryable(last_result)) return last_result;
