@@ -592,36 +796,46 @@ sta…26228 tokens truncated…g->desc));

  for (i = 0; i < words; i++)
    {
      if (xfer->raw[i] == CONTEST_I2S_RX_DMA_SENTINEL)
        {
          diag->untouched_words++;
          untouched_run++;
          if (untouched_run > diag->longest_untouched_run)
            {
              diag->longest_untouched_run = untouched_run;
            }
        }
      else
        {
