  2733	                 "next=NULL\n",
  2734	                 slot, wire_bytes, terminal_short ? 1 : 0);
  2735	        }
  2736	    }
  2737	
  2738	  flags = spin_lock_irqsave(&priv->lock);
  2739	  if (!priv->streaming)
  2740	    {
  2741	      priv->reserved = false;
  2742	      spin_unlock_irqrestore(&priv->lock, flags);
  2743	      apb_free(apb);
  2744	      syslog(LOG_INFO, "[C-I2S-DIAG] send canceled after bind\n");
  2745	      return -ECANCELED;
  2746	    }
  2747	
  2748	  xfer->next = NULL;
  2749	  xfer->apb = apb;
  2750	  xfer->callback = callback;
  2751	  xfer->arg = arg;
  2752	  xfer->nbytes = wire_bytes;
  2753	  xfer->result = -EINPROGRESS;
  2754	  xfer->done_queued = false;
  2755	  xfer->terminal = terminal;
  2756	  xfer->in_use = true;
  2757	
  2758	  priv->fill_index++;
  2759	  if (priv->fill_index >= priv->ring_slots)
  2760	    {
  2761	      priv->fill_index = 0;
  2762	    }
  2763	
  2764	  priv->queued_slots++;
  2765	  if (priv->queued_slots > priv->max_queued_slots)
  2766	    {
  2767	      priv->max_queued_slots = priv->queued_slots;
  2768	    }
  2769	
  2770	  priv->submit_count++;
  2771	
  2772	  /* Freeze and start only after all private DMA slots are initialised. */
  2773	  if (!priv->hw_running &&
  2774	      (priv->bound_slots == priv->ring_slots || terminal))
  2775	    {
  2776	      ret = contest_i2s_tx_link_immutable_ring(priv, terminal);
  2777	      if (ret < 0)
  2778	        {
  2779	          xfer->in_use = false;
  2780	          xfer->apb = NULL;
  2781	          xfer->callback = NULL;
  2782	          xfer->arg = NULL;
  2783	          xfer->nbytes = 0;
  2784	          if (priv->queued_slots > 0)
  2785	            {
  2786	              priv->queued_slots--;
  2787	            }
  2788	
  2789	          priv->reserved = false;
  2790	          spin_unlock_irqrestore(&priv->lock, flags);
  2791	          apb_free(apb);
  2792	          syslog(LOG_INFO, "[C-I2S-DIAG] send rejected immutable link rc=%d\n",
  2793	                 ret);
  2794	          return ret;
  2795	        }
  2796	
  2797	      contest_i2s_tx_start_ring(priv);
  2798	    }
  2799	
  2800	  priv->reserved = false;
  2801	  spin_unlock_irqrestore(&priv->lock, flags);
  2802	
  2803	  return OK;
  2804	
  2805	fail_reserved:
  2806	  flags = spin_lock_irqsave(&priv->lock);
  2807	  priv->reserved = false;
  2808	  spin_unlock_irqrestore(&priv->lock, flags);
  2809	  apb_free(apb);
  2810	  syslog(LOG_INFO, "[C-I2S-DIAG] send failed bind rc=%d\n", ret);
  2811	  return ret;
  2812	}
