2330	
2331	static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
2332	{
2333	  FAR struct contest_i2s_tx_s *priv = arg;
2334	  FAR struct contest_i2s_xfer_s *xfer;
2335	  uint32_t status;
2336	  unsigned int slot;
2337	  unsigned int i;
2338	  bool schedule = false;
2339	  bool terminal_stop_schedule = false;
2340	  bool fatal = false;
2341	  irqstate_t flags;
2342	
2343	  (void)irq;
2344	  (void)context;
2345	
2346	  /* OUT_DONE is the per-descriptor completion event for the sequential ring. */
2347	  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
2348	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
2349	
2350	  if ((status & (DMA_OUT_DONE_CH0_INT_ST |
2351	                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
2352	    {
2353	      return OK;
2354	    }
2355	
2356	  flags = spin_lock_irqsave(&priv->lock);
2357	  priv->irq_status = status;
2358	
2359	  if (!priv->streaming || !priv->hw_running)
2360	    {
2361	      spin_unlock_irqrestore(&priv->lock, flags);
2362	      return OK;
2363	    }
2364	
2365	  if ((status & DMA_OUT_DSCR_ERR_CH0_INT_ST) != 0)
2366	    {
2367	      fatal = true;
2368	    }
2369	  else
2370	    {
2371	      /* The descriptor ring is immutable and advances in slot order.  Its
2372	       * payload remains stable until the deferred callback below runs; do not
2373	       * wait one extra ring block and replay stale PCM. */
2374	      if ((status & DMA_OUT_DONE_CH0_INT_ST) != 0)
2375	        {
2376	          priv->done_irq_count++;
2377	
2378	          bool terminal_done;
2379	
2380	          slot = priv->done_index;
2381	          terminal_done = priv->xfer[slot].terminal;
2382	
2383	          if (terminal_done)
2384	            {
2385	              /*
2386	               * OUT_DONE means GDMA finished the descriptor, but the I2S FIFO
2387	               * / shifter may still contain the final samples. Do not stop HW
2388	               * or publish the terminal callback until the drain delay passes.
2389	               */
2390	              priv->streaming = false;
2391	              priv->terminal_stop_pending = true;
2392	              priv->terminal_stop_slot = (uint8_t)slot;
2393	              terminal_stop_schedule = true;
2394	            }
2395	          else if (contest_i2s_tx_complete_slot(priv, slot))
2396	            {
2397	              schedule = true;
2398	            }
2399	
2400	          priv->done_index = (slot + 1) % priv->ring_slots;
2401	          if (slot + 1 == priv->ring_slots)
2402	            {
2403	              priv->ring_wrap_count++;
2404	            }
2405	
2406	        }
2407	
2408	    }
2409	
2410	  if (fatal)
2411	    {
2412	      for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
2413	        {
2414	          xfer = &priv->xfer[i];
2415	          if (xfer->in_use && !xfer->done_queued)
2416	            {
2417	              xfer->result = -EIO;
2418	              xfer->done_queued = true;
2419	              contest_i2s_tx_done_push(priv, xfer);
2420	              schedule = true;
2421	            }
2422	        }
2423	
2424	      priv->queued_slots = 0;
2425	      priv->streaming = false;
2426	      priv->terminal_stop_pending = false;
2427	      contest_i2s_tx_stop_hw(priv);
2428	    }
2429	
2430	  if (terminal_stop_schedule)
2431	    {
2432	      if (work_available(&priv->tx_stop_work))
2433	        {
2434	          work_queue(HPWORK, &priv->tx_stop_work,
2435	                     contest_i2s_tx_terminal_stop_worker, priv,
2436	                     MSEC2TICK(CONTEST_I2S_TX_FIFO_DRAIN_MS));
2437	        }
2438	      else
2439	        {
2440	          /* Defensive fallback: never leave I2S running forever. */
2441	          priv->terminal_stop_pending = false;
2442	          contest_i2s_tx_stop_hw(priv);
2443	          if (contest_i2s_tx_complete_slot(priv, priv->terminal_stop_slot))
2444	            {
2445	              schedule = true;
2446	            }
2447	          syslog(LOG_ERR,
2448	                 "[C-I2S] terminal drain worker busy; immediate fallback\n");
2449	        }
2450	    }
2451	
2452	  if (schedule && work_available(&priv->tx_work))
2453	    {
2454	      /*
2455	       * Normal OUT_DONE callbacks are immediate.  Keeping the old 8 ms delay
2456	       * here increased refill latency and let the cyclic DMA ring run ahead of
2457	       * the logical producer near EOF.  Terminal FIFO drain is handled only by
2458	       * tx_stop_work above.
2459	       */
2460	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
2461	    }
2462	
2463	  spin_unlock_irqrestore(&priv->lock, flags);
2464	  return OK;
2465	}
