2553	
2554	static int contest_i2s_send_locked(FAR struct i2s_dev_s *dev,
2555	                            FAR struct ap_buffer_s *apb,
2556	                            i2s_callback_t callback, FAR void *arg,
2557	                            uint32_t timeout)
2558	{
2559	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
2560	  FAR struct contest_i2s_xfer_s *xfer;
2561	  unsigned int slot;
2562	  size_t nbytes;
2563	  size_t wire_bytes;
2564	  bool need_bind;
2565	  bool terminal_short;
2566	  bool terminal;
2567	  bool was_streaming;
2568	  bool was_reserved;
2569	  bool slot_in_use;
2570	  bool slot_done_queued;
2571	  irqstate_t flags;
2572	  int ret = OK;
2573	
2574	  (void)timeout;
2575	
2576	  if (apb == NULL || callback == NULL || apb->samp == NULL)
2577	    {
2578	      syslog(LOG_INFO, "[C-I2S-DIAG] send rejected invalid argument\n");
2579	      return -EINVAL;
2580	    }
2581	
2582	  if (apb->nbytes < apb->curbyte)
2583	    {
2584	      syslog(LOG_INFO, "[C-I2S-DIAG] send rejected curbyte beyond nbytes\n");
2585	      return -EINVAL;
2586	    }
2587	
2588	  nbytes = apb->nbytes - apb->curbyte;
2589	  {
2590	    size_t expected = CONTEST_I2S_TX_SLOT_BYTES;
2591	    size_t align = sizeof(uint32_t);
2592	
2593	    if (priv->logical_width == 16)
2594	      {
2595	        expected /= 2;
2596	        align = sizeof(int16_t);
2597	      }
2598	
2599	    if (nbytes == 0 || nbytes > expected || (nbytes % align) != 0)
2600	      {
2601	        syslog(LOG_ERR,
2602	               "[C-I2S] reject bytes=%zu max=%zu align=%zu\n",
2603	               nbytes, expected, align);
2604	        return -EINVAL;
2605	      }
2606	
2607	    terminal_short = nbytes < expected;
2608	    terminal = terminal_short || (apb->flags & AUDIO_APB_FINAL) != 0;
2609	    wire_bytes = priv->logical_width == 16 ? nbytes * 2 : nbytes;
2610	
2611	    if (wire_bytes == 0 || wire_bytes > CONTEST_I2S_TX_SLOT_BYTES ||
2612	        (wire_bytes & 3) != 0)
2613	      {
2614	        syslog(LOG_ERR,
2615	               "[C-I2S] reject wire bytes=%zu max=%u\n",
2616	               wire_bytes, CONTEST_I2S_TX_SLOT_BYTES);
2617	        return -EINVAL;
2618	      }
2619	  }
2620	
2621	  apb_reference(apb);
2622	
2623	  flags = spin_lock_irqsave(&priv->lock);
2624	  if (!priv->streaming || priv->reserved)
2625	    {
2626	      was_streaming = priv->streaming;
2627	      was_reserved = priv->reserved;
2628	      spin_unlock_irqrestore(&priv->lock, flags);
2629	      apb_free(apb);
2630	      syslog(LOG_INFO, "[C-I2S-DIAG] send rejected busy streaming=%d reserved=%d\n",
2631	             was_streaming ? 1 : 0, was_reserved ? 1 : 0);
2632	      return -EBUSY;
2633	    }
2634	
2635	  slot = priv->fill_index;
2636	  xfer = &priv->xfer[slot];
2637	
2638	  if (xfer->in_use || xfer->done_queued)
2639	    {
2640	      slot_in_use = xfer->in_use;
2641	      slot_done_queued = xfer->done_queued;
2642	      spin_unlock_irqrestore(&priv->lock, flags);
2643	      apb_free(apb);
2644	      syslog(LOG_INFO,
2645	             "[C-I2S-DIAG] send rejected slot=%u in_use=%d done_queued=%d\n",
2646	             slot, slot_in_use ? 1 : 0, slot_done_queued ? 1 : 0);
2647	      return -EBUSY;
2648	    }
2649	
2650	  need_bind = !xfer->dma_bound;
2651	
2652	  if (need_bind && priv->hw_running)
2653	    {
2654	      spin_unlock_irqrestore(&priv->lock, flags);
2655	      apb_free(apb);
2656	      syslog(LOG_INFO, "[C-I2S-DIAG] send rejected bind while hw_running\n");
2657	      return -EIO;
2658	    }
2659	
2660	  priv->reserved = true;
2661	  spin_unlock_irqrestore(&priv->lock, flags);
2662	
2663	  if (need_bind)
2664	    {
2665	      ret = contest_i2s_tx_bind_slot(priv, slot, apb, wire_bytes, terminal);
2666	      if (ret < 0)
2667	        {
2668	          goto fail_reserved;
2669	        }
2670	
2671	      if (!terminal)
2672	        {
2673	          ret = contest_i2s_tx_bind_silence_slots(priv);
2674	          if (ret < 0)
2675	            {
2676	              goto fail_reserved;
2677	            }
2678	        }
2679	    }
2680	  else
2681	    {
2682	      uint32_t queued;
2683	
2684	      /* Normal requests retain the existing cyclic descriptor.  A short or
2685	       * AUDIO_APB_FINAL request is finite: rebuild this completed descriptor
2686	       * with its exact length and next=NULL so hardware cannot wrap to stale
2687	       * audio or synthetic padding. */
2688	      if (priv->logical_width == 16)
2689	        {
2690	          FAR const int16_t *src =
2691	            (FAR const int16_t *)(apb->samp + apb->curbyte);
2692	          FAR uint32_t *dst = (FAR uint32_t *)xfer->dma_data;
2693	          unsigned int i;
2694	
2695	          for (i = 0; i < wire_bytes / sizeof(uint32_t); i++)
2696	            {
2697	              dst[i] = ((uint32_t)(int32_t)src[i]) << 16;
2698	            }
2699	        }
2700	      else
2701	        {
2702	          memcpy(xfer->dma_data, apb->samp + apb->curbyte, wire_bytes);
2703	        }
2704	
2705	      up_clean_dcache((uintptr_t)xfer->dma_data,
2706	                      (uintptr_t)xfer->dma_data + wire_bytes);
2707	
2708	      if (terminal)
2709	        {
2710	          memset(xfer->desc, 0, sizeof(xfer->desc));
2711	          queued = esp32s3_dma_setup(xfer->desc,
2712	                                     CONTEST_I2S_DMA_DESC_COUNT,
2713	                                     xfer->dma_data, wire_bytes,
2714	                                     true, priv->dma_channel);
2715	          if (queued != wire_bytes)
2716	            {
2717	              ret = -ENOMEM;
2718	              goto fail_reserved;
2719	            }
2720	
2721	          ret = contest_i2s_tx_desc_last(xfer, NULL);
2722	          if (ret < 0)
2723	            {
2724	              goto fail_reserved;
2725	            }
2726	
2727	          xfer->desc[xfer->desc_last].next = NULL;
2728	          up_clean_dcache((uintptr_t)xfer->desc,
2729	                          (uintptr_t)xfer->desc + sizeof(xfer->desc));
2730	
2731	          syslog(LOG_INFO,
2732	                 "[C-I2S] tx terminal slot=%u wire_bytes=%zu short=%d "
2733	                 "next=NULL\n",
2734	                 slot, wire_bytes, terminal_short ? 1 : 0);
2735	        }
2736	    }
2737	
2738	  flags = spin_lock_irqsave(&priv->lock);
2739	  if (!priv->streaming)
2740	    {
2741	      priv->reserved = false;
2742	      spin_unlock_irqrestore(&priv->lock, flags);
2743	      apb_free(apb);
2744	      syslog(LOG_INFO, "[C-I2S-DIAG] send canceled after bind\n");
2745	      return -ECANCELED;
2746	    }
2747	
2748	  xfer->next = NULL;
2749	  xfer->apb = apb;
2750	  xfer->callback = callback;
2751	  xfer->arg = arg;
2752	  xfer->nbytes = wire_bytes;
2753	  xfer->result = -EINPROGRESS;
2754	  xfer->done_queued = false;
2755	  xfer->terminal = terminal;
2756	  xfer->in_use = true;
2757	
2758	  priv->fill_index++;
2759	  if (priv->fill_index >= priv->ring_slots)
2760	    {
2761	      priv->fill_index = 0;
2762	    }
2763	
2764	  priv->queued_slots++;
2765	  if (priv->queued_slots > priv->max_queued_slots)
2766	    {
2767	      priv->max_queued_slots = priv->queued_slots;
2768	    }
2769	
2770	  priv->submit_count++;
2771	
2772	  /* Freeze and start only after all private DMA slots are initialised. */
2773	  if (!priv->hw_running &&
2774	      (priv->bound_slots == priv->ring_slots || terminal))
2775	    {
2776	      ret = contest_i2s_tx_link_immutable_ring(priv, terminal);
2777	      if (ret < 0)
2778	        {
2779	          xfer->in_use = false;
2780	          xfer->apb = NULL;
2781	          xfer->callback = NULL;
2782	          xfer->arg = NULL;
2783	          xfer->nbytes = 0;
2784	          if (priv->queued_slots > 0)
2785	            {
2786	              priv->queued_slots--;
2787	            }
2788	
2789	          priv->reserved = false;
2790	          spin_unlock_irqrestore(&priv->lock, flags);
2791	          apb_free(apb);
2792	          syslog(LOG_INFO, "[C-I2S-DIAG] send rejected immutable link rc=%d\n",
2793	                 ret);
2794	          return ret;
2795	        }
2796	
2797	      contest_i2s_tx_start_ring(priv);
2798	    }
2799	
2800	  priv->reserved = false;
2801	  spin_unlock_irqrestore(&priv->lock, flags);
2802	
2803	  return OK;
2804	
2805	fail_reserved:
2806	  flags = spin_lock_irqsave(&priv->lock);
2807	  priv->reserved = false;
2808	  spin_unlock_irqrestore(&priv->lock, flags);
2809	  apb_free(apb);
2810	  syslog(LOG_INFO, "[C-I2S-DIAG] send failed bind rc=%d\n", ret);
2811	  return ret;
2812	}
