2816	/* Serialize payload copies against STOP/free and START/reallocation. */
2817	
2818	static int contest_i2s_send(FAR struct i2s_dev_s *dev,
2819	                            FAR struct ap_buffer_s *apb,
2820	                            i2s_callback_t callback, FAR void *arg,
2821	                            uint32_t timeout)
2822	{
