2836	static int contest_i2s_tx_ioctl_locked(FAR struct i2s_dev_s *dev, int cmd,
2837	                                unsigned long arg)
2838	{
2839	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
2840	  FAR struct contest_i2s_xfer_s *xfer;
2841	  unsigned int i;
2842	  bool schedule = false;
2843	  irqstate_t flags;
2844	  int ret;
2845	
2846	  syslog(LOG_INFO, "[C-I2S-DIAG] ioctl cmd=0x%x arg=0x%lx\n",
2847	         cmd, arg);
2848	
2849	  switch (cmd)
2850	    {
2851	      case AUDIOIOC_START:
2852	        flags = spin_lock_irqsave(&priv->lock);
2853	        if (priv->streaming || priv->hw_running || priv->reserved ||
2854	            priv->callbacks_pending != 0 || priv->done_head != NULL ||
2855	            !work_available(&priv->tx_stop_work))
2856	          {
2857	            spin_unlock_irqrestore(&priv->lock, flags);
2858	            syslog(LOG_INFO,
2859	                   "[C-I2S-DIAG] ioctl START rejected busy streaming=%d "
2860	                   "hw_running=%d done_head=%p\n",
2861	                   priv->streaming ? 1 : 0, priv->hw_running ? 1 : 0,
2862	                   priv->done_head);
2863	            return -EBUSY;
2864	          }
2865	
2866	        spin_unlock_irqrestore(&priv->lock, flags);
2867	        contest_i2s_tx_reset_fifo();
2868	        ret = contest_i2s_tx_alloc_dma_slots(priv);
2869	        if (ret < 0)
2870	          {
2871	            syslog(LOG_ERR,
2872	                   "[C-I2S] tx private DMA allocation failed bytes=%u\n",
2873	                   priv->requested_slots * CONTEST_I2S_TX_SLOT_BYTES);
2874	            syslog(LOG_INFO, "[C-I2S-DIAG] ioctl START allocation rc=%d\n",
2875	                   ret);
2876	            return ret;
2877	          }
2878	
2879	        flags = spin_lock_irqsave(&priv->lock);
2880	        if (priv->streaming || priv->hw_running || priv->reserved ||
2881	            priv->callbacks_pending != 0 || priv->done_head != NULL ||
2882	            !work_available(&priv->tx_stop_work))
2883	          {
2884	            spin_unlock_irqrestore(&priv->lock, flags);
2885	            contest_i2s_tx_free_dma_slots(priv);
2886	            syslog(LOG_INFO,
2887	                   "[C-I2S-DIAG] ioctl START rejected busy after allocation\n");
2888	            return -EBUSY;
2889	          }
2890	
2891	        priv->streaming = true;
2892	        priv->reserved = false;
2893	        priv->terminal_stop_pending = false;
2894	        priv->terminal_stop_slot = 0;
2895	        priv->fill_index = 0;
2896	        priv->done_index = 0;
2897	        priv->queued_slots = 0;
2898	        priv->max_queued_slots = 0;
2899	        priv->bound_slots = 0;
2900	        priv->done_count = 0;
2901	        priv->chained_count = 0;
2902	        priv->underrun_count = 0;
2903	        priv->silence_done_count = 0;
2904	        priv->late_refill_count = 0;
2905	        priv->ring_wrap_count = 0;
2906	        priv->submit_count = 0;
2907	        priv->dma_start_count = 0;
2908	        priv->done_irq_count = 0;
2909	
2910	        for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
2911	          {
2912	            xfer = &priv->xfer[i];
2913	            xfer->next = NULL;
2914	            xfer->apb = NULL;
2915	            xfer->dma_bound = false;
2916	            xfer->callback = NULL;
2917	            xfer->arg = NULL;
2918	            xfer->nbytes = 0;
2919	            xfer->result = OK;
2920	            xfer->in_use = false;
2921	            xfer->done_queued = false;
2922	            xfer->terminal = false;
2923	            xfer->desc_last = 0;
2924	            memset(xfer->desc, 0, sizeof(xfer->desc));
2925	          }
2926	
2927	        spin_unlock_irqrestore(&priv->lock, flags);
2928	
2929	        up_enable_irq(priv->tx_irq);
2930	        syslog(LOG_INFO,
2931	               "[C-I2S] tx GDMA-IMMUTABLE armed rate=%lu slots=%u "
2932	               "slot_bytes=%u private_dma=dynamic\n",
2933	               (unsigned long)priv->rate,
2934	               priv->ring_slots,
2935	               CONTEST_I2S_TX_SLOT_BYTES);
2936	        syslog(LOG_INFO, "[C-I2S-DIAG] ioctl START rc=0\n");
2937	        return OK;
2938	
2939	      case AUDIOIOC_STOP:
2940	        flags = spin_lock_irqsave(&priv->lock);
2941	        priv->streaming = false;
2942	        priv->terminal_stop_pending = false;
2943	
2944	        if (priv->hw_running)
2945	          {
2946	            contest_i2s_tx_capture_state(
2947	              priv, &priv->xfer[priv->done_index]);
2948	          }
2949	
2950	        contest_i2s_tx_stop_hw(priv);
2951	
2952	        for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
2953	          {
2954	            xfer = &priv->xfer[i];
2955	
2956	            if (xfer->in_use && !xfer->done_queued)
2957	              {
2958	                xfer->result = -ECANCELED;
2959	                xfer->done_queued = true;
2960	                contest_i2s_tx_done_push(priv, xfer);
2961	                schedule = true;
2962	              }
2963	
2964	            memset(xfer->desc, 0, sizeof(xfer->desc));
2965	            xfer->desc_last = 0;
2966	            xfer->dma_bound = false;
2967	            xfer->terminal = false;
2968	            up_clean_dcache((uintptr_t)xfer->desc,
2969	                            (uintptr_t)xfer->desc + sizeof(xfer->desc));
2970	          }
2971	
2972	        priv->queued_slots = 0;
2973	        spin_unlock_irqrestore(&priv->lock, flags);
2974	
2975	        contest_i2s_tx_free_dma_slots(priv);
2976	
2977	        syslog(LOG_INFO,
2978	               "[C-I2S] tx GDMA-IMMUTABLE stop done=%lu chained=%lu "
2979	               "underrun=%lu late_refill=%lu wraps=%lu "
2980	               "submit=%lu max_queued=%u bound=%u dma_start_count=%lu "
2981	               "done_irq=%lu\n",
2982	               (unsigned long)priv->done_count,
2983	               (unsigned long)priv->chained_count,
2984	               (unsigned long)priv->underrun_count,
2985	               (unsigned long)priv->late_refill_count,
2986	               (unsigned long)priv->ring_wrap_count,
2987	               (unsigned long)priv->submit_count,
2988	               priv->max_queued_slots,
2989	               priv->bound_slots,
2990	               (unsigned long)priv->dma_start_count,
2991	               (unsigned long)priv->done_irq_count);
2992	
2993	        priv->bound_slots = 0;
2994	
2995	        if (schedule || priv->done_head != NULL)
2996	          {
2997	            contest_i2s_tx_dump_state(priv);
2998	            if (work_available(&priv->tx_work))
2999	              {
3000	                work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker,
3001	                           priv, 0);
3002	              }
3003	          }
3004	
3005	        syslog(LOG_INFO, "[C-I2S-DIAG] ioctl STOP rc=0\n");
3006	        return OK;
3007	
3008	      case AUDIOIOC_SETBUFFERINFO:
3009	        {
3010	          FAR const struct ap_buffer_info_s *info =
3011	            (FAR const struct ap_buffer_info_s *)arg;
3012	          size_t expected = CONTEST_I2S_TX_SLOT_BYTES;
3013	
3014	          if (info == NULL)
3015	            {
3016	              return -EINVAL;
3017	            }
3018	
3019	          if (priv->logical_width == 16)
3020	            {
3021	              expected /= 2;
3022	            }
3023	
3024	          if ((info->nbuffers != 4 && info->nbuffers != 8 &&
3025	               info->nbuffers != 16) ||
3026	              (info->buffer_size != 0 && info->buffer_size != expected))
3027	            {
3028	              return -EINVAL;
3029	            }
3030	
3031	          flags = spin_lock_irqsave(&priv->lock);
3032	          if (priv->streaming || priv->hw_running || priv->reserved ||
3033	              priv->callbacks_pending != 0 || priv->done_head != NULL ||
3034	              !work_available(&priv->tx_stop_work))
3035	            {
3036	              spin_unlock_irqrestore(&priv->lock, flags);
3037	              return -EBUSY;
3038	            }
3039	
3040	          priv->requested_slots = info->nbuffers;
3041	          priv->geometry_explicit = true;
3042	          spin_unlock_irqrestore(&priv->lock, flags);
3043	          syslog(LOG_INFO,
3044	                 "[C-I2S] tx DMA geometry requested slots=%u "
3045	                 "logical_bytes=%zu wire_bytes=%u\n",
3046	                 info->nbuffers, expected, CONTEST_I2S_TX_SLOT_BYTES);
3047	          return OK;
3048	        }
3049	
3050	      case AUDIOIOC_GETBUFFERINFO:
3051	        {
3052	          FAR struct ap_buffer_info_s *info =
3053	            (FAR struct ap_buffer_info_s *)arg;
3054	
3055	          if (info == NULL)
3056	            {
3057	              syslog(LOG_INFO,
3058	                     "[C-I2S-DIAG] GETBUFFERINFO rejected null arg\n");
3059	              return -EINVAL;
3060	            }
3061	
3062	          info->nbuffers = priv->ring_slots != 0 ? priv->ring_slots :
3063	                                                  priv->requested_slots;
3064	          info->buffer_size = CONTEST_I2S_TX_SLOT_BYTES;
3065	          if (priv->logical_width == 16)
3066	            {
3067	              info->buffer_size /= 2;
3068	            }
3069	
3070	          syslog(LOG_INFO,
3071	                 "[C-I2S-DIAG] GETBUFFERINFO buffer_size=%u nbuffers=%u "
3072	                 "logical_width=%u wire_bytes=%u\n",
3073	                 info->buffer_size, info->nbuffers, priv->logical_width,
3074	                 CONTEST_I2S_TX_SLOT_BYTES);
3075	          return OK;
3076	        }
3077	
3078	      default:
3079	        syslog(LOG_INFO, "[C-I2S-DIAG] unsupported ioctl cmd=0x%x\n", cmd);
3080	        return -ENOTTY;
3081	    }
3082	}
