3084	static int contest_i2s_tx_ioctl(FAR struct i2s_dev_s *dev, int cmd,
3085	                                unsigned long arg)
3086	{
3087	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
3088	  int ret = nxmutex_lock(&priv->control_lock);
3089	
3090	  if (ret < 0)
3091	    {
3092	      return ret;
