2206	          priv->done_tail = NULL;
2207	        }
2208	
2209	      xfer->next = NULL;
2210	      apb = xfer->apb;
2211	      callback = xfer->callback;
2212	      callback_arg = xfer->arg;
2213	      nbytes = xfer->nbytes;
2214	      result = xfer->result;
2215	      irq_status = priv->irq_status;
2216	
2217	      /* The APB binding and descriptor links stay fixed for this run. */
2218	      xfer->apb = NULL;
2219	      xfer->callback = NULL;
2220	      xfer->arg = NULL;
2221	      xfer->nbytes = 0;
2222	      xfer->result = OK;
2223	      xfer->done_queued = false;
2224	      xfer->in_use = false;
2225	      xfer->terminal = false;
2226	
2227	      /*
2228	       * Mirror the clean ESP-IDF reference driver's
2229	       * auto_clear_after_cb=true behavior.
2230	       *
2231	       * This lower-half uses an immutable cyclic DMA descriptor ring whose
2232	       * private payload buffer stays attached to the descriptor.  Once a slot
2233	       * has completed, clear that private payload BEFORE publishing the upper
2234	       * callback.  If the producer is late refilling the slot, the next ring
2235	       * wrap therefore emits digital zero instead of replaying stale PCM.
2236	       *
2237	       * Normal completions reach this worker immediately after OUT_DONE; GDMA
2238	       * has already consumed this private payload.  The final terminal-short
2239	       * path still waits for FIFO/shifter drain before publishing completion.
2240	       * AUDIOIOC_STOP may free DMA buffers before a canceled callback runs,
2241	       * hence the NULL guard.
2242	       */
2243	      if (xfer->dma_data != NULL)
2244	        {
2245	          memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
2246	          up_clean_dcache((uintptr_t)xfer->dma_data,
2247	                          (uintptr_t)xfer->dma_data +
2248	                          CONTEST_I2S_TX_SLOT_BYTES);
2249	        }
2250	
2251	      spin_unlock_irqrestore(&priv->lock, flags);
2252	
2253	      if (result < 0)
2254	        {
2255	          syslog(LOG_ERR,
2256	                 "[C-I2S] tx completion failed irq=%08lx bytes=%zu rc=%d\n",
2257	                 (unsigned long)irq_status, nbytes, result);
2258	        }
2259	
2260	      if (callback != NULL && apb != NULL)
2261	        {
2262	          callback(&priv->dev, apb, callback_arg, result);
2263	          apb_free(apb);
2264	        }
2265	
2266	      flags = spin_lock_irqsave(&priv->lock);
2267	      DEBUGASSERT(priv->callbacks_pending > 0);
2268	      priv->callbacks_pending--;
2269	      spin_unlock_irqrestore(&priv->lock, flags);
2270	    }
2271	}
