2273	
2274	static void contest_i2s_tx_terminal_stop_worker(FAR void *arg)
2275	{
2276	  FAR struct contest_i2s_tx_s *priv = arg;
2277	  unsigned int slot;
2278	  bool schedule = false;
2279	  bool stopped = false;
2280	  irqstate_t flags;
2281	
2282	  flags = spin_lock_irqsave(&priv->lock);
2283	
2284	  if (!priv->terminal_stop_pending)
2285	    {
2286	      spin_unlock_irqrestore(&priv->lock, flags);
2287	      return;
2288	    }
2289	
2290	  slot = priv->terminal_stop_slot;
2291	  priv->terminal_stop_pending = false;
2292	
2293	  /*
2294	   * The terminal descriptor already has next=NULL, so GDMA cannot wrap back
2295	   * into stale PCM. Keep I2S alive until this delayed worker runs so the
2296	   * peripheral FIFO / shifter can emit the final real samples cleanly.
2297	   */
2298	  if (priv->hw_running)
2299	    {
2300	      contest_i2s_tx_stop_hw(priv);
2301	      stopped = true;
2302	    }
2303	
2304	  /*
2305	   * Publish terminal completion only after the hardware drain. The upper
2306	   * playback layer may issue AUDIOIOC_STOP immediately after this callback.
2307	   */
2308	  if (slot < priv->ring_slots &&
2309	      priv->xfer[slot].in_use &&
2310	      !priv->xfer[slot].done_queued)
2311	    {
2312	      schedule = contest_i2s_tx_complete_slot(priv, slot);
2313	    }
2314	
2315	  spin_unlock_irqrestore(&priv->lock, flags);
2316	
2317	  if (stopped)
2318	    {
2319	      syslog(LOG_INFO,
2320	             "[C-I2S] tx terminal drain complete slot=%u delay_ms=%u\n",
2321	             slot, CONTEST_I2S_TX_FIFO_DRAIN_MS);
2322	    }
2323	
2324	  if (schedule && work_available(&priv->tx_work))
2325	    {
2326	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
2327	    }
2328	}
