 536	/* Snapshot under the lifetime lock; STOP first aborts the queue and waits
 537	 * for this worker, then closes the backend. No polling of a freed ring. */
 538	static int contest_media_progress(FAR struct contest_media_sink_s *sink,
 539	                                  uint64_t *completed, uint64_t *pending,
 540	                                  bool *started)
 541	{
 542	  int ret = nxsem_wait_uninterruptible(&sink->playback_lock);
 543	  if (ret < 0)
 544	    {
 545	      return ret;
 546	    }
 547	
 548	  if (started != NULL) *started = sink->started;
 549	  if (!sink->playback_open)
 550	    {
 551	      *completed = sink->dequeued_pcm;
 552	      *pending = 0;
 553	      ret = sink->stream_error;
 554	    }
 555	  else
 556	    {
 557	      ret = robot_audio_playback_progress(completed, pending);
 558	      if (ret == OK)
 559	        {
 560	          sink->dequeued_pcm = *completed;
 561	        }
 562	    }
 563	
 564	  nxsem_post(&sink->playback_lock);
 565	  return ret;
 566	}
