472	+/****************************************************************************
473	+ * Function: wlan_alloc_tx_buffer
474	+ *
475	+ * Description:
476	+ *   Allocate a buffer for normal TX polling while preserving a receive-side
477	+ *   reserve.  This prevents a large TCP write from consuming every shared
478	+ *   packet buffer before inbound ACKs can be queued.
479	+ ****************************************************************************/
480	+
481	+static inline struct wlan_pktbuf *
482	+wlan_alloc_tx_buffer(struct wlan_priv_s *priv)
483	+{
484	+  static uint32_t reserve_hits;
485	+  struct wlan_pktbuf *pktbuf = NULL;
486	+  sq_entry_t *entry;
487	+  irqstate_t flags;
488	+
489	+  flags = spin_lock_irqsave(&priv->lock);
490	+
491	+  if (priv->free_count > WLAN_RX_RESERVED_BUFS)
492	+    {
493	+      entry = sq_remfirst(&priv->freeb);
494	+      if (entry)
495	+        {
496	+          pktbuf = container_of(entry, struct wlan_pktbuf, entry);
497	+          DEBUGASSERT(priv->free_count > 0);
498	+          priv->free_count--;
499	+          if (priv->free_count < priv->free_min)
500	+            {
501	+              priv->free_min = priv->free_count;
502	+            }
503	+        }
504	+    }
505	+  else
506	+    {
507	+      reserve_hits++;
508	+
509	+      /* Keep diagnostics useful without flooding the serial console. */
510	+
511	+      if (reserve_hits <= 8 || (reserve_hits & 0x1f) == 0)
512	+        {
513	+          syslog(LOG_INFO,
514	+                 "[WLAN-BUF] TX reserve hit=%" PRIu32
515	+                 " free=%u reserve=%u total=%u\n",
516	+                 reserve_hits,
517	+                 (unsigned int)priv->free_count,
518	+                 (unsigned int)WLAN_RX_RESERVED_BUFS,
519	+                 (unsigned int)WLAN_PKTBUF_NUM);
520	+        }
521	+    }
522	+
523	+  spin_unlock_irqrestore(&priv->lock, flags);
524	+  return pktbuf;
525	+}
