676	+  uint32_t retry_count = 0;
677	+  uint32_t delay_ticks;
678	+  bool schedule = false;
679	+  int ret;
680	+
681	+  flags = spin_lock_irqsave(&priv->lock);
682	+
683	+  if (!priv->tx_retry_pending)
684	+    {
685	+      delay_ms = priv->tx_retry_ms;
686	+      priv->tx_retry_pending = true;
687	+      priv->tx_retry_count++;
688	+      retry_count = priv->tx_retry_count;
689	+
690	+      if (priv->tx_retry_ms < WLAN_TX_RETRY_MAX_MS)
691	+        {
