1906	int robot_audio_playback_write(const uint8_t *pcm, size_t len)
1907	{
1908	  struct rv_playback_s *pb = &g_pb;
1909	  size_t offset = 0;
1910	
1911	  if (!pb->opened || pcm == NULL || len == 0)
1912	    {
1913	      return -EINVAL;
1914	    }
1915	
1916	  if ((len & 1) != 0)
1917	    {
1918	      /* PCM16 producer chunks must preserve sample alignment. */
1919	      printf("[RV-PB] reject odd PCM chunk len=%zu\n", len);
1920	      return -EINVAL;
1921	    }
1922	
1923	  if (pb->cache_until_eos)
1924	    {
1925	      size_t required;
1926	      int lock_ret = rv_lock(pb);
1927	      if (lock_ret < 0) return lock_ret;
1928	      if (pb->eos || pb->stopped)
1929	        { rv_unlock(pb); return pb->stopped ? -ECANCELED : -EPIPE; }
1930	      if (len > ROBOT_VOICE_TTS_CACHE_BYTES - pb->total_written)
1931	        {
1932	          rv_unlock(pb);
1933	          printf("[RV-PB] cache overflow id=%u incoming=%zu cached=%zu limit=%u; no audio played\n",
1934	                 pb->id, len, pb->total_written, ROBOT_VOICE_TTS_CACHE_BYTES);
1935	          return -EOVERFLOW;
1936	        }
1937	      required = pb->total_written + len;
1938	      if (required > pb->ring.capacity)
1939	        {
1940	          size_t capacity = pb->ring.capacity;
1941	          uint8_t *data;
1942	          while (capacity < required) capacity *= 2;
1943	          if (capacity > ROBOT_VOICE_TTS_CACHE_BYTES)
1944	            capacity = ROBOT_VOICE_TTS_CACHE_BYTES;
1945	          /* Voice has not consumed any PCM yet. It is contiguous from zero;
1946	           * restore head=count if the old capacity was exactly full. */
1947	          data = realloc(pb->ring.data, capacity);
1948	          if (!data) { rv_unlock(pb); return -ENOMEM; }
1949	          pb->ring.data = data;
1950	          pb->ring.capacity = capacity;
1951	          pb->ring.head = pb->ring.count;
1952	        }
1953	      rv_unlock(pb);
1954	    }
1955	
1956	  /*
1957	   * Producer side from tts_pcm_playback_guide.md:
1958	   *
1959	   * Never fail a valid long utterance just because the 256 KiB ring is
1960	   * temporarily full.  Wait for the dedicated playback worker to free space,
1961	   * then continue writing the same PCM chunk.
1962	   */
1963	  while (offset < len)
1964	    {
1965	      size_t buffered;
1966	      size_t space;
1967	      size_t n;
1968	      int ret;
1969	
1970	      if (pb->stopped)
1971	        {
1972	          return pb->terminal_tail_done ? -EPIPE : -ECANCELED;
1973	        }
1974	
1975	      ret = rv_get_result(pb);
1976	      if (ret < 0)
1977	        {
1978	          return ret;
1979	        }
1980	
1981	      buffered = rv_ring_count(pb);
1982	      space = pb->ring.capacity - buffered;
1983	      if (space < 2)
1984	        {
1985	          ret = nxsem_wait_uninterruptible(&pb->ring_space);
1986	          if (ret < 0)
1987	            {
1988	              return ret;
1989	            }
1990	          continue;
1991	        }
1992	
1993	      n = len - offset;
1994	      if (n > space)
1995	        {
1996	          n = space;
1997	        }
1998	
1999	      n &= ~(size_t)1;
2000	      if (n == 0)
2001	        {
2002	          continue;
2003	        }
2004	
2005	      ret = rv_ring_write(pb, pcm + offset, n);
2006	      if (ret == -ENOSPC)
2007	        {
2008	          continue;
2009	        }
2010	      if (ret < 0)
2011	        {
2012	          return ret;
2013	        }
2014	
2015	      offset += n;
2016	    }
2017	
2018	  return 0;
2019	}
