   414	/****************************************************************************
   415	 * Function: wlan_add_txpkt_head
   416	 *
   417	 * Description:
   418	 *   Add packet into head of TX ready queue.
   419	 *
   420	 * Input Parameters:
   421	 *   priv - Reference to the driver state structure
   422	 *
   423	 * Returned Value:
   424	 *   None
   425	 *
   426	 ****************************************************************************/
   427	
   428	static inline void wlan_add_txpkt_head(struct wlan_priv_s *priv,
   429	                                       struct wlan_pktbuf *pktbuf)
   430	{
   431	  irqstate_t flags;
   432	
   433	  flags = spin_lock_irqsave(&priv->lock);
   434	  sq_addfirst(&pktbuf->entry, &priv->txb);
   435	  spin_unlock_irqrestore(&priv->lock, flags);
   436	}
   437	
   438	/****************************************************************************
   439	 * Function: wlan_recvframe
   440	 *
   441	 * Description:
   442	 *   Try to receive RX packet from RX done packet queue.
   443	 *
   444	 * Input Parameters:
   445	 *   priv - Reference to the driver state structure
   446	 *
   447	 * Returned Value:
   448	 *   RX packet if success or NULl if no packet in queue.
   449	 *
   450	 ****************************************************************************/
   451	
   452	static struct wlan_pktbuf *wlan_recvframe(struct wlan_priv_s *priv)
   453	{
   454	  irqstate_t flags;
   455	  sq_entry_t *entry;
   456	  struct wlan_pktbuf *pktbuf = NULL;
   457	
   458	  flags = spin_lock_irqsave(&priv->lock);
   459	
   460	  entry = sq_remfirst(&priv->rxb);
   461	  if (entry)
   462	    {
   463	      pktbuf = container_of(entry, struct wlan_pktbuf, entry);
   464	    }
   465	
   466	  spin_unlock_irqrestore(&priv->lock, flags);
   467	
   468	  return pktbuf;
   469	}
   470	
   471	/****************************************************************************
   472	 * Function: wlan_txframe
   473	 *
   474	 * Description:
   475	 *   Try to receive TX buffer from TX ready buffer queue.
   476	 *
   477	 * Input Parameters:
   478	 *   priv - Reference to the driver state structure
   479	 *
   480	 * Returned Value:
   481	 *   TX packets buffer if success or NULL if no packet in queue.
   482	 *
   483	 ****************************************************************************/
   484	
   485	static struct wlan_pktbuf *wlan_txframe(struct wlan_priv_s *priv)
   486	{
   487	  irqstate_t flags;
   488	  sq_entry_t *entry;
   489	  struct wlan_pktbuf *pktbuf = NULL;
   490	
   491	  flags = spin_lock_irqsave(&priv->lock);
   492	
   493	  entry = sq_remfirst(&priv->txb);
   494	  if (entry)
   495	    {
   496	      pktbuf = container_of(entry, struct wlan_pktbuf, entry);
   497	    }
   498	
   499	  spin_unlock_irqrestore(&priv->lock, flags);
   500	
   501	  return pktbuf;
   502	}
   503	
   504	/****************************************************************************
   505	 * Name: wlan_transmit
   506	 *
   507	 * Description:
   508	 *   Try to send all TX packets in TX ready queue to Wi-Fi driver. If this
   509	 *    sending fails, then breaks loop and returns.
   510	 *
   511	 * Input Parameters:
   512	 *   priv - Reference to the driver state structure
   513	 *
   514	 * Returned Value:
   515	 *   None
   516	 *
   517	 ****************************************************************************/
   518	
   519	static void wlan_transmit(struct wlan_priv_s *priv)
   520	{
   521	  struct wlan_pktbuf *pktbuf;
   522	  int ret;
   523	
   524	  while ((pktbuf = wlan_txframe(priv)))
   525	    {
   526	      ret = priv->ops->send(pktbuf->buffer, pktbuf->len);
   527	      if (ret == -ENOMEM)
   528	        {
   529	          wlan_add_txpkt_head(priv, pktbuf);
   530	          wd_start(&priv->txtimeout, WLAN_TXTOUT,
   531	                   wlan_txtimeout_expiry, (uint32_t)priv);
   532	          break;
   533	        }
   534	      else
   535	        {
   536	          if (ret < 0)
   537	            {
   538	              nwarn("WARN: Failed to send pkt, ret: %d\n", ret);
   539	            }
   540	
   541	          wlan_free_buffer(priv, pktbuf->buffer);
   542	        }
   543	    }
   544	}
