   546	/****************************************************************************
   547	 * Name: wlan_tx_done
   548	 *
   549	 * Description:
   550	 *   Wi-Fi TX done callback function. If this is called, it means sending
   551	 *   next packet.
   552	 *
   553	 * Input Parameters:
   554	 *   priv   - Reference to the driver state structure
   555	 *
   556	 * Returned Value:
   557	 *   None
   558	 *
   559	 ****************************************************************************/
   560	
   561	static void wlan_tx_done(struct wlan_priv_s *priv)
   562	{
   563	  wd_cancel(&priv->txtimeout);
