   584	 ****************************************************************************/
   585	
   586	static int wlan_rx_done(struct wlan_priv_s *priv, void *buffer,
   587	                        uint16_t len, void *eb)
   588	{
   589	  struct wlan_pktbuf *pktbuf;
   590	  irqstate_t flags;
   591	  int ret = 0;
   592	
   593	  if (!priv->ifup)
   594	    {
   595	      goto out;
   596	    }
   597	
   598	  if (len > WLAN_BUF_SIZE)
   599	    {
   600	      nwarn("ERROR: Wlan receive %d larger than %d\n",
   601	             len, WLAN_BUF_SIZE);
