   603	      goto out;
   604	    }
   605	
   606	  pktbuf = wlan_alloc_buffer(priv);
   607	  if (!pktbuf)
   608	    {
   609	      ret = -ENOBUFS;
   610	      goto out;
   611	    }
   612	
   613	  memcpy(pktbuf->buffer, buffer, len);
   614	  pktbuf->len = len;
   615	
   616	  if (eb)
   617	    {
   618	      esp_wifi_free_eb(eb);
   619	    }
   620	
   620	
   621	  flags = spin_lock_irqsave(&priv->lock);
   622	  sq_addlast(&pktbuf->entry, &priv->rxb);
   623	  spin_unlock_irqrestore(&priv->lock, flags);
   624	
   625	  if (work_available(&priv->rxwork))
   626	    {
   627	      work_queue(WLAN_WORK, &priv->rxwork, wlan_rxpoll, priv, 0);
   628	    }
   629	
   630	  return 0;
   631	
   632	out:
   633	  if (eb)
   634	    {
   635	      esp_wifi_free_eb(eb);
   636	    }
   637	
   638	  return ret;
   639	}
