   659	  struct eth_hdr_s *eth_hdr;
   660	  struct wlan_priv_s *priv = (struct wlan_priv_s *)arg;
   661	  struct net_driver_s *dev = &priv->dev;
   662	#ifdef WLAN_RX_THRESHOLD
   663	  uint32_t rbytes = 0;
