  32	/*
  33	 * Playback format mirrors the original board codec:
  34	 *
  35	 *   source: PCM16LE / 24000 Hz / mono
  36	 *   wire:   24000 Hz / 32 bit / mono-left (two physical I2S slots)
  37	 *
  38	 * No resampling and no time-domain sample repetition are performed.
  39	 * Each mono source sample is left-aligned into one 32-bit mono I2S word:
  40	 *
  41	 *   source: A B C ...
  42	 *   wire:   (A<<16) (B<<16) (C<<16) ...
  43	 *
  44	 * The TX lower-half selects the left slot and maintains the second physical
  45	 * 32-bit slot required for the 64-BCLK LRCK frame.
  46	 */
  47	#define RV_TTS_SAMPLE_RATE          24000
  48	#define RV_WIRE_SAMPLE_RATE         24000
  49	#define RV_TTS_SOURCE_CHANNELS      1
  50	#define RV_TTS_BITS                 16
  51	#define RV_WIRE_CHANNELS            1
  52	#define RV_WIRE_BITS                32
  53	#define RV_WIRE_BYTES_PER_SAMPLE    (RV_WIRE_BITS / 8)
  54	/* User-selected output volume 80 with the original quadratic volume curve:
  55	 * (80 / 100)^2 * 65536 = 41943. */
  56	#define RV_OUTPUT_GAIN_Q16          41943
  57	
  58	#define RV_SOURCE_BLOCK_BYTES       1024
  59	#define RV_WIRE_BLOCK_BYTES \
  60	  ((unsigned int)((RV_SOURCE_BLOCK_BYTES / sizeof(int16_t)) * RV_WIRE_BYTES_PER_SAMPLE))
  61	/*
  62	 * Must match contest_i2s.c:
  63	 *   CONTEST_I2S_TX_RING_SLOTS = 16
  64	 *   CONTEST_I2S_TX_SLOT_BYTES = 2048
  65	 *
  66	 * Sixteen is the maximum. START negotiates 16/8/4 slots according to actual
  67	 * internal memory; GETBUFFERINFO reports the selected count. Every priming,
  68	 * wrap and drain operation must use that same count.
  69	 */
  70	#define RV_LOWER_DMA_RING_SLOTS      16
  71	#define RV_LOWER_DMA_SLOT_BYTES      2048
  72	#define RV_MAX_INFLIGHT              RV_LOWER_DMA_RING_SLOTS
  73	#define RV_SEND_TIMEOUT_MS           1000
  74	#if ROBOT_VOICE_TTS_PREBUFFER < (RV_MAX_INFLIGHT + 1) * RV_SOURCE_BLOCK_BYTES || ROBOT_VOICE_TTS_PREBUFFER > ROBOT_VOICE_TTS_STREAM_RING_BYTES
  75	#  error Live voice prebuffer must prime DMA and fit its bounded ring
  76	#endif
  77	
  78	/* A released cyclic DMA slot must be refilled immediately. Waiting for the
  79	 * producer here allows old payloads to circulate. Voice instead waits for
  80	 * complete PCM before priming; streaming music retains its existing policy. */
  81	#define RV_REFILL_WINDOW_MS(pb) \
  82	  (((pb)->slot_count - 1) * RV_SOURCE_BLOCK_BYTES * 1000 / \
  83	   (RV_TTS_SAMPLE_RATE * sizeof(int16_t)))
  84	
  85	/*
  86	 * Diagnostic switches.  Keep both at zero for normal TTS playback.
  87	 *
  88	 * RV_FULL_CACHE_AB_TEST=1
  89	 *   Do not start I2S until the complete WAV PCM has reached EOS.  This keeps
  90	 *   the exact same PCM -> DMA path but removes producer/consumer overlap.
  91	 *
  92	 * RV_I2S_OUTPUT_TONE_TEST=1
  93	 *   Keep the same ring, worker, DMA blocks and I2S configuration, but replace
  94	 *   every source sample at the final PCM -> wire boundary with a 1 kHz tone.
  95	 *   A clean tone proves that the echo is upstream of I2S; a doubled/rough
  96	 *   tone proves that it is in the DMA/I2S/codec path.
  97	 *
  98	 * Enable one switch at a time.  Neither switch is a production setting.
  99	 */
 100	#define RV_FULL_CACHE_AB_TEST        0
 101	#define RV_I2S_OUTPUT_TONE_TEST      0
 102	#define RV_I2S_OUTPUT_TONE_PEAK       8192
 103	
 104	/*
 105	 * Ring-buffer values from tts_pcm_playback_guide.md:
 106	 *
 107	 *   Music Ring      = 2 MiB (PSRAM jitter cushion)
 108	 *   Music Prebuffer = 192 KiB; voice SSE prebuffer = 24 KiB
 109	 *   Rebuffer        =  48 KiB (legacy threshold; F7I does not rebuffer once PLAYING)
 110	 *
 111	 * The worker waits in PREBUFFER while PCM arrives. Cached voice waits for
 112	 * EOS; live voice starts at its prebuffer and retains a real final block.
 113	 *
 114	 * Legacy streaming-music invariant for the immutable contest I2S DMA ring:
 115	 * once PLAYING has started, the worker must keep every released DMA slot
 116	 * refreshed.  If the producer temporarily runs dry, submit silence instead
 117	 * of entering REBUFFER and leaving old slot payloads circulating in hardware.
 118	 */
 119	#if RV_FULL_CACHE_AB_TEST
 120	#  define RV_RING_BYTES             (2 * 1024 * 1024)
 121	#  define RV_START_PREBUFFER_BYTES  RV_RING_BYTES
 122	#  define RV_MUSIC_RING_BYTES       RV_RING_BYTES
 123	#  define RV_MUSIC_START_PREBUFFER_BYTES RV_RING_BYTES
 124	#else
 125	#  define RV_RING_BYTES             (512 * 1024)
 126	#  define RV_START_PREBUFFER_BYTES  (128 * 1024)
 127	#  define RV_MUSIC_RING_BYTES       (4 * 1024 * 1024)
 128	#  define RV_MUSIC_START_PREBUFFER_BYTES (1024 * 1024)
 129	#endif
 130	#define RV_REBUFFER_BYTES           (48 * 1024)
 131	/* Native Media's URL input is bursty. Keep the large music ring for jitter
 132	 * headroom and wait for a useful amount of PCM before enabling I2S. One DMA
 133	 * ring (4 KiB) is only about 85 ms at 24 kHz mono and starts an immediate
 134	 * underrun when the redirected URL is still filling its first TCP buffers. */
 135	#define RV_NATIVE_MEDIA_RING_BYTES  (512 * 1024)
 136	#define RV_NATIVE_MEDIA_PREBUFFER_BYTES (32 * 1024)
 137	
 138	/* The proven version used priority 120.  Keep that real-time bias.  Use a
 139	 * larger stack than the old 4 KiB implementation because this contest-local
 140	 * wrapper has additional logging/call depth, while the DMA cadence remains
 141	 * identical to the proven code.
 142	 */
 143	#define RV_WORKER_STACK             (16 * 1024)
 144	#define RV_WORKER_PRIORITY          ROBOT_VOICE_PLAY_PRIORITY
