1649	             "expected=%uHz/%uch/%ubit\n",
1650	             ROBOT_VOICE_TTS_RATE, ROBOT_VOICE_CHANNELS, ROBOT_VOICE_BITS,
1651	             RV_TTS_SAMPLE_RATE, RV_TTS_SOURCE_CHANNELS, RV_TTS_BITS);
1652	      return -ENOTSUP;
1653	    }
1654	
1655	  pb->ring.data = malloc(pb->ring.capacity);
1656	  if (pb->ring.data == NULL && !cache_until_eos && !voice_live &&
1657	      !native_media && pb->ring.capacity != RV_RING_BYTES)
1658	    {
1659	      /* Music uses PSRAM for a long jitter cushion when available. Fall back
1660	       * to the original bounded ring if the board has less free PSRAM. */
1661	      pb->ring.capacity = RV_RING_BYTES;
1662	      pb->start_prebuffer = RV_FULL_CACHE_AB_TEST ? RV_RING_BYTES :
1663	                            RV_MUSIC_START_PREBUFFER_BYTES;
1664	      if (pb->start_prebuffer > pb->ring.capacity)
1665	        {
1666	          pb->start_prebuffer = pb->ring.capacity;
1667	        }
1668	      pb->ring.data = malloc(pb->ring.capacity);
1669	      printf("[RV-PB] music ring fallback capacity=%zu prebuffer=%u\n",
1670	             pb->ring.capacity, pb->start_prebuffer);
1671	    }
1672	  if (pb->ring.data == NULL)
1673	    {
1674	      printf("[RV-PB] ring alloc failed bytes=%u mode=%s\n",
1675	             (unsigned int)pb->ring.capacity,
1676	             RV_FULL_CACHE_AB_TEST ? "full-cache" : "streaming");
1677	      return -ENOMEM;
1678	    }
1679	
1680	  ret = nxsem_init(&pb->i2s_done, 0, 0);
1681	  if (ret < 0)
1682	    {
1683	      free(pb->ring.data);
1684	      memset(pb, 0, sizeof(*pb));
1685	      return ret;
1686	    }
1687	
1688	  ret = nxsem_init(&pb->ring_lock, 0, 1);
1689	  if (ret < 0)
1690	    {
1691	      nxsem_destroy(&pb->i2s_done);
1692	      free(pb->ring.data);
1693	      memset(pb, 0, sizeof(*pb));
1694	      return ret;
1695	    }
1696	
1697	  ret = nxsem_init(&pb->ring_data, 0, 0);
1698	  if (ret < 0)
1699	    {
1700	      nxsem_destroy(&pb->ring_lock);
1701	      nxsem_destroy(&pb->i2s_done);
1702	      free(pb->ring.data);
1703	      memset(pb, 0, sizeof(*pb));
1704	      return ret;
1705	    }
1706	
1707	  ret = nxsem_init(&pb->ring_space, 0, 0);
1708	  if (ret < 0)
1709	    {
1710	      nxsem_destroy(&pb->ring_data);
1711	      nxsem_destroy(&pb->ring_lock);
1712	      nxsem_destroy(&pb->i2s_done);
1713	      free(pb->ring.data);
1714	      memset(pb, 0, sizeof(*pb));
1715	      return ret;
1716	    }
1717	
1718	  for (i = 0; i < RV_MAX_INFLIGHT; i++)
1719	    {
1720	      ret = nxsem_init(&pb->slots[i].done, 0, 0);
1721	      if (ret < 0)
1722	        {
1723	          while (i > 0)
1724	            {
1725	              i--;
1726	              nxsem_destroy(&pb->slots[i].done);
1727	            }
1728	
1729	          nxsem_destroy(&pb->ring_space);
1730	          nxsem_destroy(&pb->ring_data);
1731	          nxsem_destroy(&pb->ring_lock);
1732	          nxsem_destroy(&pb->i2s_done);
1733	          free(pb->ring.data);
1734	          memset(pb, 0, sizeof(*pb));
1735	          return ret;
1736	        }
1737	
1738	      pb->slots[i].pb = pb;
1739	      pb->slots[i].result = 0;
1740	      pb->slots[i].inflight = 0;
1741	      pb->slots[i].index = i;
1742	    }
1743	
1744	  pb->i2s_result = 0;
1745	  pb->state = RV_STATE_PREBUFFER;
1746	  pb->opened = 1;
1747	
1748	  /* Complete-cache voice needs no DMA buffers, APBs or hardware worker
1749	   * during the network download. Release this DRAM budget to Wi-Fi until
1750	   * the full validated playback window is ready at finish(). */
1751	  if (!(cache_until_eos && ROBOT_VOICE_TTS_CONTINUITY))
1752	    {
1753	      ret = rv_start_i2s_playback(pb);
1754	      if (ret < 0)
1755	        {
1756	          rv_destroy(pb);
1757	          memset(pb, 0, sizeof(*pb));
1758	          return ret;
1759	        }
1760	    }
1761	
1762	  RV_VERBOSE("[RV-DIAG] mode=%s output=%s tone_peak=%u "
1763	         "source_bytes_per_sec=%u wire_bytes_per_sec=%u\n",
1764	         RV_FULL_CACHE_AB_TEST ? "full-cache" : "streaming",
1765	         RV_I2S_OUTPUT_TONE_TEST ? "tone-1khz" : "tts-pcm",
1766	         RV_I2S_OUTPUT_TONE_PEAK,
1767	         RV_TTS_SAMPLE_RATE * RV_TTS_SOURCE_CHANNELS *
1768	           (RV_TTS_BITS / 8),
1769	         RV_WIRE_SAMPLE_RATE * RV_WIRE_BYTES_PER_SAMPLE);
1770	  RV_VERBOSE("[RV-PB] ring open capacity=%zu start=%u rebuffer=%u "
1771	         "source=%uHz/mono/%ubit wire=%uHz/mono-left/%ubit resample=none\n",
1772	         pb->ring.capacity, pb->start_prebuffer, RV_REBUFFER_BYTES,
1773	         RV_TTS_SAMPLE_RATE, RV_TTS_BITS,
1774	         RV_WIRE_SAMPLE_RATE, RV_WIRE_BITS);
1775	  RV_VERBOSE("[RV-PB] open id=%u mode=%s capacity=%zu cache_limit=%zu source=24000/mono16\n",
1776	         pb->id, cache_until_eos ? "voice-complete-cache" :
1777	         (voice_live ? "voice-live" : "music-stream"), pb->ring.capacity,
1778	         cache_until_eos ? ROBOT_VOICE_TTS_CACHE_BYTES : pb->ring.capacity);
1779	  return 0;
1780	}
