2035	int robot_audio_playback_finish(void)
2036	{
2037	  struct rv_playback_s *pb = &g_pb;
2038	  int ret = 0;
2039	
2040	  if (!pb->opened)
2041	    {
2042	      return -EINVAL;
2043	    }
2044	
2045	  if (pb->finished)
2046	    {
2047	      return rv_get_result(pb);
2048	    }
2049	
2050	  if (pb->cache_until_eos && ROBOT_VOICE_TTS_CONTINUITY &&
2051	      !pb->worker_started && !pb->stopped && pb->total_written != 0)
2052	    {
2053	      ret = rv_start_i2s_playback(pb);
2054	      if (ret < 0)
2055	        {
2056	          if (rv_lock(pb) == 0)
2057	            {
2058	              pb->i2s_result = ret;
2059	              rv_unlock(pb);
2060	            }
2061	          return ret;
2062	        }
2063	    }
2064	
2065	  /*
2066	   * Producer EOS: wake the consumer.  If less than a normal prebuffer/block
2067	   * remains, the worker is allowed to drain that final aligned PCM tail.
2068	   */
2069	  pb->eos = 1;
2070	  RV_VERBOSE("[RV-PB] producer EOS id=%u mono_ms=%llu cached=%zu\n",
2071	         pb->id, rv_audio_now_ms(), pb->total_written);
2072	  rv_signal_all(pb);
2073	
2074	  if (pb->worker_started)
2075	    {
2076	      int join_ret = pthread_join(pb->worker, NULL);
2077	
2078	      if (join_ret != 0 && ret >= 0)
2079	        {
2080	          ret = -join_ret;
2081	        }
2082	
2083	      pb->worker_started = 0;
2084	    }
2085	
2086	  if (rv_get_result(pb) < 0 && ret >= 0)
2087	    {
2088	      ret = rv_get_result(pb);
2089	    }
2090	
2091	  if (pb->i2s != NULL && pb->i2s_started)
2092	    {
2093	      pb->i2s_started = 0;
2094	      I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
2095	    }
2096	
2097	  pb->finished = 1;
2098	
2099	  if ((pb->cache_until_eos || pb->voice_live) && ret == 0 && (pb->input_hash != pb->output_hash ||
2100	                   pb->total_written != pb->total_read)) ret = -EPROTO;
2101	  if (ret < 0 && rv_lock(pb) == 0)
2102	    { if (pb->i2s_result >= 0) pb->i2s_result = ret; rv_unlock(pb); }
2103	  if (pb->voice_live && pb->sentence) {
2104	    RV_EVENT("[播放] run=%lu seq=%u 已完成 PCM=%zuB 补静音块=%lu 最大连续补静音块=%lu rc=%d\n",
2105	      pb->run_id, pb->sentence, pb->total_read, (unsigned long)pb->silence_blocks,
2106	      (unsigned long)pb->max_gap_run, ret);
2107	  } else if (pb->sentence && pb->dma_start_ms) {
2108	    RV_EVENT("[耗时][TTS] run=%lu seq=%u 文本送入到播放提交=%lldms 合成=%lldms 就绪后等待及提交=%lldms rc=%d\n",
2109	      pb->run_id, pb->sentence, rv_elapsed_ms(pb->tts_start_ms, pb->dma_start_ms),
2110	      rv_elapsed_ms(pb->tts_start_ms, pb->tts_ready_ms),
2111	      rv_elapsed_ms(pb->tts_ready_ms, pb->dma_start_ms), ret);
2112	  }
2113	
2114	  RV_VERBOSE("[RV-PB] PLAY_DONE id=%u pcm=%zu consumed=%zu hash=%08lx/%08lx "
2115	         "gap_blocks=%lu late_refills=%lu max_refill_ms=%llu max_send_ms=%llu "
2116	         "callback_errors=%lu callback_gap_max_ms=%llu tail_pad=%lu end_silence_blocks=%lu rc=%d\n",
2117	         pb->id, pb->total_written, pb->total_read,
2118	         (unsigned long)pb->input_hash, (unsigned long)pb->output_hash,
2119	         (unsigned long)pb->underrun_count, (unsigned long)pb->late_refills,
2120	         pb->max_refill_ms, pb->max_send_ms, (unsigned long)pb->callback_errors,
2121	         pb->max_callback_gap_ms, (unsigned long)pb->tail_pad_bytes, (unsigned long)pb->silence_blocks, ret);
2122	  RV_VERBOSE("[RV-LATENCY] playback_id=%u dma_start_ms=%llu "
2123	         "user_end_to_dma_ms=%llu commit_to_dma_ms=%llu tts_to_dma_ms=%llu "
2124	         "first_pcm_to_dma_ms=%llu source_ms=%zu play_ms=%llu producer_gap_max_ms=%llu\n",
2125	         pb->id, pb->dma_start_ms,
2126	         pb->user_end_ms && pb->dma_start_ms >= pb->user_end_ms ? pb->dma_start_ms - pb->user_end_ms : 0,
2127	         pb->commit_ms && pb->dma_start_ms >= pb->commit_ms ? pb->dma_start_ms - pb->commit_ms : 0,
2128	         pb->tts_start_ms && pb->dma_start_ms >= pb->tts_start_ms ? pb->dma_start_ms - pb->tts_start_ms : 0,
2129	         pb->first_pcm_ms && pb->dma_start_ms >= pb->first_pcm_ms ? pb->dma_start_ms - pb->first_pcm_ms : 0,
2130	         pb->total_written * 1000 / (RV_TTS_SAMPLE_RATE * sizeof(int16_t)),
2131	         pb->dma_start_ms && pb->dma_done_ms >= pb->dma_start_ms ? pb->dma_done_ms - pb->dma_start_ms : 0,
2132	         pb->max_pcm_gap_ms);
2133	  if (!pb->voice_live)
2134	    {
2135	      printf("[RV-PB] stream summary id=%u prebuffer=%u low_water=%zu "
2136	             "underruns=%lu silence_blocks=%lu producer_gap_max_ms=%llu\n",
2137	             pb->id, pb->start_prebuffer, pb->ring_min_play,
2138	             (unsigned long)pb->underrun_count,
2139	             (unsigned long)pb->silence_blocks, pb->max_pcm_gap_ms);
2140	    }
2141	  return ret;
2142	}
2143	
2144	void robot_audio_playback_close(void)
2145	{
2146	  struct rv_playback_s *pb = &g_pb;
2147	
2148	  if (!pb->opened)
2149	    {
2150	      return;
2151	    }
2152	
2153	  if (pb->worker_started)
2154	    {
2155	      pb->stopped = 1;
2156	      rv_signal_all(pb);
2157	
2158	      if (pb->i2s != NULL && pb->i2s_started)
2159	        {
2160	          pb->i2s_started = 0;
2161	          I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
2162	          rv_signal_all(pb);
2163	        }
2164	
2165	      pthread_join(pb->worker, NULL);
2166	      pb->worker_started = 0;
2167	    }
2168	
2169	  (void)rv_drain(pb);
2170	
2171	  if (pb->i2s != NULL && pb->i2s_started)
2172	    {
2173	      pb->i2s_started = 0;
2174	      I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
2175	    }
