   346	static uint32_t contest_i2s_bswap32(uint32_t value)
   347	{
   348	  return ((value & UINT32_C(0x000000ff)) << 24) |
   349	         ((value & UINT32_C(0x0000ff00)) << 8) |
   350	         ((value & UINT32_C(0x00ff0000)) >> 8) |
   351	         ((value & UINT32_C(0xff000000)) >> 24);
   352	}
