   354	static int16_t contest_i2s_pcm_candidate_a(uint32_t raw)
   355	{
   356	  return (int16_t)((int32_t)raw >> CONTEST_I2S_RX_PCM_SHIFT);
   357	}
   358	
   359	static int16_t contest_i2s_pcm_candidate_b(uint32_t raw)
   360	{
   361	  int32_t signed24 = (int32_t)(raw & UINT32_C(0x00ffffff));
   362	
   363	  if ((signed24 & INT32_C(0x00800000)) != 0)
   364	    {
   365	      signed24 |= ~INT32_C(0x00ffffff);
   366	    }
   367	
   368	  return (int16_t)(signed24 >> 8);
   369	}
