   371	static void contest_i2s_pcm_stats_init(FAR struct contest_i2s_pcm_stats_s *s)
   372	{
   373	  s->minimum = INT16_MAX;
   374	  s->maximum = INT16_MIN;
   375	  s->sum = 0;
   376	  s->squares = 0;
   377	  s->clip_count = 0;
   378	  s->max_delta = 0;
   379	  s->have_previous = false;
   380	}
   381	
   382	static void contest_i2s_pcm_stats_add(FAR struct contest_i2s_pcm_stats_s *s,
   383	                                       int16_t value)
   384	{
   385	  int64_t delta;
   386	
   387	  if (value < s->minimum)
   388	    {
   389	      s->minimum = value;
   390	    }
   391	
   392	  if (value > s->maximum)
   393	    {
   394	      s->maximum = value;
   395	    }
   396	
   397	  s->sum += value;
   398	  s->squares += (int64_t)value * value;
   399	  if (value == INT16_MIN || value == INT16_MAX)
   400	    {
   401	      s->clip_count++;
   402	    }
   403	
   404	  if (s->have_previous)
   405	    {
   406	      delta = (int64_t)value - s->previous;
   407	      if (delta < 0)
   408	        {
   409	          delta = -delta;
   410	        }
   411	
   412	      if ((uint64_t)delta > s->max_delta)
   413	        {
   414	          s->max_delta = delta;
   415	        }
   416	    }
   417	
   418	  s->previous = value;
   419	  s->have_previous = true;
   420	}
