   901	static void contest_i2s_rx_worker(FAR void *arg)
   902	{
   903	  FAR struct contest_i2s_s *priv = arg;
   904	  FAR struct contest_i2s_rx_xfer_s *xfer;
   905	  FAR struct ap_buffer_s *apb;
   906	  i2s_callback_t callback;
   907	  FAR void *callback_arg;
   908	  int result;
   909	  uint32_t irq_status;
   910	  irqstate_t flags;
   911	  size_t logical_bytes;
   912	  size_t raw_bytes;
   913	  size_t logical_samples;
   914	  size_t dma_bytes;
   915	  size_t dma_samples;
   916	  unsigned int i;
   917	
   918	  for (; ;)
   919	    {
   920	      flags = spin_lock_irqsave(&priv->lock);
   921	      xfer = priv->done_head;
   922	      if (xfer != NULL)
   923	        {
   924	          priv->done_head = xfer->next;
   925	          if (priv->done_head == NULL)
   926	            {
   927	              priv->done_tail = NULL;
   928	            }
   929	
   930	          xfer->next = NULL;
   931	        }
   932	
   933	      irq_status = priv->irq_status;
   934	      spin_unlock_irqrestore(&priv->lock, flags);
   935	
   936	      if (xfer == NULL)
   937	        {
   938	          return;
   939	        }
   940	
   941	      result = xfer->result;
   942	      logical_bytes = xfer->logical_bytes;
   943	      raw_bytes = xfer->raw_bytes;
   944	      logical_samples = logical_bytes / sizeof(int16_t);
   945	      dma_bytes = contest_i2s_rx_completed_bytes(xfer);
   946	      dma_samples = dma_bytes / sizeof(uint32_t);
   947	
   948	      if (result >= 0 &&
   949	          (logical_bytes == 0 ||
   950	           raw_bytes != logical_samples * sizeof(uint32_t) ||
   951	           dma_bytes != raw_bytes ||
   952	           dma_bytes % sizeof(uint32_t) != 0))
   953	        {
   954	          result = -EIO;
   955	        }
   956	
   957	      up_invalidate_dcache((uintptr_t)xfer->raw,
   958	                           (uintptr_t)xfer->raw + raw_bytes);
   959	
   960	      if (priv->diagnostics_enabled && xfer->dma_diag)
   961	        {
   962	          contest_i2s_capture_rx_dma_diag(priv, xfer);
   963	          xfer->dma_diag = false;
   964	        }
   965	
   966	      if (result >= 0)
   967	        {
   968	          FAR int16_t *pcm = (FAR int16_t *)(xfer->apb->samp +
   969	                                             xfer->apb->curbyte);
   970	
   971	          /* Only convert words that hardware reports as received.  A short
   972	           * transaction is rejected above, so unwritten sentinel/old data
   973	           * can never be exposed as a successful PCM frame. */
   974	
   975	          for (i = 0; i < dma_samples; i++)
   976	            {
   977	              pcm[i] = (int16_t)((int32_t)xfer->raw[i] >>
   978	                                 CONTEST_I2S_RX_PCM_SHIFT);
   979	            }
   980	
   981	          /* Preserve the first clearly non-silent frame for post-stop
   982	           * diagnostics.  Raw words are never printed while recording.
   983	           */
   984	
   985	          if (priv->diagnostics_enabled && !priv->raw_logged &&
   986	              contest_i2s_rx_has_signal(pcm, dma_samples))
   987	            {
   988	              memcpy(priv->raw_diag, xfer->raw, raw_bytes);
   989	              priv->raw_diag_words = dma_samples;
   990	              priv->raw_logged = true;
   991	            }
   992	
   993	          xfer->apb->nbytes = logical_bytes;
   994	          xfer->apb->nsamples = logical_samples;
   995	        }
   996	      else
   997	        {
   998	          xfer->apb->nbytes = 0;
   999	          xfer->apb->nsamples = 0;
  1000	        }
  1001	
  1002	      apb = xfer->apb;
  1003	      callback = xfer->callback;
  1004	      callback_arg = xfer->arg;
  1005	
  1006	      /* Conversion is complete.  Admit a replacement before invoking the
  1007	       * upper callback, exactly as the upstream done queue permits.
  1008	       */
  1009	
  1010	      flags = spin_lock_irqsave(&priv->lock);
  1011	      xfer->in_use = false;
  1012	      spin_unlock_irqrestore(&priv->lock, flags);
  1013	
