  1224	#ifndef CONFIG_AUDIO_EXCLUDE_PAUSE_RESUME
  1225	#ifdef CONFIG_AUDIO_MULTI_SESSION
  1226	static int contest_media_pause(FAR struct audio_lowerhalf_s *dev,
  1227	                               FAR void *session)
  1228	#else
  1229	static int contest_media_pause(FAR struct audio_lowerhalf_s *dev)
  1230	#endif
  1231	{
  1232	  FAR struct contest_media_sink_s *sink =
  1233	    (FAR struct contest_media_sink_s *)dev;
  1234	  int ret = OK;
  1235	#ifdef CONFIG_AUDIO_MULTI_SESSION
  1236	  (void)session;
  1237	#endif
  1238	  if (nxsem_wait_uninterruptible(&sink->playback_lock) < 0) return -EINTR;
  1239	  if (sink->playback_open)
  1240	    {
  1241	      /* Media's player reports source-side xrun through AUDIOIOC_PAUSE while
  1242	       * abufsrc has temporarily run dry.  Freezing the private I2S ring here
  1243	       * would prevent its queued PCM from draining, block the graph writer,
  1244	       * and make RESUME unreachable.  Keep DMA moving; empty periods are
  1245	       * already filled with silence by the playback worker. */
  1246	      sink->paused = true;
  1247	    }
  1248	  nxsem_post(&sink->playback_lock);
  1249	  /* Empty input is an underrun or a pause, never a declaration of EOF. */
  1250	  return ret;
  1251	}
