  1279	static int contest_media_enqueue_internal(FAR struct audio_lowerhalf_s *dev,
  1280	                                          FAR struct ap_buffer_s *apb)
  1281	{
  1282	  FAR struct contest_media_sink_s *sink =
  1283	    (FAR struct contest_media_sink_s *)dev;
  1284	  size_t len;
  1285	  int ret;
  1286	  bool final;
  1287	
  1288	  if (apb == NULL || apb->curbyte > apb->nbytes)
  1289	    {
  1290	      return -EINVAL;
  1291	    }
  1292	
  1293	  len = (size_t)apb->nbytes - (size_t)apb->curbyte;
  1294	  final = (apb->flags & AUDIO_APB_FINAL) != 0;
  1295	  if ((len & 1) != 0) return -EINVAL;
  1296	  /* A bounded APB must fit before START, when DMA intentionally consumes
  1297	   * nothing. Reject oversized client buffers rather than blocking forever. */
  1298	  if (len > CONTEST_MEDIA_BUFFER_BYTES) return -EMSGSIZE;
  1299	
  1300	  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) || sink->eos)
  1301	    {
  1302	      return -EPIPE;
  1303	    }
  1304	
  1305	  /* Fail before committing PCM if no ownership slot is available. */
  1306	  ret = nxsem_wait_uninterruptible(&sink->pace_lock);
  1307	  if (ret < 0) return ret;
  1308	  bool full = sink->pace_count + (sink->pace_busy ? 1 : 0) >=
  1309	              CONTEST_MEDIA_PACE_QUEUE;
  1310	  nxsem_post(&sink->pace_lock);
  1311	  if (full) return -EAGAIN;
  1312	
  1313	  /* Be tolerant of clients that enqueue before AUDIOIOC_START.  The NuttX
  1314	   * upper-half still requires CONFIGURE first, and open_playback() enforces
  1315	   * that contract. */
  1316	  ret = contest_media_open_playback(sink);
  1317	  if (ret < 0)
  1318	    {
  1319	      return ret;
  1320	    }
  1321	
  1322	  if (len > 0)
  1323	    {
  1324	      ret = contest_media_write_music_pcm(&apb->samp[apb->curbyte], len);
  1325	      if (ret < 0)
  1326	        {
  1327	          syslog(LOG_ERR, "[MEDIA-BRIDGE] write failed len=%zu rc=%d\n",
  1328	                 len, ret);
  1329	          return ret;
  1330	        }
  1331	
  1332	      sink->total_pcm += len;
  1333	      __atomic_store_n(&sink->last_pcm_ms,
  1334	                       (uint32_t)contest_media_now_ms(),
  1335	                       __ATOMIC_RELEASE);
  1336	      sink->enqueue_count++;
  1337	      apb->curbyte = apb->nbytes;
  1338	
  1339	      if (sink->enqueue_count <= 4 || (sink->enqueue_count % 32) == 0)
  1340	        {
  1341	          syslog(LOG_INFO,
  1342	                 "[MEDIA-BRIDGE] PCM enqueue #%u bytes=%zu total=%zu final=%d\n",
  1343	                 sink->enqueue_count, len, sink->total_pcm, final ? 1 : 0);
  1344	        }
  1345	    }
  1346	
  1347	  /* Retain the APB until its PCM-duration slot on the Media timeline. */
  1348	  if (final)
  1349	    {
  1350	      syslog(LOG_INFO,
  1351	             "[MEDIA-BRIDGE] FINAL APB received bytes=%zu "
  1352	             "pcm_total=%zu dequeued=%zu\n",
  1353	             len, sink->total_pcm, sink->dequeued_pcm);
  1354	    }
  1355	
  1356	  if (final)
  1357	    {
  1358	      sink->eos = true;
  1359	      /* Nonblocking EOS wakes even a file shorter than the startup water
  1360	       * mark. Waiting for FINAL's dequeue before EOS would deadlock. */
  1361	      if (nxsem_wait_uninterruptible(&sink->playback_lock) < 0) return -EINTR;
  1362	      ret = sink->started ? robot_audio_playback_end_input() : OK;
  1363	      nxsem_post(&sink->playback_lock);
  1364	      if (ret < 0) return ret;
  1365	    }
  1366	
  1367	  ret = contest_media_queue_apb(sink, apb, len, final);
  1368	  if (ret < 0)
  1369	    {
  1370	      syslog(LOG_ERR,
  1371	             "[MEDIA-BRIDGE] queue APB failed bytes=%zu final=%d rc=%d\n",
  1372	             len, final ? 1 : 0, ret);
  1373	      return ret;
  1374	    }
  1375	
  1376	  return OK;
  1377	}
  1378	
  1379	static int contest_media_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
  1380	                                       FAR struct ap_buffer_s *apb)
  1381	{
  1382	  FAR struct contest_media_sink_s *sink = (FAR void *)dev;
  1383	  int ret = nxsem_wait_uninterruptible(&sink->enqueue_lock);
  1384	  if (ret < 0) return ret;
  1385	  ret = contest_media_enqueue_internal(dev, apb);
  1386	  nxsem_post(&sink->enqueue_lock);
  1387	  return ret;
  1388	}
