  1390	static int contest_media_ioctl(FAR struct audio_lowerhalf_s *dev,
  1391	                               int cmd, unsigned long arg)
  1392	{
  1393	  FAR struct contest_media_sink_s *sink =
  1394	    (FAR struct contest_media_sink_s *)dev;
  1395	
  1396	  switch (cmd)
  1397	    {
  1398	      case AUDIOIOC_GETBUFFERINFO:
  1399	        {
  1400	          FAR struct ap_buffer_info_s *info =
  1401	            (FAR struct ap_buffer_info_s *)((uintptr_t)arg);
  1402	
  1403	          if (info == NULL)
  1404	            {
  1405	              return -EINVAL;
  1406	            }
  1407	
  1408	          info->nbuffers = CONTEST_MEDIA_NBUFFERS;
  1409	          info->buffer_size = CONTEST_MEDIA_BUFFER_BYTES;
  1410	          syslog(LOG_INFO,
  1411	                 "[MEDIA-BRIDGE] GETBUFFERINFO nbuffers=%u bytes=%u\n",
  1412	                 CONTEST_MEDIA_NBUFFERS, CONTEST_MEDIA_BUFFER_BYTES);
  1413	          return OK;
  1414	        }
  1415	
  1416	      case AUDIOIOC_SETBUFFERINFO:
  1417	        /* GETBUFFERINFO is authoritative: the native playback ring and DMA
  1418	         * geometry are private to the backend, not set by a Media period. */
  1419	        return OK;
  1420	
  1421	      case AUDIOIOC_GETPOSITION:
  1422	        {
  1423	          FAR long *position =
  1424	            (FAR long *)((uintptr_t)arg);
  1425	          size_t bytes_per_frame;
  1426	
  1427	          if (position == NULL)
  1428	            {
  1429	              return -EINVAL;
  1430	            }
  1431	
  1432	          bytes_per_frame =
  1433	            (size_t)sink->channels * (size_t)sink->bits / 8;
  1434	
  1435	          if (bytes_per_frame == 0)
  1436	            {
  1437	              bytes_per_frame =
  1438	                CONTEST_MEDIA_CHANNELS * (CONTEST_MEDIA_BITS / 8);
  1439	            }
  1440	
  1441	          uint64_t completed;
  1442	          uint64_t pending;
  1443	          int ret = contest_media_progress(sink, &completed, &pending, NULL);
  1444	          if (ret < 0) return ret;
  1445	          *position = (long)(completed / bytes_per_frame);
  1446	          return OK;
  1447	        }
  1448	
  1449	      case AUDIOIOC_GETLATENCY:
  1450	        {
  1451	          FAR long *latency =
  1452	            (FAR long *)((uintptr_t)arg);
  1453	
  1454	          if (latency == NULL)
  1455	            {
  1456	              return -EINVAL;
  1457	            }
  1458	
  1459	          uint64_t completed;
  1460	          uint64_t pending;
  1461	          int ret = contest_media_progress(sink, &completed, &pending, NULL);
  1462	          if (ret < 0) return ret;
  1463	          *latency = (long)(pending / (CONTEST_MEDIA_CHANNELS *
  1464	                                      (CONTEST_MEDIA_BITS / 8)));
  1465	          return OK;
  1466	        }
  1467	
  1468	      case AUDIOIOC_FLUSH:
  1469	        {
  1470	          bool restart = sink->started;
  1471	#ifndef CONFIG_AUDIO_EXCLUDE_PAUSE_RESUME
  1472	          bool paused = sink->paused;
  1473	#endif
  1474	          syslog(LOG_INFO, "[MEDIA-BRIDGE] FLUSH\n");
  1475	          (void)contest_media_abort_pending(sink);
  1476	          int ret = contest_media_finish_playback(sink, false);
  1477	          sink->eos = false;
  1478	          __atomic_store_n(&sink->completion_sent, false, __ATOMIC_RELEASE);
  1479	          sink->stream_error = OK;
  1480	          /* ff_nuttx_flush() keeps its running flag. Re-arm the lower half
  1481	           * here; the client will not send a new START after a seek/flush. */
  1482	          if (ret == OK && restart)
  1483	            {
  1484	#ifdef CONFIG_AUDIO_MULTI_SESSION
  1485	              ret = contest_media_start(dev, sink);
  1486	#else
  1487	              ret = contest_media_start(dev);
  1488	#endif
  1489	#ifndef CONFIG_AUDIO_EXCLUDE_PAUSE_RESUME
  1490	              if (ret == OK && paused)
  1491	                {
  1492	#ifdef CONFIG_AUDIO_MULTI_SESSION
  1493	                  ret = contest_media_pause(dev, sink);
  1494	#else
  1495	                  ret = contest_media_pause(dev);
  1496	#endif
  1497	                }
  1498	#endif
  1499	            }
  1500	          return ret;
  1501	        }
  1502	
  1503	      default:
  1504	        return -ENOTTY;
  1505	    }
  1506	}
