  if (final)
    {
      syslog(LOG_INFO,
             "[MEDIA-BRIDGE] FINAL APB received bytes=%zu "
             "pcm_total=%zu dequeued=%zu\n",
             len, sink->total_pcm, sink->dequeued_pcm);
    }

  if (final)
    {
