      ret = sink->started ? robot_audio_playback_end_input() : OK;
      nxsem_post(&sink->playback_lock);
      if (ret < 0) return ret;
    }

  ret = contest_media_queue_apb(sink, apb, len, final);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "[MEDIA-BRIDGE] queue APB failed bytes=%zu final=%d rc=%d\n",
             len, final ? 1 : 0, ret);
      return ret;
    }

  return OK;
}

