  2184	  FAR struct contest_i2s_xfer_s *xfer;
  2185	  FAR struct ap_buffer_s *apb;
  2186	  i2s_callback_t callback;
  2187	  FAR void *callback_arg;
  2188	  uint32_t irq_status;
