  2245	          memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
  2246	          up_clean_dcache((uintptr_t)xfer->dma_data,
  2247	                          (uintptr_t)xfer->dma_data +
  2248	                          CONTEST_I2S_TX_SLOT_BYTES);
  2249	        }
