  2251	      spin_unlock_irqrestore(&priv->lock, flags);
  2252	
  2253	      if (result < 0)
  2254	        {
  2255	          syslog(LOG_ERR,
  2256	                 "[C-I2S] tx completion failed irq=%08lx bytes=%zu rc=%d\n",
  2257	                 (unsigned long)irq_status, nbytes, result);
  2258	        }
  2259	
  2260	      if (callback != NULL && apb != NULL)
  2261	        {
  2262	          callback(&priv->dev, apb, callback_arg, result);
  2263	          apb_free(apb);
  2264	        }
