  2458	       * tx_stop_work above.
  2459	       */
  2460	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
  2461	    }
  2462	
  2463	  spin_unlock_irqrestore(&priv->lock, flags);
  2464	  return OK;
  2465	}
