   740	
   741	      int wait_ret = nxsem_tickwait_uninterruptible(
   742	        &sink->pace_data, MSEC2TICK(CONTEST_MEDIA_HEALTH_POLL_MS));
   743	      if (wait_ret == -ETIMEDOUT || wait_ret == -ETIME)
   744	        {
   745	          contest_media_check_health(sink);
   746	          continue;
   747	        }
