   768	              if (contest_media_pace_aborted(sink))
   769	                {
   770	                  ret = -ECANCELED;
   771	                }
   772	            }
   773	
   774	          /* Keep diagnostics tied to the real backend, while APB ownership
   775	           * follows the Media pacing timeline above. */
