   777	            {
   778	              dma_done = played >= entry.endpoint;
   779	            }
   780	
   781	          /* STOP can arrive while waiting. Do not turn that cancellation
   782	           * into natural EOS or finish()/drain the queued music. */
   783	          aborted = contest_media_pace_aborted(sink);
   784	          if (ret < 0 && !aborted)
