   792	
   793	          if (sink->dequeue_count <= 4 ||
   794	              (sink->dequeue_count % 32) == 0 ||
   795	              entry.final)
   796	            {
   797	              syslog(LOG_INFO,
   798	                     "[MEDIA-BRIDGE] PCM dequeue #%u bytes=%zu "
   799	                     "dma_done=%d final=%d played=%zu copied=%zu\n",
   800	                     sink->dequeue_count, entry.bytes,
   801	                     dma_done ? 1 : 0, entry.final ? 1 : 0,
   802	                     (size_t)played, sink->total_pcm);
