711	/* The generic ESP32-S3 helper splits a 4096-byte RX request into 4095+1.
712	 * With the I2S RX EOF unit used by this board, that layout can terminate
713	 * after the first short descriptor.  Keep RX descriptors 4-byte aligned and
714	 * use two equal buffers for the normal 4096-byte transaction.
715	 */
716	
717	static uint32_t contest_i2s_dma_setup_rx(
718	  FAR struct esp32s3_dmadesc_s *desc, uint32_t count,
719	  FAR uint8_t *buffer, uint32_t bytes)
720	{
721	  uint32_t offset = 0;
722	  uint32_t i;
723	
724	  memset(desc, 0, count * sizeof(*desc));
725	
726	  for (i = 0; i < count && offset < bytes; i++)
727	    {
728	      uint32_t length = bytes - offset;
729	
730	      if (length > CONTEST_I2S_RX_DESC_BYTES)
731	        {
732	          length = CONTEST_I2S_RX_DESC_BYTES;
733	        }
734	
735	      desc[i].ctrl = ESP32S3_DMA_CTRL_OWN |
736	                     (length << ESP32S3_DMA_CTRL_BUFLEN_S);
737	      desc[i].pbuf = buffer + offset;
738	      offset += length;
739	      desc[i].next = offset < bytes ? &desc[i + 1] : NULL;
740	    }
741	
742	  return offset;
743	}
744	
745	/* The local ESP32-S3 reference lower-half writes its eof_nbytes directly to
746	 * I2S_RX_EOF_NUM.  Keep this board-local experiment in the same byte-count
747	 * unit; do not derive the field from the 32-bit container width.
748	 */
749	
750	static uint32_t contest_i2s_rx_eof_value(size_t raw_bytes)
751	{
752	  DEBUGASSERT(raw_bytes <= I2S_RX_EOF_NUM_V);
753	  return raw_bytes;
754	}
