756	static size_t contest_i2s_rx_completed_bytes(
757	  FAR const struct contest_i2s_rx_xfer_s *xfer)
758	{
759	  size_t bytes = 0;
760	  unsigned int i;
761	
762	  for (i = 0; i < CONTEST_I2S_DMA_DESC_COUNT; i++)
763	    {
764	      uint32_t length = (xfer->desc[i].ctrl >> ESP32S3_DMA_CTRL_DATALEN_S) &
765	                        ESP32S3_DMA_CTRL_DATALEN_V;
766	
767	      bytes += length;
768	      if (xfer->desc[i].next == NULL)
769	        {
770	          break;
771	        }
772	    }
773	
774	  return bytes > xfer->raw_bytes ? xfer->raw_bytes : bytes;
775	}
