800	static void contest_i2s_set_rate(FAR struct contest_i2s_s *priv)
801	{
802	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
803	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
804	  uint32_t remainder = CONTEST_I2S_SOURCE_CLOCK % mclk;
805	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS *
806	                  CONTEST_INMP441_SLOT_BITS;
807	  uint32_t bclk_div = mclk / bclk;
808	  uint32_t regval;
809	  uint32_t numerator = 0;
810	  uint32_t denominator = 1;
811	  uint32_t a;
812	
813	  /* Match the ESP32-S3 reference driver's CLK160 fractional divider. */
814	
815	  if (remainder != 0)
816	    {
817	      for (a = 2; a <= 63; a++)
818	        {
819	          uint32_t b = (remainder * a + mclk / 2) / mclk;
820	
821	          if (b != 0 && remainder * a == mclk * b)
822	            {
823	              numerator = b;
824	              denominator = a;
825	              break;
826	            }
827	        }
828	    }
829	
830	  if (numerator == 0)
831	    {
832	      denominator = 1;
833	    }
834	
835	  regval = getreg32(I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
836	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
837	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
838	  putreg32(regval, I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
839	
840	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
841	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
842	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
843	  if (numerator != 0)
844	    {
