   581	/* Return Media APBs at the PCM consumption rate.  The native playback ring
   582	 * and I2S DMA continue independently; waiting for each DMA callback here
   583	 * starves adevsink of APBs and makes it report a false xrun after four
   584	 * buffers.  Use one absolute timeline so scheduler delay does not accumulate
   585	 * into audible gaps. */
   586	static void contest_media_pace_delay(FAR struct contest_media_sink_s *sink,
   587	                                     size_t bytes)
   588	{
   589	  uint64_t duration;
   590	
   591	  if (bytes == 0)
   592	    {
   593	      return;
   594	    }
   595	
   596	  duration = ((uint64_t)bytes * 1000000ULL +
   597	              CONTEST_MEDIA_BYTES_PER_SEC - 1) /
   598	             CONTEST_MEDIA_BYTES_PER_SEC;
   599	
   600	  uint64_t now = contest_media_now_us();
   601	  if (!sink->pace_clock_valid || now == 0)
   602	    {
   603	      sink->pace_deadline_us = now + duration;
   604	      sink->pace_clock_valid = true;
   605	    }
   606	  else
   607	    {
   608	      sink->pace_deadline_us += duration;
   609	    }
   610	
   611	  for (;;)
   612	    {
   613	      if (contest_media_pace_aborted(sink))
   614	        {
   615	          return;
   616	        }
   617	
   618	      now = contest_media_now_us();
   619	      if (now == 0 || now >= sink->pace_deadline_us)
   620	        {
   621	          return;
   622	        }
   623	
   624	      uint64_t remain = sink->pace_deadline_us - now;
   625	      unsigned int slice = remain > CONTEST_MEDIA_PACE_SLICE_US ?
   626	                           CONTEST_MEDIA_PACE_SLICE_US :
   627	                           (unsigned int)remain;
