   717	/* The generic ESP32-S3 helper splits a 4096-byte RX request into 4095+1.
   718	 * With the I2S RX EOF unit used by this board, that layout can terminate
   719	 * after the first short descriptor.  Keep RX descriptors 4-byte aligned and
   720	 * use two equal buffers for the normal 4096-byte transaction.
   721	 */
   722	
   723	static uint32_t contest_i2s_dma_setup_rx(
   724	  FAR struct esp32s3_dmadesc_s *desc, uint32_t count,
   725	  FAR uint8_t *buffer, uint32_t bytes)
   726	{
   727	  uint32_t offset = 0;
   728	  uint32_t i;
   729	
   730	  memset(desc, 0, count * sizeof(*desc));
   731	
   732	  for (i = 0; i < count && offset < bytes; i++)
   733	    {
   734	      uint32_t length = bytes - offset;
   735	
   736	      if (length > CONTEST_I2S_RX_DESC_BYTES)
   737	        {
   738	          length = CONTEST_I2S_RX_DESC_BYTES;
   739	        }
   740	
   741	      desc[i].ctrl = ESP32S3_DMA_CTRL_OWN |
   742	                     (length << ESP32S3_DMA_CTRL_BUFLEN_S);
   743	      desc[i].pbuf = buffer + offset;
   744	      offset += length;
   745	      desc[i].next = offset < bytes ? &desc[i + 1] : NULL;
   746	    }
   747	
   748	  return offset;
   749	}
   750	
   751	/* The local ESP32-S3 reference lower-half writes its eof_nbytes directly to
   752	 * I2S_RX_EOF_NUM.  Keep this board-local experiment in the same byte-count
   753	 * unit; do not derive the field from the 32-bit container width.
   754	 */
   755	
   756	static uint32_t contest_i2s_rx_eof_value(size_t raw_bytes)
   757	{
   758	  size_t words;
   759	
   760	  if (raw_bytes == 0 || raw_bytes % sizeof(uint32_t) != 0)
   761	    {
   762	      return UINT32_MAX;
   763	    }
   764	
   765	  words = raw_bytes / sizeof(uint32_t);
   766	  if (words == 0 || words - 1 > I2S_RX_EOF_NUM_V)
   767	    {
   768	      return UINT32_MAX;
   769	    }
   770	
   771	  /* I2S_RX_EOF_NUM counts 32-bit words and is encoded as count - 1. */
   772	  return (uint32_t)(words - 1);
