2425	
2426	static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
2427	{
2428	  FAR struct contest_i2s_tx_s *priv = arg;
2429	  FAR struct contest_i2s_xfer_s *xfer;
2430	  uint32_t status;
2431	  unsigned int slot;
2432	  unsigned int i;
2433	  bool schedule = false;
2434	  bool terminal_stop_schedule = false;
2435	  bool fatal = false;
2436	  irqstate_t flags;
2437	
2438	  (void)irq;
2439	  (void)context;
2440	
2441	  /* OUT_DONE is the per-descriptor completion event for the sequential ring. */
2442	  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
2443	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
2444	
2445	  if ((status & (DMA_OUT_DONE_CH0_INT_ST |
2446	                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
2447	    {
2448	      return OK;
2449	    }
2450	
2451	  flags = spin_lock_irqsave(&priv->lock);
2452	  priv->irq_status = status;
2453	
2454	  if (!priv->streaming || !priv->hw_running)
2455	    {
2456	      spin_unlock_irqrestore(&priv->lock, flags);
2457	      return OK;
2458	    }
2459	
2460	  if ((status & DMA_OUT_DSCR_ERR_CH0_INT_ST) != 0)
2461	    {
2462	      fatal = true;
2463	    }
2464	  else
2465	    {
2466	      /* The descriptor ring is immutable and advances in slot order.  Its
2467	       * payload remains stable until the deferred callback below runs; do not
2468	       * wait one extra ring block and replay stale PCM. */
2469	      if ((status & DMA_OUT_DONE_CH0_INT_ST) != 0)
2470	        {
2471	          priv->done_irq_count++;
2472	
2473	          bool terminal_done;
2474	
2475	          slot = priv->done_index;
2476	          terminal_done = priv->xfer[slot].terminal;
2477	
2478	          if (terminal_done)
2479	            {
2480	              /*
2481	               * OUT_DONE means GDMA finished the descriptor, but the I2S FIFO
2482	               * / shifter may still contain the final samples. Do not stop HW
2483	               * or publish the terminal callback until the drain delay passes.
2484	               */
2485	              priv->streaming = false;
2486	              priv->terminal_stop_pending = true;
2487	              priv->terminal_stop_slot = (uint8_t)slot;
2488	              terminal_stop_schedule = true;
2489	            }
2490	          else if (contest_i2s_tx_complete_slot(priv, slot))
2491	            {
2492	              schedule = true;
2493	            }
2494	
2495	          priv->done_index = (slot + 1) % priv->ring_slots;
2496	          if (slot + 1 == priv->ring_slots)
2497	            {
2498	              priv->ring_wrap_count++;
2499	            }
2500	
2501	        }
2502	
2503	    }
2504	
2505	  if (fatal)
2506	    {
2507	      for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
2508	        {
2509	          xfer = &priv->xfer[i];
2510	          if (xfer->in_use && !xfer->done_queued)
2511	            {
2512	              xfer->result = -EIO;
2513	              xfer->done_queued = true;
2514	              contest_i2s_tx_done_push(priv, xfer);
2515	              schedule = true;
2516	            }
2517	        }
2518	
2519	      priv->queued_slots = 0;
2520	      priv->streaming = false;
2521	      priv->terminal_stop_pending = false;
2522	      contest_i2s_tx_stop_hw(priv);
2523	    }
2524	
2525	  if (terminal_stop_schedule)
2526	    {
2527	      int ret = contest_i2s_tx_schedule_stop_locked(
2528	        priv, MSEC2TICK(CONTEST_I2S_TX_FIFO_DRAIN_MS));
2529	
2530	      if (ret < 0 && ret != -EBUSY)
2531	        {
2532	          /* Defensive fallback: never leave I2S running forever. */
2533	          priv->terminal_stop_pending = false;
2534	          contest_i2s_tx_stop_hw(priv);
2535	          if (contest_i2s_tx_complete_slot(priv, priv->terminal_stop_slot))
2536	            {
2537	              schedule = true;
2538	            }
2539	          syslog(LOG_ERR,
2540	                 "[C-I2S] terminal drain worker busy; immediate fallback\n");
2541	        }
2542	    }
2543	
2544	  if (schedule)
2545	    {
2546	      /*
2547	       * Normal OUT_DONE callbacks are immediate.  Keeping the old 8 ms delay
2548	       * here increased refill latency and let the cyclic DMA ring run ahead of
2549	       * the logical producer near EOF.  Terminal FIFO drain is handled only by
2550	       * tx_stop_work above.
2551	       */
2552	      (void)contest_i2s_tx_schedule_work_locked(priv);
2553	    }
2554	
2555	  spin_unlock_irqrestore(&priv->lock, flags);
2556	  return OK;
2557	}
