1587	static int contest_i2s_tx_bind_slot(FAR struct contest_i2s_tx_s *priv,
1588	                                    unsigned int slot,
1589	                                    FAR struct ap_buffer_s *apb,
1590	                                    size_t wire_bytes, bool terminal)
1591	{
1592	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer[slot];
1593	  uint32_t queued;
1594	  int ret;
1595	
1596	  DEBUGASSERT(apb != NULL);
1597	  DEBUGASSERT(apb->samp != NULL);
1598	  DEBUGASSERT(!priv->hw_running);
1599	
1600	  if (xfer->dma_bound)
1601	    {
1602	      return OK;
1603	    }
1604	
1605	  if (xfer->dma_data == NULL)
1606	    {
1607	      return -ENOMEM;
1608	    }
1609	
1610	  if (wire_bytes == 0 || wire_bytes > CONTEST_I2S_TX_SLOT_BYTES ||
1611	      (wire_bytes & 3) != 0)
1612	    {
1613	      return -EINVAL;
1614	    }
1615	
1616	  memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
1617	
1618	  if (priv->logical_width == 16)
1619	    {
1620	      FAR const int16_t *src =
1621	        (FAR const int16_t *)(apb->samp + apb->curbyte);
1622	      FAR uint32_t *dst = (FAR uint32_t *)xfer->dma_data;
1623	      unsigned int i;
1624	
1625	      for (i = 0; i < wire_bytes / sizeof(uint32_t); i++)
1626	        {
1627	          /* Sign-extend PCM16 into the high half of the 32-bit Philips
1628	           * slot.  Do not reinterpret the input buffer as 32-bit data. */
1629	          dst[i] = ((uint32_t)(int32_t)src[i]) << 16;
1630	        }
1631	    }
1632	  else
1633	    {
1634	      memcpy(xfer->dma_data, apb->samp + apb->curbyte,
1635	             wire_bytes);
1636	    }
1637	  up_clean_dcache((uintptr_t)xfer->dma_data,
1638	                  (uintptr_t)xfer->dma_data + CONTEST_I2S_TX_SLOT_BYTES);
1639	
1640	  memset(xfer->desc, 0, sizeof(xfer->desc));
1641	  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
1642	                              xfer->dma_data, wire_bytes,
1643	                              true, priv->dma_channel);
1644	  if (queued != wire_bytes)
1645	    {
1646	      memset(xfer->desc, 0, sizeof(xfer->desc));
1647	      return -ENOMEM;
1648	    }
1649	
1650	  ret = contest_i2s_tx_desc_last(xfer, NULL);
1651	  if (ret < 0)
1652	    {
1653	      memset(xfer->desc, 0, sizeof(xfer->desc));
1654	      return ret;
1655	    }
1656	
1657	  if (terminal)
1658	    {
1659	      xfer->desc[xfer->desc_last].next = NULL;
1660	      up_clean_dcache((uintptr_t)xfer->desc,
1661	                      (uintptr_t)xfer->desc + sizeof(xfer->desc));
1662	    }
1663	
1664	  xfer->dma_bound = true;
1665	  priv->bound_slots++;
1666	
1667	  return OK;
1668	}
