1670	/* Prime slots that do not have an APB yet with silence descriptors.  The
1671	 * media bridge submits one block and waits for its callback before submitting
1672	 * the next one, so the immutable ring must be armed before all slots carry
1673	 * real APBs.  Later sends reuse these descriptors in place. */
1674	
1675	static int contest_i2s_tx_bind_silence_slots(
1676	  FAR struct contest_i2s_tx_s *priv)
1677	{
1678	  FAR struct contest_i2s_xfer_s *xfer;
1679	  uint32_t queued;
1680	  unsigned int i;
1681	  int ret;
1682	
1683	  DEBUGASSERT(!priv->hw_running);
1684	
1685	  for (i = 0; i < priv->ring_slots; i++)
1686	    {
1687	      xfer = &priv->xfer[i];
1688	      if (xfer->dma_bound)
1689	        {
1690	          continue;
1691	        }
1692	
1693	      if (xfer->dma_data == NULL)
1694	        {
1695	          return -ENOMEM;
1696	        }
1697	
1698	      memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
1699	      up_clean_dcache((uintptr_t)xfer->dma_data,
1700	                      (uintptr_t)xfer->dma_data + CONTEST_I2S_TX_SLOT_BYTES);
1701	
1702	      memset(xfer->desc, 0, sizeof(xfer->desc));
1703	      queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
1704	                                  xfer->dma_data,
1705	                                  CONTEST_I2S_TX_SLOT_BYTES, true,
1706	                                  priv->dma_channel);
1707	      if (queued != CONTEST_I2S_TX_SLOT_BYTES)
1708	        {
1709	          memset(xfer->desc, 0, sizeof(xfer->desc));
1710	          return -ENOMEM;
1711	        }
1712	
1713	      ret = contest_i2s_tx_desc_last(xfer, NULL);
1714	      if (ret < 0)
1715	        {
1716	          memset(xfer->desc, 0, sizeof(xfer->desc));
1717	          return ret;
1718	        }
1719	
1720	      xfer->terminal = false;
1721	      xfer->dma_bound = true;
1722	      priv->bound_slots++;
1723	    }
1724	
1725	  return OK;
1726	}
