1728	static int contest_i2s_tx_link_immutable_ring(
1729	  FAR struct contest_i2s_tx_s *priv, bool finite)
1730	{
1731	  FAR struct contest_i2s_xfer_s *xfer;
1732	  FAR struct contest_i2s_xfer_s *next;
1733	  unsigned int i;
1734	
1735	  unsigned int count = finite ? priv->bound_slots : priv->ring_slots;
1736	
1737	  if (count == 0 || count > priv->ring_slots ||
1738	      (!finite && count != priv->ring_slots))
1739	    {
1740	      return -EAGAIN;
1741	    }
1742	
1743	  for (i = 0; i < count; i++)
1744	    {
1745	      xfer = &priv->xfer[i];
1746	
1747	      if (!xfer->dma_bound)
1748	        {
1749	          return -EINVAL;
1750	        }
1751	
1752	      if (xfer->terminal)
1753	        {
1754	          if (!finite || i + 1 != count)
1755	            {
1756	              return -EINVAL;
1757	            }
1758	          xfer->desc[xfer->desc_last].next = NULL;
1759	        }
1760	      else if (i + 1 < count)
1761	        {
1762	          next = &priv->xfer[i + 1];
1763	          if (!next->dma_bound)
1764	            {
1765	              return -EINVAL;
1766	            }
1767	          xfer->desc[xfer->desc_last].next = &next->desc[0];
1768	        }
1769	      else if (finite)
1770	        {
1771	          return -EINVAL;
1772	        }
1773	      else
1774	        {
1775	          next = &priv->xfer[0];
1776	          xfer->desc[xfer->desc_last].next = &next->desc[0];
1777	        }
1778	
1779	      up_clean_dcache((uintptr_t)xfer->desc,
1780	                      (uintptr_t)xfer->desc + sizeof(xfer->desc));
1781	    }
1782	
1783	  return OK;
1784	}
