1786	
1787	static bool contest_i2s_tx_complete_slot(
1788	  FAR struct contest_i2s_tx_s *priv, unsigned int slot)
1789	{
1790	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer[slot];
1791	  bool schedule = false;
1792	
1793	  /*
1794	   * The descriptor owns xfer->dma_data, never the upper APB.
1795	   *
1796	   * For a normal block, OUT_DONE means GDMA has already handed the payload to
1797	   * the I2S peripheral, so publish its completion immediately.  Delaying every
1798	   * normal callback makes refill lag behind the immutable cyclic ring and can
1799	   * let hardware lap the producer at EOF.
1800	   *
1801	   * Only a terminal-short descriptor gets the separate 8 ms FIFO/shifter
1802	   * drain in contest_i2s_tx_terminal_stop_worker().
1803	   */
1804	
1805	  if (xfer->in_use && !xfer->done_queued)
1806	    {
1807	      xfer->result = OK;
1808	      xfer->done_queued = true;
1809	      contest_i2s_tx_done_push(priv, xfer);
1810	      schedule = true;
1811	
1812	      if (priv->queued_slots > 0)
1813	        {
1814	          priv->queued_slots--;
1815	        }
1816	    }
1817	  else
1818	    {
1819	      priv->silence_done_count++;
1820	      priv->late_refill_count++;
1821	      priv->underrun_count++;
1822	    }
1823	
1824	  priv->done_count++;
1825	  priv->chained_count++;
1826	  return schedule;
1827	}
