1830	static void contest_i2s_tx_start_ring(FAR struct contest_i2s_tx_s *priv)
1831	{
1832	  DEBUGASSERT(!priv->hw_running);
1833	
1834	  CLR_GDMA_CH_BITS(DMA_OUT_CONF1_CH0_REG, priv->dma_channel,
1835	                   DMA_OUT_CHECK_OWNER_CH0);
1836	
1837	  esp32s3_dma_load(priv->xfer[0].desc, priv->dma_channel, true);
1838	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
1839	
1840	  /* OUT_DONE is the per-descriptor completion event used by the proven
1841	   * sequential ring on this board. */
1842	  SET_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
1843	                   DMA_OUT_DONE_CH0_INT_ENA |
1844	                   DMA_OUT_DSCR_ERR_CH0_INT_ENA);
1845	  CLR_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
1846	                   DMA_OUT_EOF_CH0_INT_ENA |
1847	                   DMA_OUT_TOTAL_EOF_CH0_INT_ENA);
1848	  esp32s3_dma_enable(priv->dma_channel, true);
1849	
1850	  contest_i2s_tx_update_wait();
1851	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_START);
1852	  priv->hw_running = true;
1853	  priv->dma_start_count++;
1854	
1855	  syslog(LOG_INFO,
1856	         "[C-I2S] tx GDMA-IMMUTABLE start=%lu slots=%u slot_bytes=%u "
1857	         "irq=DONE(sequential) descriptors=frozen\n",
1858	         (unsigned long)priv->dma_start_count,
1859	         priv->ring_slots, CONTEST_I2S_TX_SLOT_BYTES);
1860	}
