 664	/* Detect a stopped I2S DMA worker even when Media has not queued a FINAL
 665	 * buffer.  Without this poll, APBs already copied into the private PCM ring
 666	 * can be returned and the Media thread can then wait forever for an event. */
 667	static void contest_media_check_health(FAR struct contest_media_sink_s *sink)
