 775	static size_t contest_i2s_rx_completed_bytes(
 776	  FAR const struct contest_i2s_rx_xfer_s *xfer)
 777	{
 778	  size_t bytes = 0;
 779	  unsigned int i;
 780	
 781	  for (i = 0; i < CONTEST_I2S_DMA_DESC_COUNT; i++)
 782	    {
 783	      uint32_t length = (xfer->desc[i].ctrl >> ESP32S3_DMA_CTRL_DATALEN_S) &
 784	                        ESP32S3_DMA_CTRL_DATALEN_V;
 785	
 786	      bytes += length;
 787	      if (xfer->desc[i].next == NULL)
 788	        {
 789	          break;
 790	        }
 791	    }
 792	
 793	  return bytes > xfer->raw_bytes ? xfer->raw_bytes : bytes;
 794	}
