 819	static void contest_i2s_set_rate(FAR struct contest_i2s_s *priv)
 820	{
 821	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
 822	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
 823	  uint32_t remainder = CONTEST_I2S_SOURCE_CLOCK % mclk;
 824	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS *
 825	                  CONTEST_INMP441_SLOT_BITS;
 826	  uint32_t bclk_div = mclk / bclk;
 827	  uint32_t regval;
 828	  uint32_t numerator = 0;
 829	  uint32_t denominator = 1;
 830	  uint32_t a;
 831	
 832	  /* Match the ESP32-S3 reference driver's CLK160 fractional divider. */
 833	
 834	  if (remainder != 0)
 835	    {
 836	      for (a = 2; a <= 63; a++)
 837	        {
 838	          uint32_t b = (remainder * a + mclk / 2) / mclk;
 839	
 840	          if (b != 0 && remainder * a == mclk * b)
 841	            {
 842	              numerator = b;
 843	              denominator = a;
 844	              break;
 845	            }
 846	        }
 847	    }
 848	
 849	  if (numerator == 0)
 850	    {
 851	      denominator = 1;
 852	    }
 853	
 854	  regval = getreg32(I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
 855	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
 856	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
 857	  putreg32(regval, I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
 858	
 859	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
 860	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
 861	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
 862	  if (numerator != 0)
 863	    {
 864	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Z, numerator);
 865	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y, denominator % numerator);
 866	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_X,
 867	                               denominator / numerator - 1);
 868	    }
 869	
 870	  putreg32(regval, I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
 871	
 872	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_BCK_DIV_NUM_M,
 873	              FIELD_TO_VALUE(I2S_RX_BCK_DIV_NUM, bclk_div - 1));
 874	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_UPDATE);
 875	}
