1910	/* DMA payloads must stay in the kernel DRAM heap.  PSRAM application
1911	 * buffers are copied here; never replace kmm_memalign() with malloc().
1912	 * Failed attempts are rolled back before trying a smaller ring.
1913	 */
1914	
1915	static void contest_i2s_tx_free_dma_slots(FAR struct contest_i2s_tx_s *priv)
1916	{
1917	  FAR uint8_t *data;
1918	  unsigned int i;
1919	  irqstate_t flags;
1920	
1921	  for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
1922	    {
1923	      /* The completion worker clears payloads under the same spinlock.
1924	       * Detach before freeing so a canceled callback cannot touch freed RAM.
1925	       * START/STOP/SEND are serialized by control_lock.
1926	       */
1927	
1928	      flags = spin_lock_irqsave(&priv->lock);
1929	      data = priv->xfer[i].dma_data;
1930	      priv->xfer[i].dma_data = NULL;
1931	      priv->xfer[i].dma_bound = false;
1932	      spin_unlock_irqrestore(&priv->lock, flags);
1933	      kmm_free(data);
1934	    }
1935	
1936	  priv->ring_slots = 0;
1937	}
