1939	static int contest_i2s_tx_alloc_dma_slots(FAR struct contest_i2s_tx_s *priv)
1940	{
1941	  FAR struct contest_i2s_xfer_s *xfer;
1942	  unsigned int slots;
1943	  unsigned int minimum;
1944	  unsigned int i;
1945	
1946	  /* An explicit SETBUFFERINFO is an exact contract: do not silently change
1947	   * geometry after a client has sized its APB queue.  Such clients retry
1948	   * START with 16, 8, then 4 slots.  Clients using automatic selection must
1949	   * query GETBUFFERINFO again after START and before the first SEND.
1950	   */
1951	
1952	  minimum = priv->geometry_explicit ? priv->requested_slots :
1953	                                     CONTEST_I2S_TX_MIN_RING_SLOTS;
1954	  contest_i2s_tx_free_dma_slots(priv);
1955	
1956	  for (slots = priv->requested_slots; slots >= minimum; slots /= 2)
1957	    {
1958	      for (i = 0; i < slots; i++)
1959	        {
1960	          xfer = &priv->xfer[i];
1961	          xfer->dma_data = kmm_memalign(CONTEST_I2S_TX_DMA_ALIGN,
1962	                                        CONTEST_I2S_TX_SLOT_BYTES);
1963	          if (xfer->dma_data == NULL)
1964	            {
1965	              break;
1966	            }
1967	
1968	          memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
1969	          up_clean_dcache((uintptr_t)xfer->dma_data,
1970	                          (uintptr_t)xfer->dma_data +
1971	                          CONTEST_I2S_TX_SLOT_BYTES);
1972	        }
1973	
1974	      if (i == slots)
1975	        {
1976	          priv->ring_slots = (uint8_t)slots;
1977	          syslog(LOG_INFO,
1978	                 "[C-I2S] tx DMA ring selected slots=%u slot_bytes=%u "
1979	                 "total=%u requested=%u exact=%d\n",
1980	                 slots, CONTEST_I2S_TX_SLOT_BYTES,
1981	                 slots * CONTEST_I2S_TX_SLOT_BYTES,
1982	                 priv->requested_slots, priv->geometry_explicit ? 1 : 0);
1983	          return OK;
1984	        }
1985	
1986	      syslog(LOG_WARNING,
1987	             "[C-I2S] tx DMA allocation failed slot=%u/%u "
1988	             "slot_bytes=%u; rollback\n",
1989	             i, slots, CONTEST_I2S_TX_SLOT_BYTES);
1990	      contest_i2s_tx_free_dma_slots(priv);
1991	    }
1992	
1993	  return -ENOMEM;
1994	}
