335	/**
336	 * Send a reply to the quickapp process via the outbound mqueue.
337	 * Called from the outbound dispatch thread in the agent process.
338	 */
339	static void quickapp_mq_dispatch(const char *chat_id, const char *content)
340	{
341	    struct mq_attr attr = {
342	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
343	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
344	    };
345	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_WRONLY | O_CREAT, 0666, &attr);
346	    if (mq == (mqd_t)-1) {
347	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_open failed: %d\n", TAG, errno);
348	        return;
349	    }
350	
351	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
352	    if (!buf) {
353	        mq_close(mq);
354	        return;
355	    }
356	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, content);
357	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
358	        len = VELACLAW_MQ_MSG_SIZE - 1;
359	        buf[len] = '\0';
360	    }
361	
362	    if (mq_send(mq, buf, len + 1, 0) != 0) {
363	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_send failed: %d\n", TAG, errno);
364	    } else {
365	        syslog(LOG_INFO, "[%s] quickapp dispatch: reply sent chat_id=%s\n", TAG, chat_id);
366	    }
367	    free(buf);
368	    mq_close(mq);
369	}
