2380	/* Controller only. No Agent/TTS call occurs while holding the capture lock.
2381	 * Waiting for all submitted finals also protects the wake+compound-command
2382	 * case when the two HTTP workers return out of order. */
2383	static void rv_dispatch_pending(void)
2384	{
2385	  char routed[ROBOT_VOICE_TEXT_CAP];
2386	  bool failed;
2387	  int error;
2388	  bool notify = true;
2389	  unsigned long run_id;
2390	  unsigned long long now = robot_voice_now_ms();
2391	
2392	  if (contest_voice_music_active())
2393	    {
2394	      return;
2395	    }
2396	
2397	  pthread_mutex_lock(&g_monitor.lock);
2398	  if (g_voice_stop_requested || g_monitor.phase != RV_MON_LISTEN ||
2399	      g_monitor.wake_handoff_pending || g_monitor.muted || g_monitor.capture_active ||
2400	      now < g_monitor.last_voice_ms ||
2401	      now - g_monitor.last_voice_ms < ROBOT_VOICE_TURN_END_MS ||
2402	      g_monitor.consumed_final != g_monitor.submitted_final ||
2403	      (g_monitor.pending_text[0] == '\0' && !g_monitor.pending_failed))
2404	    {
2405	      pthread_mutex_unlock(&g_monitor.lock);
2406	      return;
2407	    }
2408	  failed = g_monitor.pending_failed;
2409	  error = g_monitor.pending_error;
2410	  run_id = g_monitor.run_id;
2411	  if (failed && error) {
2412	    notify = true;
2413	    g_monitor.error_notice_ms = now;
2414	    printf("[RV-RECOVER] turn_failed cause=asr-service rc=%d notify=%u\n", error, notify);
2415	  }
2416	  snprintf(routed, sizeof(routed), "%s", failed ?
2417	           (error ? ROBOT_PROMPT_NETWORK_ERROR : ROBOT_PROMPT_NOT_HEARD) :
2418	           g_monitor.pending_text);
2419	  g_monitor.pending_text[0] = '\0';
2420	  g_monitor.pending_failed = false;
2421	  g_monitor.pending_error = 0;
2422	  if (!failed && rv_end_chat(routed))
2423	    {
2424	      rv_return_to_wake_locked();
2425	      run_id = g_monitor.run_id;
2426	      pthread_mutex_unlock(&g_monitor.lock);
2427	      (void)robot_voice_tts_submit(ROBOT_PROMPT_CHAT_EXIT, false, run_id);
2428	      return;
2429	    }
2430	  g_monitor.phase = RV_MON_BUSY;
2431	  g_monitor.reply_locked = false;
2432	  g_monitor.listening_announced = false;
2433	  rv_run_token_advance_locked();
2434	  run_id = ++g_monitor.run_id;
2435	  g_monitor.reply_claimed = false;
2436	  g_monitor.reply_start_ms = now;
2437	  g_monitor.reply_user_end_ms = g_monitor.last_voice_ms;
2438	  RV_VERBOSE("[RV-TURN] commit mono_ms=%llu run=%lu end_to_commit_ms=%llu complete=%u text_bytes=%zu\n",
2439	         now, g_monitor.run_id, now - g_monitor.last_voice_ms, (unsigned int)!failed, strlen(routed));
2440	  RV_TEXT("[RV-TURN] text=%s\n", routed);
2441	  pthread_mutex_unlock(&g_monitor.lock);
2442	  if (failed)
2443	    {
2444	      pthread_mutex_lock(&g_monitor.lock);
2445	      g_monitor.reply_claimed = true;
2446	      g_monitor.agent_text[0] = 0;
2447	      pthread_mutex_unlock(&g_monitor.lock);
2448	      if (robot_voice_tts_submit(routed, true, run_id) < 0)
2449	        {
2450	          rv_reply_done(true);
2451	        }
2452	    }
2453	  else if (contest_voice_route_text(routed) < 0)
2454	    {
2455	      rv_reply_done(true);
2456	    }
2457	}
