    24	/*
    25	 * Keep the exact transaction shape that was stable in voice_echo:
    26	 *   - 1024 logical PCM bytes per RX APB
    27	 *   - two in-flight RX slots
    28	 *   - two warm-up chunks
    29	 *   - heap-owned callback context
    30	 *
    31	 * The important part is callback lifetime.  I2S completion is asynchronous,
    32	 * so a callback context must never live on the caller's stack.  When capture
    33	 * is stopped while an RX is in flight, the transfer is marked abandoned and
    34	 * the eventual callback releases the application APB reference and its own
    35	 * heap context.  This prevents late HPWORK callbacks from touching a returned
    36	 * stack frame or a destroyed semaphore/mutex.
    37	 */
    38	
    39	#define ROBOT_VOICE_RX_DMA_BYTES        1024
    40	#define ROBOT_VOICE_RX_SLOT_COUNT       2
    41	#define ROBOT_VOICE_RX_WARMUP_CHUNKS    2
    42	#define ROBOT_VOICE_RX_POLL_MS          50
    43	#define ROBOT_VOICE_RX_TIMEOUT_MS       1000
    44	#define ROBOT_VOICE_RECORD_GUARD_MS     2000
    45	
    46	/* The stream and diagnostic finite recordings share one physical RX port. */
    47	static pthread_mutex_t g_capture_lock = PTHREAD_MUTEX_INITIALIZER;
    48	
    49	struct robot_voice_transfer_s
    50	{
    51	  sem_t done;
    52	  mutex_t lock;
    53	  int result;
    54	  FAR struct ap_buffer_s *apb;
    55	  bool retain_apb;
    56	  bool callback_done;
    57	  bool abandoned;
    58	  unsigned int chunk;
    59	};
    60	
    61	struct robot_voice_rx_slot_s
    62	{
    63	  FAR struct ap_buffer_s *apb;
    64	  FAR struct robot_voice_transfer_s *transfer;
    65	  size_t request_bytes;
    66	  unsigned int chunk;
    67	  bool in_flight;
    68	};
