    76	static void robot_voice_transfer_init(
    77	  FAR struct robot_voice_transfer_s *transfer, bool retain_apb,
    78	  unsigned int chunk)
    79	{
    80	  nxsem_init(&transfer->done, 0, 0);
    81	  nxmutex_init(&transfer->lock);
    82	  transfer->result = -EINPROGRESS;
    83	  transfer->apb = NULL;
    84	  transfer->retain_apb = retain_apb;
    85	  transfer->callback_done = false;
    86	  transfer->abandoned = false;
    87	  transfer->chunk = chunk;
    88	}
