    90	static void robot_voice_transfer_destroy(
    91	  FAR struct robot_voice_transfer_s *transfer)
    92	{
    93	  nxmutex_lock(&transfer->lock);
    94	  nxmutex_unlock(&transfer->lock);
    95	  nxmutex_destroy(&transfer->lock);
    96	  nxsem_destroy(&transfer->done);
    97	}
