    99	static void robot_voice_rx_callback(FAR struct i2s_dev_s *dev,
   100	                                    FAR struct ap_buffer_s *apb,
   101	                                    FAR void *arg, int result)
   102	{
   103	  FAR struct robot_voice_transfer_s *transfer = arg;
   104	  size_t nbytes = apb == NULL ? 0 : apb->nbytes;
   105	  bool abandoned;
   106	
   107	  (void)dev;
   108	
   109	  if (transfer == NULL)
   110	    {
   111	      return;
   112	    }
   113	
   114	  if ((ROBOT_VOICE_LOG_VERBOSE && transfer->chunk < 2) || result < 0)
   115	    {
   116	      RV_VERBOSE("[RV-CAP] callback chunk=%u rc=%d bytes=%zu\n",
   117	             transfer->chunk, result, nbytes);
   118	    }
   119	
   120	  nxmutex_lock(&transfer->lock);
   121	  abandoned = transfer->abandoned;
   122	
   123	  if (abandoned)
   124	    {
   125	      /* The lower half still owns its own APB reference until this callback
   126	       * returns.  Release only the application's original reference here. */
   127	
   128	      nxmutex_unlock(&transfer->lock);
   129	      if (apb != NULL)
   130	        {
   131	          apb_free(apb);
   132	        }
   133	
   134	      nxmutex_destroy(&transfer->lock);
   135	      nxsem_destroy(&transfer->done);
   136	      free(transfer);
   137	      return;
   138	    }
   139	
   140	  if (transfer->retain_apb && apb != NULL && result >= 0)
   141	    {
   142	      /* Keep a callback-owned reference until the waiting thread has copied
   143	       * the completed PCM and releases the slot. */
   144	
   145	      apb_reference(apb);
   146	      transfer->apb = apb;
   147	    }
   148	
   149	  transfer->result = result;
   150	  transfer->callback_done = true;
   151	  nxsem_post(&transfer->done);
   152	  nxmutex_unlock(&transfer->lock);
   153	}
