   155	static bool robot_voice_abandon_transfer(
   156	  FAR struct robot_voice_transfer_s *transfer)
   157	{
   158	  bool abandoned = false;
   159	
   160	  if (transfer == NULL)
   161	    {
   162	      return false;
   163	    }
   164	
   165	  nxmutex_lock(&transfer->lock);
   166	  if (!transfer->callback_done)
   167	    {
   168	      transfer->abandoned = true;
   169	      abandoned = true;
   170	    }
   171	  nxmutex_unlock(&transfer->lock);
   172	  return abandoned;
   173	}
