   216	static int robot_voice_rx_slot_submit(FAR struct i2s_dev_s *mic,
   217	                                      FAR struct robot_voice_rx_slot_s *slot,
   218	                                      size_t request_bytes,
   219	                                      unsigned int chunk)
   220	{
   221	  int ret;
   222	
   223	  if (mic == NULL || slot == NULL || request_bytes == 0 ||
   224	      request_bytes > ROBOT_VOICE_RX_DMA_BYTES)
   225	    {
   226	      return -EINVAL;
   227	    }
   228	
   229	  ret = robot_voice_buffer_alloc(&slot->apb, request_bytes);
   230	  if (ret < 0)
   231	    {
   232	      return ret;
   233	    }
   234	
   235	  slot->transfer = calloc(1, sizeof(*slot->transfer));
   236	  if (slot->transfer == NULL)
   237	    {
   238	      apb_free(slot->apb);
   239	      slot->apb = NULL;
   240	      return -ENOMEM;
   240	      return -ENOMEM;
   241	    }
   242	
   243	  slot->request_bytes = request_bytes;
   244	  slot->chunk = chunk;
   245	  robot_voice_transfer_init(slot->transfer, true, chunk);
   246	
   247	  if (ROBOT_VOICE_LOG_VERBOSE && chunk < 2)
   248	    {
   249	      RV_VERBOSE("[RV-CAP] receive submit chunk=%u logical=%zu\n",
   250	             chunk, request_bytes);
   251	    }
   252	
   253	  ret = I2S_RECEIVE(mic, slot->apb, robot_voice_rx_callback,
   254	                    slot->transfer,
   255	                    MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS));
   256	  if ((ROBOT_VOICE_LOG_VERBOSE && chunk < 2) || ret < 0)
   257	    {
   258	      RV_VERBOSE("[RV-CAP] I2S_RECEIVE chunk=%u rc=%d\n", chunk, ret);
   259	    }
   260	
   261	  if (ret < 0)
   262	    {
   263	      robot_voice_rx_slot_release(slot);
   264	      return ret;
   265	    }
   266	
   267	  slot->in_flight = true;
   268	  return OK;
   269	}
