   271	static int robot_voice_rx_slot_wait_interruptible(
   272	  FAR struct robot_voice_rx_slot_s *slot, clock_t deadline,
   273	  FAR volatile bool *stop_requested)
   274	{
   275	  FAR struct robot_voice_transfer_s *transfer;
   276	  int ret;
   277	
   278	  if (slot == NULL || slot->transfer == NULL)
   279	    {
   280	      return -EINVAL;
   281	    }
   282	
   283	  transfer = slot->transfer;
   284	
   285	  for (;;)
   286	    {
   287	      ret = nxsem_tickwait(&transfer->done,
   288	                           MSEC2TICK(ROBOT_VOICE_RX_POLL_MS));
   289	      if (ret >= 0)
   290	        {
   291	          nxmutex_lock(&transfer->lock);
   292	          ret = transfer->result;
   293	          nxmutex_unlock(&transfer->lock);
   294	          return ret;
   295	        }
   296	
   297	      if (ret == -EINTR)
   298	        {
   299	          continue;
   300	        }
   301	
   302	      if (ret != -ETIMEDOUT)
   303	        {
   304	          return ret;
   305	        }
   306	
   307	      if (robot_voice_capture_stop_requested(stop_requested))
   308	        {
   309	          return -ECANCELED;
   310	        }
   311	
   312	      if ((int32_t)(deadline - clock_systime_ticks()) <= 0)
   313	        {
   314	          return -ETIMEDOUT;
   315	        }
   316	    }
   317	}
