   319	static int robot_voice_rx_abort(FAR struct i2s_dev_s *mic,
   320	                                FAR struct robot_voice_rx_slot_s *slots)
   321	{
   322	  unsigned int i;
   323	  int stop_ret;
   324	
   325	  /* Mark every live callback context abandoned BEFORE stopping hardware.
   326	   * AUDIOIOC_STOP can schedule completion immediately on HPWORK. */
   327	
   328	  for (i = 0; i < ROBOT_VOICE_RX_SLOT_COUNT; i++)
   329	    {
   330	      FAR struct robot_voice_rx_slot_s *slot = &slots[i];
   331	
   332	      if (!slot->in_flight)
   333	        {
   334	          robot_voice_rx_slot_release(slot);
   335	          continue;
   336	        }
   337	
   338	      if (robot_voice_abandon_transfer(slot->transfer))
   339	        {
   340	          /* Callback owns cleanup from this point.  Do not touch either
   341	           * pointer after AUDIOIOC_STOP. */
   342	
   343	          slot->transfer = NULL;
   344	          slot->apb = NULL;
   345	          slot->in_flight = false;
   346	        }
   347	      else
   348	        {
   349	          robot_voice_rx_slot_release(slot);
   350	        }
   351	    }
   352	
   353	  stop_ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
   354	  RV_VERBOSE("[RV-CAP] abort stop rc=%d\n", stop_ret);
   355	  return stop_ret;
   356	}
