   358	static int robot_voice_rx_copy(FAR const struct robot_voice_rx_slot_s *slot,
   359	                               uint8_t *dst, size_t cap, size_t *used)
   360	{
   361	  FAR const uint8_t *src_bytes;
   362	  size_t nbytes;
   363	  size_t samples;
   364	  size_t i;
   365	
   366	  if (slot == NULL || slot->apb == NULL || dst == NULL || used == NULL)
   367	    {
   368	      return -EINVAL;
   369	    }
   370	
   371	  nbytes = slot->apb->nbytes;
   372	  if (nbytes != slot->request_bytes || nbytes > cap - *used ||
   373	      (nbytes % sizeof(int16_t)) != 0)
   374	    {
   375	      return -EIO;
   376	    }
   377	
   378	  src_bytes = slot->apb->samp;
   379	  memcpy(dst + *used, src_bytes, nbytes);
   380	
   381	  /* Apply the same 2x capture gain that produced the known-good ASR input,
   382	   * but use memcpy per sample so alignment of the destination never matters. */
   383	
   384	  samples = nbytes / sizeof(int16_t);
   385	  for (i = 0; i < samples; i++)
   386	    {
   387	      int16_t sample;
   388	      int32_t gained;
   389	
   390	      memcpy(&sample, dst + *used + i * sizeof(int16_t), sizeof(sample));
   391	      gained = (int32_t)sample * 2;
   392	      if (gained > INT16_MAX)
   393	        {
   394	          gained = INT16_MAX;
   395	        }
   396	      else if (gained < INT16_MIN)
   397	        {
   398	          gained = INT16_MIN;
   399	        }
   400	
   401	      sample = (int16_t)gained;
   402	      memcpy(dst + *used + i * sizeof(int16_t), &sample, sizeof(sample));
   403	    }
   404	
   405	  *used += nbytes;
   406	  return OK;
   407	}
