   409	static int robot_voice_capture_record_internal(
   410	  uint8_t *buf, size_t cap, size_t *out_len, unsigned int duration_ms,
   411	  FAR volatile bool *stop_requested)
   412	{
   413	  FAR struct i2s_dev_s *mic;
   414	  struct robot_voice_rx_slot_s slots[ROBOT_VOICE_RX_SLOT_COUNT];
   415	  size_t target;
   416	  size_t capture_target;
   417	  size_t submitted_bytes = 0;
   418	  size_t used = 0;
   419	  unsigned int submit_chunk = 0;
   420	  unsigned int wait_slot = 0;
   421	  unsigned int submitted = 0;
   422	  unsigned int completed = 0;
   423	  unsigned int in_flight = 0;
   424	  unsigned int warmup_chunks = 0;
   425	  clock_t deadline;
   426	  int ret;
   427	
   428	  if (buf == NULL || out_len == NULL || cap < sizeof(int16_t) ||
   429	      duration_ms == 0)
   430	    {
   431	      return -EINVAL;
   432	    }
   433	
   434	  memset(slots, 0, sizeof(slots));
   435	  *out_len = 0;
   436	
   437	  target = ((size_t)ROBOT_VOICE_CAPTURE_RATE * sizeof(int16_t) *
   438	            duration_ms) / 1000;
   439	  target = target > cap ? cap : target;
   440	  target -= target % sizeof(int16_t);
   441	  if (target == 0)
   442	    {
   443	      return -EINVAL;
   444	    }
   445	
   446	  mic = board_voice_mic_i2s();
   447	  if (mic == NULL)
   448	    {
   449	      return -ENODEV;
   450	    }
   451	
   452	  ret = I2S_RXCHANNELS(mic, ROBOT_VOICE_CHANNELS);
   453	  RV_VERBOSE("[RV-CAP] set channels %d rc=%d\n", ROBOT_VOICE_CHANNELS, ret);
   454	  if (ret < 0)
   455	    {
   456	      return ret;
   457	    }
   458	
   459	  ret = (int)I2S_RXSAMPLERATE(mic, ROBOT_VOICE_CAPTURE_RATE);
   460	  RV_VERBOSE("[RV-CAP] set rate %d rc=%d\n", ROBOT_VOICE_CAPTURE_RATE, ret);
   461	  if (ret != ROBOT_VOICE_CAPTURE_RATE)
   462	    {
   463	      return ret < 0 ? ret : -ENOTSUP;
   464	    }
   465	
   466	  ret = (int)I2S_RXDATAWIDTH(mic, ROBOT_VOICE_BITS);
   467	  RV_VERBOSE("[RV-CAP] set width %d rc=%d\n", ROBOT_VOICE_BITS, ret);
   468	  if (ret != ROBOT_VOICE_BITS)
   469	    {
   470	      return ret < 0 ? ret : -ENOTSUP;
   471	    }
   472	
   473	  board_voice_mic_set_diagnostics(false);
   474	  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
   475	  RV_VERBOSE("[RV-CAP] start rc=%d\n", ret);
   476	  if (ret < 0)
   477	    {
   478	      return ret;
   479	    }
   480	
   481	  capture_target = target + ROBOT_VOICE_RX_WARMUP_CHUNKS *
   482	                             ROBOT_VOICE_RX_DMA_BYTES;
   483	  /* Allow the requested capture window to grow without being cut off by a
   484	   * stale fixed seven-second deadline.  The guard covers the RX queue,
   485	   * callback and final APB completion overhead. */
   486	  deadline = clock_systime_ticks() +
   487	             MSEC2TICK(duration_ms + ROBOT_VOICE_RECORD_GUARD_MS);
   488	
   489	  RV_VERBOSE("[RV-CAP] recording %u ms target=%zu chunk=%d slots=%d warmup=%d\n",
   490	         duration_ms, target, ROBOT_VOICE_RX_DMA_BYTES,
   491	         ROBOT_VOICE_RX_SLOT_COUNT, ROBOT_VOICE_RX_WARMUP_CHUNKS);
   492	
   493	  while (submitted_bytes < capture_target &&
   494	         in_flight < ROBOT_VOICE_RX_SLOT_COUNT)
   495	    {
