1642	static void rv_wake_buffer_push_locked(struct rv_segmenter_s *seg,
1643	                                       const uint8_t *pcm, bool voiced)
1644	{
1645	  const size_t cap = RV_MS_BYTES(ROBOT_VOICE_WAKE_CONTEXT_MS);
1646	  uint8_t *ring = seg->speech + RV_MS_BYTES(ROBOT_VOICE_SEGMENT_MAX_MS) - cap;
1647	  size_t slot = seg->wake_head / ROBOT_AFE_BYTES;
1648	  if (seg->wake_used == cap && seg->wake_votes[slot])
1649	    seg->wake_voiced -= ROBOT_AFE_BYTES;
1650	  seg->wake_votes[slot] = voiced;
1651	  if (voiced) seg->wake_voiced += ROBOT_AFE_BYTES;
1652	  memcpy(ring + seg->wake_head, pcm, ROBOT_AFE_BYTES);
1653	  seg->wake_head = (seg->wake_head + ROBOT_AFE_BYTES) % cap;
1654	  if (seg->wake_used < cap) seg->wake_used += ROBOT_AFE_BYTES;
1655	  seg->wake_total += ROBOT_AFE_BYTES;
1656	  g_monitor.wake_total_samples = seg->wake_total / 2;
1657	  g_monitor.wake_buffered_samples = seg->wake_used / 2;
1658	}
