1660	static void rv_wake_handoff_locked(struct rv_segmenter_s *seg)
1661	{
1662	  const size_t cap = RV_MS_BYTES(ROBOT_VOICE_WAKE_CONTEXT_MS);
1663	  size_t oldest = (seg->wake_head + cap - seg->wake_used) % cap;
1664	  size_t first = cap - oldest;
1665	  if (first > seg->wake_used) first = seg->wake_used;
1666	  const uint8_t *ring = seg->speech + RV_MS_BYTES(ROBOT_VOICE_SEGMENT_MAX_MS) - cap;
1667	  /* Standby uses the allocation's tail. The head is a disjoint destination,
1668	   * so linearization copies each retained byte once, with no new allocation.
1669	   * Never trim samples using the classifier or the model window endpoint. */
1670	  memcpy(seg->speech, ring + oldest, first);
1671	  memcpy(seg->speech + first, ring, seg->wake_used - first);
1672	  seg->used = seg->wake_used;
1673	  seg->voiced = seg->wake_voiced;
1674	  if (seg->voiced < RV_MS_BYTES(ROBOT_VOICE_VAD_MIN_MS))
1675	    seg->voiced = RV_MS_BYTES(ROBOT_VOICE_VAD_MIN_MS);
1676	  seg->active = true;
1677	  seg->wake_context = true;
1678	  seg->speech_id = ++g_monitor.speech_id;
1679	  seg->last_voice_end = seg->used;
1680	  seg->early_voice_end = 0;
1681	  seg->silence = seg->stored_silence = seg->onset = 0;
1682	  g_monitor.capture_active = true;
1683	  g_monitor.wake_handoff_pending = false;
1684	  g_monitor.wake_total_samples = g_monitor.wake_buffered_samples = 0;
1685	  RV_EVENT("[RV-WAKE-HANDOFF] segment=%lu retained=%zu bytes; full wake+command PCM\n",
1686	           seg->speech_id, seg->used);
1687	}
