1902	/* This is the sole activation entry point. It accepts only a fresh acoustic
1903	 * score from the current capture epoch, outside TTS/echo guards. */
1904	static bool rv_accept_acoustic_wake(const struct robot_wakeword_result_s *result)
1905	{
1906	  bool accepted = false;
1907	  pthread_mutex_lock(&g_monitor.lock);
1908	  if (result->triggered && g_monitor.enabled && !g_monitor.stop &&
1909	      !g_voice_stop_requested && !g_monitor.muted &&
1910	      robot_voice_now_ms() >= g_monitor.echo_until_ms &&
1911	      result->epoch == g_monitor.epoch && g_monitor.phase == RV_MON_WAKE)
1912	    {
1913	      size_t window = robot_wakeword_window_samples();
1914	      uint64_t oldest = g_monitor.wake_total_samples - g_monitor.wake_buffered_samples;
1915	      uint64_t start = result->end_sample > window ? result->end_sample - window : 0;
1916	      if (result->end_sample &&
1917	          (result->end_sample > g_monitor.wake_total_samples || start < oldest))
1918	        {
1919	          RV_EVENT("[RV-WAKE-HANDOFF] stale/overrun wake context; repeat complete command\n");
1920	          pthread_mutex_unlock(&g_monitor.lock);
1921	          return false;
1922	        }
1923	      g_monitor.phase = RV_MON_LISTEN;
1924	      g_monitor.wake_handoff_pending = g_monitor.wake_buffered_samples != 0;
1925	      g_monitor.chat_activity_ms = robot_voice_now_ms();
1926	      rv_listening_expression_locked();
1927	      robot_world_state_note_user_activity();
1928	      RV_EVENT("[唤醒][TFLite] score=%.6f threshold=%.6f\n",
1929	               (double)result->score, (double)result->threshold);
1930	      pthread_cond_broadcast(&g_monitor.changed);
1931	      accepted = true;
1932	    }
1933	  pthread_mutex_unlock(&g_monitor.lock);
1934	  return accepted;
1935	}
