1937	static void *rv_acoustic_worker(void *arg)
1938	{
1939	  (void)arg;
1940	  while (!g_voice_stop_requested)
1941	    {
1942	      struct robot_wakeword_result_s result;
1943	      int ret = robot_wakeword_poll(&result);
1944	      if (ret < 0)
1945	        {
1946	          RV_EVENT("[语音错误] TFLite 唤醒推理失败 rc=%d，停止监听\n", ret);
1947	          g_voice_stop_requested = true;
1948	          pthread_mutex_lock(&g_monitor.lock);
1949	          g_monitor.acoustic_error = ret;
1950	          g_monitor.stop = true;
1951	          pthread_cond_broadcast(&g_monitor.changed);
1952	          pthread_mutex_unlock(&g_monitor.lock);
1953	          break;
1954	        }
1955	      if (ret > 0)
1956	        {
1957	          (void)rv_accept_acoustic_wake(&result);
1958	        }
1959	      usleep(ROBOT_WAKEWORD_POLL_MS * 1000);
1960	    }
1961	  return NULL;
