1964	static void *rv_capture_worker(void *arg)
1965	{
1966	  struct rv_segmenter_s seg;
1967	  int ret = -ENOMEM;
1968	
1969	  (void)arg;
1970	  memset(&seg, 0, sizeof(seg));
1971	  seg.pre = malloc(RV_MS_BYTES(ROBOT_VOICE_PRE_ROLL_MS));
1972	  seg.speech = malloc(RV_MS_BYTES(ROBOT_VOICE_SEGMENT_MAX_MS));
1973	  if (seg.pre != NULL && seg.speech != NULL)
1974	    {
1975	      unsigned int restarts = 0;
1976	      do {
1977	        unsigned long before;
1978	        pthread_mutex_lock(&g_monitor.lock);
1979	        before = g_monitor.frames;
1980	        pthread_mutex_unlock(&g_monitor.lock);
1981	        seg.afe = robot_voice_afe_create(g_monitor.afe_mode);
1982	        if (!seg.afe) { ret = -ENOMEM; break; }
1983	        memset(&seg.afe_previous, 0, sizeof(seg.afe_previous));
1984	        ret = robot_voice_capture_stream(rv_monitor_frame, &seg,
1985	                                          &g_voice_stop_requested);
1986	        pthread_mutex_lock(&g_monitor.lock);
1987	        g_monitor.afe_stats.discarded_samples += seg.afe_previous.partial_samples;
1988	        g_monitor.afe_stats.partial_samples = 0;
1989	        pthread_mutex_unlock(&g_monitor.lock);
1990	        robot_voice_afe_destroy(seg.afe);
1991	        seg.afe = NULL;
1992	        if (g_voice_stop_requested ||
1993	            (ret != -EIO && ret != -ETIMEDOUT && ret != -EPIPE)) break;
1994	        pthread_mutex_lock(&g_monitor.lock);
1995	        /* A recovered RX stream starts a fresh segment; an interrupted user
1996	         * turn must never be executed from its surviving half. */
1997	        if (seg.active || g_monitor.wake_handoff_pending)
1998	          g_monitor.pending_failed = true;
1999	        g_monitor.afe_restarts++;
2000	        (void)robot_wakeword_feed(NULL, 0, g_monitor.epoch, false);
2001	        g_monitor.capture_active = false;
2002	        if (g_monitor.frames - before >= 32) restarts = 0;
2003	        pthread_mutex_unlock(&g_monitor.lock);
2004	        if (restarts++ >= 2) break;
2005	        pthread_mutex_lock(&g_monitor.lock);
2006	        rv_segment_reset(&seg); seg.pre_used = 0;
2007	        rv_wake_buffer_reset_locked(&seg);
2008	        pthread_mutex_unlock(&g_monitor.lock);
2009	        RV_VERBOSE("[RV-RECOVER] RX restart=%u rc=%d; queued human audio retained\n",
2010	               restarts, ret);
2011	        usleep(200000);
2012	      } while (!g_voice_stop_requested);
2013	    }
2014	  free(seg.pre);
2015	  free(seg.speech);
2016	  pthread_mutex_lock(&g_monitor.lock);
2017	  g_monitor.capture_result = ret;
2018	  g_monitor.capture_exited = true;
2019	  pthread_cond_broadcast(&g_monitor.changed);
2020	  pthread_mutex_unlock(&g_monitor.lock);
2021	  RV_VERBOSE("[RV-MON] capture exit rc=%d\n", ret);
2022	  return NULL;
2023	}
