1310	/* A Flash reply locks recognition before TTS synthesis. Unscoped CLI
1311	 * playback still waits for an active user utterance before muting capture. */
1312	static bool rv_playback_begin_checked(bool (*cancelled)(void *), void *arg)
1313	{
1314	  bool allowed;
1315	  pthread_mutex_lock(&g_monitor.lock);
1316	  while (g_monitor.enabled && !g_monitor.stop &&
1317	         !g_voice_stop_requested && !(cancelled && cancelled(arg)) &&
1318	         !g_monitor.reply_locked &&
1319	         (g_monitor.capture_active || g_monitor.wake_handoff_pending ||
1320	          (robot_voice_now_ms() >= g_monitor.last_voice_ms &&
1321	           robot_voice_now_ms() - g_monitor.last_voice_ms <
1322	             ROBOT_VOICE_TURN_END_MS)))
1323	    {
1324	      rv_wait_locked(50);
1325	    }
1326	  allowed = (!g_monitor.enabled ||
1327	            (!g_monitor.stop && !g_voice_stop_requested)) &&
1328	            !(cancelled && cancelled(arg));
1329	  if (allowed && g_monitor.enabled)
1330	    {
1331	      g_monitor.muted = true;
1332	      g_monitor.playback_token = rv_run_token_load();
1333	      (void)robot_wakeword_feed(NULL, 0, g_monitor.epoch, false);
1334	      g_monitor.listening_announced = false;
1335	    }
1336	  pthread_mutex_unlock(&g_monitor.lock);
1337	  return allowed;
1338	}
