1367	static void rv_reply_done_for_run(bool agent_reply, unsigned long run_id)
1368	{
1369	  pthread_mutex_lock(&g_monitor.lock);
1370	  if (run_id && run_id != g_monitor.run_id)
1371	    { pthread_mutex_unlock(&g_monitor.lock); return; }
1372	  if (g_monitor.reply_locked && !agent_reply)
1373	    { pthread_mutex_unlock(&g_monitor.lock); return; }
1374	  if (agent_reply) {
1375	    g_voice_reply_pending = false;
1376	    g_monitor.reply_locked = false;
1377	  }
1378	  if (g_monitor.enabled && !g_voice_stop_requested)
1379	    {
1380	      /* No speaker mute means capture may already contain a new onset.
1381	       * A download/empty reply finishing must not invent an echo interval. */
1382	      if (g_monitor.muted)
1383	        g_monitor.echo_until_ms = ROBOT_VOICE_ECHO_GUARD_MS ?
1384	      robot_voice_now_ms() + ROBOT_VOICE_ECHO_GUARD_MS : 0;
1385	      g_monitor.muted = false;
1386	      g_monitor.chat_activity_ms = robot_voice_now_ms();
1387	      if (agent_reply && g_monitor.phase == RV_MON_GREETING)
1388	        {
1389	          g_monitor.phase = RV_MON_WAKE;
1390	          RV_VERBOSE("[RV-WAKE] ready: say 你好，OpenVela\n");
1391	        }
1392	      else if (agent_reply && g_monitor.phase == RV_MON_BUSY)
1393	        {
1394	          g_monitor.phase = RV_MON_LISTEN;
1395	        }
1396	      rv_listening_expression_locked();
1397	      pthread_cond_broadcast(&g_monitor.changed);
1398	    }
1399	  pthread_mutex_unlock(&g_monitor.lock);
1400	}
