 69	static int parse_endpoint(const char *endpoint, char *host, size_t host_cap,
 70	    char *path, size_t path_cap)
 71	{
 72	    const char *begin;
 73	    const char *slash;
 74	    size_t host_len;
 75	
 76	    if (!endpoint || !host || host_cap == 0 || !path || path_cap == 0) {
 77	        return -EINVAL;
 78	    }
 79	
 80	    if (strncmp(endpoint, "https://", 8) == 0) {
 81	        begin = endpoint + 8;
 82	    } else if (strncmp(endpoint, "http://", 7) == 0) {
 83	        begin = endpoint + 7;
 84	    } else {
 85	        return -EINVAL;
 86	    }
 87	
 88	    slash = strchr(begin, '/');
 89	    host_len = slash ? (size_t)(slash - begin) : strlen(begin);
 90	    if (host_len == 0 || host_len >= host_cap) {
 91	        return -EINVAL;
 92	    }
 93	
 94	    memcpy(host, begin, host_len);
 95	    host[host_len] = '\0';
 96	
 97	    if (!slash || slash[1] == '\0' || strcmp(slash, "/v1") == 0 ||
 98	        strcmp(slash, "/v1/") == 0) {
 99	        snprintf(path, path_cap, "/v1/chat/completions");
100	    } else {
101	        if (strlen(slash) >= path_cap) {
102	            return -EINVAL;
103	        }
104	        snprintf(path, path_cap, "%s", slash);
105	    }
106	
107	    return OK;
108	}
