142	        strcmp(applied.model, backend.model) != 0 ||
143	        strcmp(applied.path, backend.path) != 0 ||
144	        strcmp(applied.api_key, backend.api_key) != 0) {
145	        return ret == OK ? -EIO : ret;
146	    }
147	
148	    return OK;
149	}
