 28	static uint64_t rv_afe_us(void)
 29	{
 30	  struct timespec t;
 31	  if (clock_gettime(CLOCK_MONOTONIC, &t) != 0) return 0;
 32	  return (uint64_t)t.tv_sec * 1000000u + (uint64_t)t.tv_nsec / 1000u;
 33	}
