 35	static unsigned int rv_afe_level(const int16_t *pcm)
 36	{
 37	  int32_t mean = 0;
 38	  uint32_t sum = 0;
 39	  size_t i;
 40	  for (i = 0; i < ROBOT_AFE_SAMPLES; i++) mean += pcm[i];
 41	  mean /= ROBOT_AFE_SAMPLES;
 42	  for (i = 0; i < ROBOT_AFE_SAMPLES; i++)
 43	    {
 44	      int32_t delta = (int32_t)pcm[i] - mean;
 45	      sum += delta < 0 ? -delta : delta;
 46	    }
 47	  return sum / ROBOT_AFE_SAMPLES;
 48	}
