 50	struct robot_voice_afe_s *robot_voice_afe_create(enum robot_voice_afe_mode_e mode)
 51	{
 52	  struct robot_voice_afe_s *a;
 53	  if (mode < ROBOT_AFE_CLEAN || mode > ROBOT_AFE_KWS_RAW) return NULL;
 54	  a = calloc(1, sizeof(*a));
 55	  if (!a) return NULL;
 56	  a->mode = mode;
 57	  a->noise_q8 = 32u * 256u;
 58	  a->vad = fvad_new();
 59	  if (!a->vad) goto failed;
 60	  if (fvad_set_sample_rate(a->vad, ROBOT_VOICE_CAPTURE_RATE) < 0 ||
 61	      fvad_set_mode(a->vad, ROBOT_VOICE_VAD_MODE) < 0)
 62	    goto failed;
 63	  return a;
 64	failed:
 65	  robot_voice_afe_destroy(a);
 66	  return NULL;
 67	}
