3724	static int rv_sentence_pcm_sink(const uint8_t *pcm, size_t len, void *arg)
3725	{
3726	  struct rv_sentence_job_s *job = arg;
3727	  size_t required;
3728	  size_t capacity;
3729	  uint8_t *next;
3730	
3731	  if (job == NULL || (pcm == NULL && len != 0) || (len & 1u) != 0)
3732	    {
3733	      return -EINVAL;
3734	    }
3735	
3736	  if (rv_sentence_retry_expired(job)) return -ETIMEDOUT;
3737	
3738	  if ((job->cancel_on_stop && g_voice_stop_requested) ||
3739	      rv_pipeline_cancelled(job->pipeline))
3740	    {
3741	      return -ECANCELED;
3742	    }
3743	
3744	  if (len == 0)
3745	    {
3746	      return 0;
3747	    }
3748	  if (!job->first_pcm_ms) {
3749	    job->first_pcm_ms = robot_voice_now_ms();
3750	    if (!ROBOT_VOICE_TTS_LIVE)
3751	      RV_EVENT("[耗时][TTS首包] run=%lu seq=%u 请求到首PCM=%lldms\n",
3752	        job->run_id, job->sequence, rv_elapsed_ms(job->tts_start_ms, job->first_pcm_ms));
3753	  }
3754	  if (ROBOT_VOICE_TTS_LIVE && job->pipeline)
3755	    return rv_live_sentence_sink(pcm, len, job);
3756	
3757	  if (len > RV_SENTENCE_PCM_LIMIT - job->pcm_bytes)
3758	    {
3759	      return -EOVERFLOW;
3760	    }
3761	
3762	  required = job->pcm_bytes + len;
3763	  if (required > job->pcm_capacity)
3764	    {
3765	      capacity = job->pcm_capacity == 0 ? 16 * 1024 : job->pcm_capacity;
3766	      while (capacity < required)
3767	        {
3768	          if (capacity > RV_SENTENCE_PCM_LIMIT / 2)
3769	            {
3770	              capacity = RV_SENTENCE_PCM_LIMIT;
3771	              break;
3772	            }
3773	          capacity *= 2;
3774	        }
3775	
3776	      int reserve_ret = rv_pipeline_reserve(job, capacity - job->pcm_capacity);
3777	      if (reserve_ret < 0) return reserve_ret;
3778	      next = realloc(job->pcm, capacity);
3779	      if (next == NULL)
3780	        {
3781	          if (job->pipeline) rv_pipeline_release(job->pipeline, capacity - job->pcm_capacity);
3782	          return -ENOMEM;
3783	        }
3784	      job->pcm = next;
3785	      job->pcm_capacity = capacity;
3786	    }
3787	
3788	  memcpy(job->pcm + job->pcm_bytes, pcm, len);
3789	  job->pcm_bytes = required;
3790	  return 0;
3791	}
