  (void)arg;

  if (pcm == NULL)
    {
      printf("[contest_voice] worker cleanup: pcm allocation failed\n");
      goto cleanup;
    }

    printf("[ROBOT-PROACTIVE] runtime unavailable; music playback remains available\n");
