  free(job);
  pthread_mutex_lock(&g_voice_lock);
  g_tts_jobs--;
  pthread_cond_broadcast(&g_tts_jobs_changed);
  pthread_mutex_unlock(&g_voice_lock);
  return NULL;
}

static int robot_voice_tts_submit(const char *text, bool agent_reply,
