2535	/* Controller waits for a real RX frame, rather than assuming pthread_create
2536	 * means the microphone is ready. No Flash request is needed for this greeting. */
2537	static int rv_startup_announce(void)
2538	{
2539	  unsigned long run_id;
2540	  unsigned long long start = robot_voice_now_ms();
2541	  int ret = 0;
2542	  pthread_mutex_lock(&g_monitor.lock);
2543	  while (!g_monitor.capture_ready && !g_monitor.capture_exited &&
2544	         !g_monitor.stop && !g_voice_stop_requested &&
2545	         robot_voice_now_ms() - start < ROBOT_VOICE_READY_TIMEOUT_MS)
2546	    rv_wait_locked(50);
2547	  if (g_voice_stop_requested || g_monitor.stop) ret = -ECANCELED;
2548	  else if (g_monitor.capture_exited)
2549	    ret = g_monitor.capture_result < 0 ? g_monitor.capture_result : -EIO;
2550	  else if (!g_monitor.capture_ready) ret = -ETIMEDOUT;
2551	  run_id = g_monitor.run_id;
2552	  g_monitor.reply_start_ms = robot_voice_now_ms();
2553	  pthread_mutex_unlock(&g_monitor.lock);
2554	  if (ret < 0) return ret;
2555	  RV_EVENT("[语音] 系统准备就绪，开始问好\n");
2556	  ret = robot_voice_tts_submit(ROBOT_PROMPT_STARTUP, true, run_id);
2557	  if (ret < 0) {
2558	    printf("[语音错误] 启动问好提交失败 rc=%d\n", ret);
2559	    rv_reply_done(true); /* keep wake listening available after TTS failure */
2560	  }
2561	  return 0;
2562	}
