   706	         ROBOT_VOICE_RX_DMA_BYTES, ROBOT_VOICE_RX_SLOT_COUNT);
   707	  while (!robot_voice_capture_stop_requested(stop_requested))
   708	    {
   709	      FAR struct robot_voice_rx_slot_s *slot = &slots[index];
   710	      clock_t deadline = clock_systime_ticks() +
   711	        MSEC2TICK(ROBOT_VOICE_RX_TIMEOUT_MS + ROBOT_VOICE_RECORD_GUARD_MS);
   712	      size_t used = 0;
   713	
   714	      ret = robot_voice_rx_slot_wait_interruptible(slot, deadline,
   715	                                                   stop_requested);
   716	      if (ret < 0)
   717	        {
   718	          goto out;
   719	        }
   720	
   721	      if (warmup < ROBOT_VOICE_RX_WARMUP_CHUNKS)
   722	        {
   723	          warmup++;
   724	        }
   725	      else
   726	        {
   727	          ret = robot_voice_rx_copy(slot, frame, sizeof(frame), &used);
   728	          if (ret < 0)
   729	            {
   730	              goto out;
   731	            }
   732	        }
   733	
   734	      robot_voice_rx_slot_release(slot);
   735	      /* Requeue RX before running the application sink, so DMA stays ahead. */
   736	      ret = robot_voice_rx_slot_submit(mic, slot, ROBOT_VOICE_RX_DMA_BYTES,
   737	                                       chunk++);
   738	      if (ret < 0)
   739	        {
   740	          goto out;
   741	        }
   742	
   743	      index = (index + 1) % ROBOT_VOICE_RX_SLOT_COUNT;
   744	      if (used != 0)
   745	        {
   746	          ret = sink(frame, used, arg);
   747	          if (ret < 0)
   748	            {
   749	              goto out;
   750	            }
   751	        }
   752	    }
   753	
   754	  ret = 0;
   755	out:
   756	  if (started)
   757	    {
   758	      /* Preserve heap-owned abandoned callback cleanup on every exit. */
   759	      (void)robot_voice_rx_abort(mic, slots);
   760	    }
   761	
   762	  if (ret == -ECANCELED && robot_voice_capture_stop_requested(stop_requested))
   763	    {
   764	      ret = 0;
   765	    }
   766	
   767	  RV_VERBOSE("[RV-CAP] continuous RX stopped rc=%d chunks=%u\n", ret, chunk);
   768	  pthread_mutex_unlock(&g_capture_lock);
   769	  return ret;
   770	}

