     2	 * board/contest_board/src/board_voice_audio.c
     3	 *
     4	 * SPDX-License-Identifier: Apache-2.0
     5	 *
     6	 * F7P Media PCM bridge with exact terminal short-tail playback:
     7	 *
     8	 *   FFmpeg/Media decoded PCM16LE 24 kHz mono
     9	 *       -> /dev/audio/pcm0p
    10	 *       -> robot_audio_playback_write()
    11	 *       -> proven contest I2S1 / MAX98357 playback path
    12	 *
    13	 * The NuttX Audio device in this file intentionally does NOT use audio_i2s
    14	 * or pcm_decode.  Media owns decoding; robot_audio_playback owns the single
    15	 * verified hardware playback path.
    16	 *
    17	 * F7H additionally preserves NuttX Audio timing semantics: an APB is returned
    18	 * to FFmpeg only after its PCM duration has elapsed, instead of immediately
    19	 * after copying it into robot_audio_playback's private ring.
    20	 ****************************************************************************/
    21	
    22	/****************************************************************************
    23	 * Included Files
    24	 ****************************************************************************/
    25	
    26	#include <nuttx/config.h>
    27	
    28	#include <errno.h>
