    45	 ****************************************************************************/
    46	
    47	#define CONTEST_MEDIA_RATE          24000
    48	#define CONTEST_MEDIA_CHANNELS      1
    49	#define CONTEST_MEDIA_BITS          16
    50	#define CONTEST_MEDIA_NBUFFERS      6
    51	#define CONTEST_MEDIA_BUFFER_BYTES  4096
    52	
    53	/* F7H: pace AUDIO_CALLBACK_DEQUEUE at the real PCM consumption rate.
    54	 *
    55	 * The proven robot_audio_playback backend copies PCM into a 512 KiB ring.
    56	 * Returning an APB immediately after that copy makes FFmpeg believe the
    57	 * hardware consumed all periods instantly, which triggers its
    58	 * "playback underflow! pause" path.  Keep the APB owned by this lower-half
    59	 * until its PCM duration has elapsed.
    60	 */
    61	#define CONTEST_MEDIA_BYTES_PER_SEC \
    62	  (CONTEST_MEDIA_RATE * CONTEST_MEDIA_CHANNELS * (CONTEST_MEDIA_BITS / 8))
    63	#define CONTEST_MEDIA_PACE_QUEUE      16
    64	#define CONTEST_MEDIA_PACE_STACK      8192
    65	#define CONTEST_MEDIA_PACE_SLICE_US   5000
    66	
    67	/* Music volume is scaled only in the Media PCM bridge.  TTS uses the
    68	 * application playback path directly and is intentionally unaffected. */
    69	#define CONTEST_MEDIA_MUSIC_GAIN_NUM  1
    70	#define CONTEST_MEDIA_MUSIC_GAIN_DEN  2
    71	#define CONTEST_MEDIA_GAIN_CHUNK      512
