1971	static void *rv_capture_worker(void *arg)
1972	{
1973	  struct rv_segmenter_s seg;
1974	  int ret = -ENOMEM;
1975	
1976	  (void)arg;
1977	  memset(&seg, 0, sizeof(seg));
1978	  seg.pre = malloc(RV_MS_BYTES(ROBOT_VOICE_PRE_ROLL_MS));
1979	  seg.speech = malloc(RV_MS_BYTES(ROBOT_VOICE_SEGMENT_MAX_MS));
1980	  if (seg.pre != NULL && seg.speech != NULL)
1981	    {
1982	      unsigned int restarts = 0;
1983	      do {
1984	        unsigned long before;
1985	        pthread_mutex_lock(&g_monitor.lock);
1986	        before = g_monitor.frames;
1987	        pthread_mutex_unlock(&g_monitor.lock);
1988	        seg.afe = robot_voice_afe_create(g_monitor.afe_mode);
1989	        if (!seg.afe) { ret = -ENOMEM; break; }
1990	        memset(&seg.afe_previous, 0, sizeof(seg.afe_previous));
1991	        ret = robot_voice_capture_stream(rv_monitor_frame, &seg,
1992	                                          &g_voice_stop_requested);
1993	        pthread_mutex_lock(&g_monitor.lock);
1994	        g_monitor.afe_stats.discarded_samples += seg.afe_previous.partial_samples;
1995	        g_monitor.afe_stats.partial_samples = 0;
1996	        pthread_mutex_unlock(&g_monitor.lock);
1997	        robot_voice_afe_destroy(seg.afe);
1998	        seg.afe = NULL;
1999	        if (g_voice_stop_requested ||
2000	            (ret != -EIO && ret != -ETIMEDOUT && ret != -EPIPE)) break;
2001	        pthread_mutex_lock(&g_monitor.lock);
2002	        /* A recovered RX stream starts a fresh segment; an interrupted user
2003	         * turn must never be executed from its surviving half. */
2004	        if (seg.active || g_monitor.wake_handoff_pending)
2005	          g_monitor.pending_failed = true;
2006	        g_monitor.afe_restarts++;
2007	        (void)robot_wakeword_feed(NULL, 0, g_monitor.epoch, false);
2008	        g_monitor.capture_active = false;
2009	        if (g_monitor.frames - before >= 32) restarts = 0;
2010	        pthread_mutex_unlock(&g_monitor.lock);
2011	        if (restarts++ >= CONTEST_VOICE_CAPTURE_RESTART_LIMIT) break;
2012	        pthread_mutex_lock(&g_monitor.lock);
2013	        rv_segment_reset(&seg); seg.pre_used = 0;
2014	        rv_wake_buffer_reset_locked(&seg);
2015	        pthread_mutex_unlock(&g_monitor.lock);
2016	        RV_VERBOSE("[RV-RECOVER] RX restart=%u rc=%d; queued human audio retained\n",
2017	               restarts, ret);
2018	        usleep(200000);
2019	      } while (!g_voice_stop_requested);
2020	    }
2021	  free(seg.pre);
2022	  free(seg.speech);
2023	  pthread_mutex_lock(&g_monitor.lock);
2024	  g_monitor.capture_result = ret;
2025	  g_monitor.capture_exited = true;
2026	  pthread_cond_broadcast(&g_monitor.changed);
2027	  pthread_mutex_unlock(&g_monitor.lock);
2028	  RV_VERBOSE("[RV-MON] capture exit rc=%d\n", ret);
2029	  return NULL;
2030	}
