718	/* The generic ESP32-S3 helper splits a 4096-byte RX request into 4095+1.
719	 * With the I2S RX EOF unit used by this board, that layout can terminate
720	 * after the first short descriptor.  Keep RX descriptors 4-byte aligned and
721	 * use two equal buffers for the normal 4096-byte transaction.
722	 */
723	
724	static uint32_t contest_i2s_dma_setup_rx(
725	  FAR struct esp32s3_dmadesc_s *desc, uint32_t count,
726	  FAR uint8_t *buffer, uint32_t bytes)
727	{
728	  uint32_t offset = 0;
729	  uint32_t i;
730	
731	  memset(desc, 0, count * sizeof(*desc));
732	
733	  for (i = 0; i < count && offset < bytes; i++)
734	    {
735	      uint32_t length = bytes - offset;
736	
737	      if (length > CONTEST_I2S_RX_DESC_BYTES)
738	        {
739	          length = CONTEST_I2S_RX_DESC_BYTES;
740	        }
741	
742	      desc[i].ctrl = ESP32S3_DMA_CTRL_OWN |
743	                     (length << ESP32S3_DMA_CTRL_BUFLEN_S);
744	      desc[i].pbuf = buffer + offset;
745	      offset += length;
746	      desc[i].next = offset < bytes ? &desc[i + 1] : NULL;
747	    }
748	
749	  return offset;
750	}
