752	/* I2S_RX_EOF_NUM is a 32-bit word count encoded as count - 1.  The public
753	 * receive path remains byte based, so convert only at the register boundary.
754	 */
755	
756	static uint32_t contest_i2s_rx_eof_value(size_t raw_bytes)
757	{
758	  size_t words;
759	
760	  if (raw_bytes == 0 || raw_bytes % sizeof(uint32_t) != 0)
761	    {
762	      return UINT32_MAX;
763	    }
764	
765	  words = raw_bytes / sizeof(uint32_t);
766	  if (words == 0 || words - 1 > I2S_RX_EOF_NUM_V)
767	    {
768	      return UINT32_MAX;
769	    }
770	
771	  /* I2S_RX_EOF_NUM counts 32-bit words and is encoded as count - 1. */
772	  return (uint32_t)(words - 1);
773	}
