    char* result_str = cJSON_PrintUnformatted(result);
    cJSON_Delete(result);
    cJSON_Delete(j);

    if (!result_str) {
        snprintf(output, output_size, "Error: OOM building result");
        return -ENOMEM;
    }

    strlcpy(output, result_str, output_size);
    free(result_str);

    syslog(LOG_INFO, "[%s] Found %d songs for search\n", TAG, count);
    return 0;
}
"}],"is_error":false}

