532	            cJSON* first = songs ? cJSON_GetArrayItem(songs, 0) : NULL;
533	            cJSON* url = first ? cJSON_GetObjectItem(first, "url") : NULL;
534	            if (url && cJSON_IsString(url) && url->valuestring[0]) {
535	                char play_input[512];
536	                cJSON* play_obj = cJSON_CreateObject();
537	                char* play_json = NULL;
538	                cJSON* play_name = first ? cJSON_GetObjectItem(first, "name") : NULL;
539	                cJSON* play_artist = first ? cJSON_GetObjectItem(first, "artist") : NULL;
540	                if (play_obj) {
541	                    cJSON_AddStringToObject(play_obj, "url", url->valuestring);
542	                    if (play_name && cJSON_IsString(play_name))
543	                        cJSON_AddStringToObject(play_obj, "title", play_name->valuestring);
544	                    if (play_artist && cJSON_IsString(play_artist))
545	                        cJSON_AddStringToObject(play_obj, "artist", play_artist->valuestring);
546	                    play_json = cJSON_PrintUnformatted(play_obj);
547	                }
548	                snprintf(play_input, sizeof(play_input), "%s",
549	                    play_json ? play_json : "{}");
550	                free(play_json);
551	                cJSON_Delete(play_obj);
552	                char play_result[256];
553	                memset(play_result, 0, sizeof(play_result));
554	                tool_registry_execute("music_play", play_input, play_result, sizeof(play_result));
555	
556	                /* Build reply with song info */
557	                cJSON* name = cJSON_GetObjectItem(first, "name");
558	                cJSON* artist = cJSON_GetObjectItem(first, "artist");
559	                const char* sname = (name && cJSON_IsString(name)) ? name->valuestring : "未知";
560	                const char* sartist = (artist && cJSON_IsString(artist)) ? artist->valuestring : "未知";
561	
562	                /* Check if play actually succeeded */
563	                bool play_ok = (strstr(play_result, "error") == NULL && play_result[0] != '\0');
564	                reply = calloc(1, 512);
565	                if (reply) {
566	                    if (play_ok) {
567	                        snprintf(reply, 512, "正在播放: %s - %s", sname, sartist);
568	                    } else {
569	                        snprintf(reply, 512, "找到了 %s - %s，但播放失败: %s",
570	                            sname, sartist, play_result);
571	                    }
572	                }
573	            } else {
574	                reply = calloc(1, 4096);
575	                if (reply)
576	                    strncpy(reply, search_result, 4095);
577	            }
578	            cJSON_Delete(sr);
579	
580	            if (reply) {
581	                s_fast_path_count++;
582	                syslog(LOG_INFO,
583	                    "[%s] NL fast path: music_search (fast=%d llm=%d)\n",
584	                    TAG, s_fast_path_count, s_llm_path_count);
585	            }
586	            return reply;
587	        }
588	    }
589	
590	    return NULL;
591	}
