 902	/* ── Extracted: force finish when iteration limit reached ─── */
 903	
 904	static char* force_finish_reply(const char* system_prompt,
 905	    cJSON* messages)
 906	{
 907	    syslog(LOG_WARNING,
 908	        "[%s] Tool iteration limit (%d) reached, forcing finish\n",
 909	        TAG, AGENT_AI_AGENT_MAX_TOOL_ITER);
 910	
 911	    cJSON* hint = cJSON_CreateObject();
 912	    cJSON_AddStringToObject(hint, "role", "system");
 913	    cJSON_AddStringToObject(hint, "content",
 914	        "You have used all available tool iterations. "
 915	        "Do NOT call any more tools. Summarize what you have "
 916	        "learned so far and reply to the user in plain text now.");
 917	    cJSON_AddItemToArray(messages, hint);
 918	
 919	    llm_response_t resp;
 920	    char* result = NULL;
 921	    uint64_t t0 = monotonic_ms();
 922	    int err = llm_chat_tools(system_prompt, messages, NULL, &resp);
 923	    uint64_t t1 = monotonic_ms();
 924	    uint64_t ms = monotonic_elapsed_ms(t0, t1);
 925	    bool timed_out = llm_watchdog_expired(ms, err);
 926	
 927	    if (err == OK && !timed_out && resp.text && resp.text_len > 0) {
 928	        result = strdup(resp.text);
 929	    }
 930	    llm_response_free(&resp);
 931	
 932	    if (!result && timed_out) {
 933	        result = strdup(LLM_TIMEOUT_MSG);
 934	    }
 935	
 936	    return strip_tool_call_markup(result);
 937	}
