1019	/* Check for duplicate tool calls. Returns true if loop should break. */
1020	static bool check_tool_dup(const llm_response_t* resp,
1021	    char* prev_sig, int* dup_count,
1022	    char* prev_name, int* name_repeat)
1023	{
1024	    if (resp->call_count != 1) {
1025	        prev_sig[0] = '\0';
1026	        *dup_count = 0;
1027	        prev_name[0] = '\0';
1028	        *name_repeat = 0;
1029	        return false;
1030	    }
1031	
1032	    /* Exact match (name + args) */
1033	    char cur_sig[512];
1034	
1035	    snprintf(cur_sig, sizeof(cur_sig), "%s|%.400s",
1036	        resp->calls[0].name,
1037	        resp->calls[0].input ? resp->calls[0].input : "");
1038	
1039	    if (strcmp(cur_sig, prev_sig) == 0) {
1040	        (*dup_count)++;
1450	    } else if (final_text) {
1451	        agent_trace_end(&trace, AGENT_TRACE_OK);
1452	    } else {
1453	        agent_trace_end(&trace, AGENT_TRACE_FAIL);
1454	    }
1455	
1456	send_reply:
1457	    /* Cache store: save simple query responses for future reuse */
1458	    if (cacheable && !watchdog_fired && final_text && msg->content
1459	        && complexity == LLM_COMPLEXITY_SIMPLE) {
1460	        llm_cache_put(msg->content, strlen(msg->content), final_text);
1461	        if (last_total_tokens > 0) {
1462	            llm_cache_put_tokens(msg->content, strlen(msg->content),
1463	                last_total_tokens);
1464	        }
