1517	/* ── Main agent loop task ─────────────────────────────────── */
1518	
1519	static void* agent_loop_task(void* arg)
1520	{
1521	    (void)arg;
1522	    agent_mem_status_t mem_st;
1523	
1524	    agent_mem_get_status(&mem_st);
1525	    syslog(LOG_INFO, "[%s] Agent loop started, free heap: %zu\n",
1526	        TAG, mem_st.free_heap);
1527	
1528	    size_t ctx_size = agent_mem_safe_size(
1529	        AGENT_CONTEXT_BUF_SIZE, 4 * 1024);
1530	    size_t hist_size = agent_mem_safe_size(
1531	        AGENT_LLM_STREAM_BUF_SIZE, 8 * 1024);
1532	    size_t tool_size = agent_mem_safe_size(
1533	        TOOL_OUTPUT_SIZE, TOOL_OUTPUT_SIZE_MIN);
1534	
1535	    char* sys_prompt = calloc(1, ctx_size);
1536	    char* history_json = calloc(1, hist_size);
1537	    char* tool_output = calloc(1, tool_size);
1538	
1539	    if (!sys_prompt || !history_json || !tool_output) {
1540	        syslog(LOG_ERR, "[%s] Failed to allocate agent buffers\n", TAG);
1541	        free(sys_prompt);
1542	        free(history_json);
1543	        free(tool_output);
1544	        return NULL;
1545	    }
1546	
1547	    syslog(LOG_INFO, "[%s] Buffers: ctx=%zu hist=%zu tool=%zu\n",
1548	        TAG, ctx_size, hist_size, tool_size);
1549	
1550	    /* Initialize memory pool for parallel tool outputs */
1551	    size_t pool_buf_size = agent_mem_safe_size(
1552	        TOOL_OUTPUT_SIZE_LARGE, TOOL_OUTPUT_SIZE_MIN);
1553	    if (agent_pool_init(&s_tool_pool, pool_buf_size,
1554	            AGENT_MAX_TOOL_CALLS)
1555	        == OK) {
1556	        s_pool_ready = true;
1557	        syslog(LOG_INFO, "[%s] Tool output pool: %d x %zu bytes\n",
1558	            TAG, AGENT_MAX_TOOL_CALLS, pool_buf_size);
1559	    } else {
1560	        syslog(LOG_WARNING,
1561	            "[%s] Pool init failed, using heap fallback\n", TAG);
1562	    }
1563	
1564	    char* tools_json = tool_registry_get_tools_json();
1565	
1566	    syslog(LOG_INFO, "[%s] Tools JSON loaded: %d bytes\n",
1567	        TAG, tools_json ? (int)strlen(tools_json) : 0);
1568	
1569	    while (!agent_shutdown_requested()) {
1570	        agent_msg_t msg;
1571	        int err = message_bus_pop_inbound(&msg, UINT32_MAX);
1572	
1573	        if (err != OK) {
1574	            continue;
1575	        }
1576	
1577	        if (agent_shutdown_requested()) {
1578	            free(msg.content);
1579	            free(msg.image_b64);
1580	            break;
1581	        }
1582	
1583	        syslog(LOG_INFO, "[%s] Processing message from %s:%s\n",
1584	            TAG, msg.channel, msg.chat_id);
1585	
1586	        /* Check memory pressure */
1587	        agent_mem_get_status(&mem_st);
1588	        if (mem_st.free_heap < AGENT_MEM_RESERVE_BYTES) {
1589	            syslog(LOG_WARNING,
1590	                "[%s] Low memory: %zu bytes free, skipping\n",
1591	                TAG, mem_st.free_heap);
1592	            agent_msg_t out = { 0 };
1593	            strncpy(out.channel, msg.channel,
1594	                sizeof(out.channel) - 1);
1595	            strncpy(out.chat_id, msg.chat_id,
1596	                sizeof(out.chat_id) - 1);
1597	            out.flags = msg.flags;
1598	            out.content = strdup("系统内存不足，请稍后再试。");
1599	            if (out.content) {
1600	                if (message_bus_push_outbound(&out) != OK) {
1601	                    free(out.content);
1602	                }
1603	            }
1604	            free(msg.content);
1605	            continue;
1606	        }
1607	
1608	        /* Slash commands — fast path, bypass LLM */
1609	        char* reply = handle_slash_command(&msg);
1610	
1611	        /* Prompt injection check — before LLM */
1612	        if (!reply && tool_guard_check_injection(msg.content)) {
1613	            syslog(LOG_WARNING,
1614	                "[%s] Prompt injection blocked from %s:%s\n",
1615	                TAG, msg.channel, msg.chat_id);
1616	            reply = strdup("I can't do that.");
1617	            if (!reply) {
1618	                /* Fail-closed: skip this message entirely */
1619	                free(msg.content);
1620	                continue;
1621	            }
1622	        }
1623	
1624	        /* NL fast path — after injection check, before LLM */
1625	        if (!reply) {
1626	            reply = handle_nl_fast_path(msg.content);
1627	        }
1628	
1629	        if (reply) {
1630	            agent_msg_t out = { 0 };
1631	            strncpy(out.channel, msg.channel,
1632	                sizeof(out.channel) - 1);
1633	            strncpy(out.chat_id, msg.chat_id,
1634	                sizeof(out.chat_id) - 1);
1635	            out.flags = msg.flags;
1636	            out.content = reply;
1637	            if (message_bus_push_outbound(&out) != OK) {
1638	                free(reply);
1639	            }
1640	            free(msg.content);
1641	            continue;
1642	        }
1643	
1644	        /* Hot-reload skills if directory changed */
1645	        if (skill_loader_check_changed()) {
1646	            syslog(LOG_INFO, "[%s] Skills changed, refreshing\n", TAG);
1647	            skill_loader_refresh();
1648	        }
1649	
1650	        context_build_system_prompt(sys_prompt, ctx_size);
1651	        inject_session_context(sys_prompt, ctx_size,
1652	            msg.channel, msg.chat_id);
1653	
1654	        /* Refresh tools JSON — Node tools are dynamic */
1655	        free(tools_json);
1656	        tools_json = tool_registry_get_tools_json();
1657	
1658	        cJSON* messages = build_messages(msg.chat_id, msg.content,
1659	            history_json, hist_size);
1660	
1661	        char* final_text = NULL;
1662	
1663	        /* Vision path */
1664	        final_text = handle_vision_message(&msg);
1665	        if (final_text) {
1666	            cJSON_Delete(messages);
1667	        } else {
1668	            /* ReAct loop */
1669	            s_llm_path_count++;
1670	            final_text = run_react_loop(sys_prompt, messages,
1671	                tools_json, tool_output, tool_size, &msg);
1672	            cJSON_Delete(messages);
1673	        }
1674	
1675	        dispatch_response(&msg, final_text);
1676	
1677	        /* Free image_b64 if not already freed by vision path */
1678	        free(msg.image_b64);
1679	        msg.image_b64 = NULL;
1680	        free(msg.content);

380	 * Reads messages from the outbound queue and dispatches them to the
381	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
382	 */
383	static void* outbound_dispatch_task(void* arg)
384	{
385	    (void)arg;
386	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
387	
388	    while (!g_shutdown_requested) {
389	        agent_msg_t msg;
390	        if (message_bus_pop_outbound(&msg, 1000) != OK)
391	            continue;
392	        msg.channel[sizeof(msg.channel) - 1] = '\0';
393	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
394	
395	        if (!msg.content) {
396	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
397	            continue;
398	        }
399	
400	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
401	
402	        /* Let registered taps intercept before normal dispatch */
403	        if (mbus_tap_try_deliver(&msg)) {
404	            free(msg.content);
405	            continue;
406	        }
407	
408	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
409	            bool delivered = false;
410	#ifdef CONFIG_AI_AGENT_FEISHU
411	            const char* app_id = feishu_get_app_id();
412	            if (app_id && app_id[0] != '\0') {
413	                delivered = feishu_send_message(msg.chat_id, msg.content) == OK;
414	                if (!delivered) {
415	                    syslog(LOG_WARNING,
416	                        "[%s] Feishu response delivery failed\n", TAG);
417	                }
418	            }
419	#endif
420	#ifdef CONFIG_AI_AGENT_NODE
421	            if (!delivered) {
422	                delivered = node_client_send_chat_message(
423	                    msg.channel, msg.chat_id, msg.content) == OK;
424	            }
425	#endif
426	            if (!delivered) {
427	                syslog(LOG_WARNING,
428	                    "[%s] Feishu message dropped: no local config "
429	                    "and no gateway\n",
430	                    TAG);
431	            } else if ((msg.flags & AGENT_MSG_FLAG_NO_TTS) == 0) {
432	                int vret = voice_channel_speak(msg.content);
433	                if (vret != 0) {
434	                    syslog(LOG_WARNING,
435	                        "[%s] Feishu response TTS failed: %d\n", TAG, vret);
436	                } else {
437	                    syslog(LOG_INFO,
438	                        "[%s] Feishu response spoken locally\n", TAG);
439	                }
440	            } else {
441	                syslog(LOG_INFO,
442	                    "[%s] Feishu response text-only by user request\n", TAG);
443	            }
444	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
445	            ws_server_send(msg.chat_id, msg.content);
580	#else
581	        syslog(LOG_INFO, "[AGENT-STACK-HEAP] separate_internal=0\n");
582	#endif
583	    }
584	
585	    /* ── Phase 1: Core infrastructure ──────────────────────── */
586	    {
587	        int rc;
588	        rc = config_store_init();
589	        BOOT_LOG_RC(&t0, "P1", "config_store_init", rc);
590	
591	        rc = message_bus_init();
592	        BOOT_LOG_RC(&t0, "P1", "message_bus_init", rc);
593	        if (rc != OK)
594	            return -1;
595	
596	        rc = memory_store_init();
597	        BOOT_LOG_RC(&t0, "P1", "memory_store_init", rc);
598	
599	        rc = session_mgr_init();
600	        BOOT_LOG_RC(&t0, "P1", "session_mgr_init", rc);
601	    }
602	
603	    /* ── Phase 2: Proxy / networking ───────────────────────── */
604	    {
605	        int rc = http_proxy_init();
606	        BOOT_LOG_RC(&t0, "P2", "http_proxy_init", rc);
607	    }
608	
