1115	/* Run the ReAct tool-calling loop. Returns final_text (caller owns). */
1116	static char* run_react_loop(const char* sys_prompt, cJSON* messages,
1117	    const char* tools_json, char* tool_output, size_t tool_size,
1118	    const agent_msg_t* msg)
1119	{
1120	    char prev_sig[512];
1121	    int dup_count;
1122	    char prev_name[64];
1123	    int name_repeat;
1124	    int iteration;
1125	    char* final_text = NULL;
1126	
1127	    prev_sig[0] = '\0';
1128	    dup_count = 0;
1129	    prev_name[0] = '\0';
1130	    name_repeat = 0;
1131	    int last_total_tokens = 0;
1132	    bool watchdog_fired = false;
1133	    bool cacheable = false;
1134	
1135	    /* Router: select and apply best backend before first LLM call.
1136	     * Estimate complexity from the last user message. */
1137	    llm_complexity_t complexity = LLM_COMPLEXITY_SIMPLE;
1138	    if (msg->content) {
1139	        complexity = llm_router_estimate_complexity(
1140	            msg->content, strlen(msg->content));
1141	    }
1142	    int router_idx = llm_router_select(complexity);
1143	    if (router_idx >= 0) {
1144	        llm_router_apply(router_idx);
1145	    }
1146	
1147	    /* Structured trace: begin */
1148	    agent_trace_t trace;
1149	    agent_trace_begin(&trace, msg->chat_id, msg->channel);
1150	    trace.backend_idx = router_idx;
1151	
1152	    /* Cache check: for simple queries, try cache before LLM call */
1153	    if (msg->content && complexity == LLM_COMPLEXITY_SIMPLE) {
1154	        char* cached = llm_cache_get(msg->content, strlen(msg->content));
1155	        if (cached) {
1156	            syslog(LOG_INFO,
1157	                "[%s] Cache hit (successful answer), skipping LLM call\n",
1158	                TAG);
1159	            final_text = cached;
1160	            agent_trace_step(&trace, 0, NULL, 0, 1);
1161	            agent_trace_end(&trace, AGENT_TRACE_OK);
1162	            goto send_reply;
1163	        }
1164	    }
1165	
1166	    for (iteration = 0; iteration < AGENT_AI_AGENT_MAX_TOOL_ITER;
1167	         iteration++) {
1168	        send_working_status(msg, iteration);
1169	
1170	        llm_response_t resp;
1171	        uint64_t tv_start = monotonic_ms();
1172	        int err = llm_chat_tools(sys_prompt, messages, tools_json, &resp);
1173	        uint64_t tv_end = monotonic_ms();
1174	        uint64_t latency_ms = monotonic_elapsed_ms(tv_start, tv_end);
1175	
1176	        /* Router failover: on LLM call failure, try next backend */
1177	        if (err != OK && router_idx >= 0) {
