1179	                "[%s] LLM call failed on backend %d, trying failover\n",
1180	                TAG, router_idx);
1181	            llm_router_report_failure(router_idx);
1182	
1183	            int next_idx = llm_router_select(complexity);
1184	            if (next_idx >= 0 && next_idx != router_idx) {
1185	                llm_router_apply(next_idx);
1186	                router_idx = next_idx;
1187	                trace.backend_idx = next_idx;
1188	                llm_response_free(&resp);
1189	                tv_start = monotonic_ms();
1190	                err = llm_chat_tools(sys_prompt, messages,
1191	                    tools_json, &resp);
1192	                tv_end = monotonic_ms();
1193	                latency_ms = monotonic_elapsed_ms(tv_start, tv_end);
1194	            }
1195	        }
1196	
1197	        if (err != OK) {
1198	            /* Distinguish timeout-induced failure from other errors */
1199	            if (llm_watchdog_expired(latency_ms, err)) {
1200	                syslog(LOG_WARNING,
1201	                    "[%s] LLM watchdog: call failed after %" PRIu64 " ms "
1202	                    "(limit %ds)\n",
1203	                    TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
