1207	                final_text = strdup(LLM_TIMEOUT_MSG);
1208	                watchdog_fired = true;
1209	                break;
1210	            }
1211	            syslog(LOG_ERR, "[%s] LLM call failed (iter %d)\n",
1212	                TAG, iteration);
1213	            agent_trace_step(&trace, iteration, NULL, latency_ms, 0);
1214	            llm_response_free(&resp);
1215	            break;
1216	        }
1217	
1218	        /* Watchdog: if the LLM call took longer than the configured
1219	         * timeout, treat it as a timeout even if it returned OK.
1220	         * The socket SO_RCVTIMEO may have fired and caused a partial
