1265	                }
1266	            }
1267	
1268	            if (cascade_retry) {
1269	                syslog(LOG_INFO,
1270	                    "[%s] Cascade: cheap response inadequate, "
1271	                    "retrying with PREMIUM\n",
1272	                    TAG);
1273	
1274	                /* Save the cheap response as fallback before freeing */
1275	                char* fallback_text = NULL;
1276	                if (resp.text && resp.text_len > 0) {
1277	                    fallback_text = strdup(resp.text);
1278	                }
1279	                llm_response_free(&resp);
1280	
1281	                /* Select a PREMIUM backend without changing profile */
1282	                int prem_idx = llm_router_select_with_profile(
1283	                    LLM_COMPLEXITY_MEDIUM, LLM_ROUTE_PREMIUM);
1284	
1285	                if (prem_idx >= 0 && prem_idx != router_idx) {
1286	                    llm_router_apply(prem_idx);
1287	                    router_idx = prem_idx;
1288	                    trace.backend_idx = prem_idx;
1289	
1290	                    tv_start = monotonic_ms();
1291	                    err = llm_chat_tools(sys_prompt, messages,
1292	                        tools_json, &resp);
1293	                    tv_end = monotonic_ms();
1294	                    latency_ms = monotonic_elapsed_ms(tv_start, tv_end);
1295	
1296	                    /* Watchdog check on cascade retry */
1297	                    if (llm_watchdog_expired(latency_ms, err)) {
1298	                        syslog(LOG_WARNING,
1299	                            "[%s] LLM watchdog: cascade retry "
1300	                            "took %" PRIu64 " ms\n",
1301	                            TAG, latency_ms);
1302	                        free(fallback_text);
1303	                        fallback_text = NULL;
1304	                        final_text = strdup(LLM_TIMEOUT_MSG);
1305	                        watchdog_fired = true;
1306	                        agent_trace_step(&trace, iteration, NULL,
1307	                            latency_ms, 0);
1308	                        llm_response_free(&resp);
1309	                        break;
1310	                    }
1311	
1312	                    if (err == OK && resp.text && resp.text_len > 0) {
1313	                        final_text = strdup(resp.text);
1314	                        cacheable = final_text != NULL;
1315	                        free(fallback_text);
1316	                        fallback_text = NULL;
1317	                    } else {
1318	                        /* Premium failed — fall back to cheap response */
1319	                        final_text = fallback_text;
1320	                        cacheable = final_text != NULL;
1321	                        fallback_text = NULL;
1322	                    }
1323	                    agent_trace_step(&trace, iteration, NULL,
1324	                        latency_ms, err == OK);
1325	                    llm_response_free(&resp);
1326	                    break;
1327	                }
1328	                /* No premium backend available — use cheap response */
1329	                final_text = fallback_text;
1330	                cacheable = final_text != NULL;
1331	                fallback_text = NULL;
1332	                agent_trace_step(&trace, iteration, NULL, latency_ms, 1);
1333	                break;
1334	            }
1335	
1336	            if (resp.text && resp.text_len > 0 && !final_text) {
1337	                final_text = strdup(resp.text);
1338	                cacheable = final_text != NULL;
1339	            }
1340	            agent_trace_step(&trace, iteration, NULL, latency_ms, 1);
1341	            llm_response_free(&resp);
1342	            break;
1343	        }
1344	
1345	        syslog(LOG_INFO, "[%s] Tool iter %d: %d calls\n",
1346	            TAG, iteration + 1, resp.call_count);
1347	
1348	        /* Trace: log tool step */
1349	        agent_trace_step(&trace, iteration,
1350	            resp.call_count > 0 ? resp.calls[0].name : NULL,
1351	            latency_ms, 1);
1352	
1353	        /* Duplicate detection — break if stuck in a loop */
1354	        bool should_break = check_tool_dup(
1355	            &resp, prev_sig, &dup_count, prev_name, &name_repeat);
1356	
1357	        if (should_break) {
