1361	            llm_response_free(&resp);
1362	            break;
1363	        }
1364	
1365	        add_assistant_message(messages, &resp);
1366	        add_tool_result_messages(messages, &resp, tool_output,
1367	            tool_size, msg->channel, msg->chat_id);
1368	
1369	        /* Local tool shortcut: if the single tool in this round is a
1370	         * local file op, skip the next LLM round and use the tool
1371	         * output directly as the reply. Saves ~2s.
1372	         * Restricted to call_count == 1: the parallel path does not
