  1308	static int rv_write_scaled_pcm16(const void *data, size_t len)
  1309	{
  1310	  const uint8_t *src = data;
  1311	  uint8_t scaled[RV_MUSIC_SCALE_CHUNK];
  1312	  size_t offset = 0;
  1313	
  1314	  if (!data || len == 0)
  1315	    {
  1316	      return -EINVAL;
  1317	    }
  1318	
  1319	  while (offset < len)
  1320	    {
  1321	      size_t chunk = len - offset;
  1322	      size_t even;
  1323	      size_t i;
  1324	      int ret;
  1325	
  1326	      if (chunk > sizeof(scaled))
  1327	        {
  1328	          chunk = sizeof(scaled);
  1329	        }
  1330	
  1331	      if ((chunk & 1u) != 0 && chunk > 1)
  1332	        {
  1333	          chunk--;
  1334	        }
  1335	
  1336	      even = chunk & ~(size_t)1u;
  1337	
  1338	      for (i = 0; i < even; i += 2)
  1339	        {
  1340	          uint16_t raw = (uint16_t)src[offset + i] |
  1341	                         ((uint16_t)src[offset + i + 1] << 8);
  1342	          int16_t sample = (int16_t)raw;
  1343	          int16_t quieter =
  1344	            (int16_t)((sample * RV_MUSIC_GAIN_NUM) / RV_MUSIC_GAIN_DEN);
  1345	
  1346	          scaled[i] = (uint8_t)((uint16_t)quieter & 0xff);
  1347	          scaled[i + 1] = (uint8_t)(((uint16_t)quieter >> 8) & 0xff);
  1348	        }
  1349	
  1350	      if (chunk > even)
  1351	        {
  1352	          scaled[even] = src[offset + even];
  1353	        }
  1354	
  1355	      ret = robot_audio_playback_write(scaled, chunk);
  1356	      if (ret < 0)
  1357	        {
  1358	          return ret;
  1359	        }
  1360	
  1361	      offset += chunk;
  1362	    }
  1363	
  1364	  return 0;
  1365	}
