                                    rv_media_event_callback callback)
{
  struct rv_media_player *player = handle;

  if (!player)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&player->lock);
  player->callback_cookie = cookie;
  player->callback = callback;
  pthread_mutex_unlock(&player->lock);
  return 0;
}

