 25	/* ── Outgoing @mention conversion ──────────────────────────────── */
 26	
 27	static char* convert_outgoing_mentions(const char* text, size_t* clean_end)
 28	{
 29	    typedef struct {
 30	        char name[64];
 31	        char oid[64];
 32	    } mention_entry_t;
 33	
 34	    mention_entry_t mmap[8];
 35	    int mcount = 0;
 36	
 37	    const char* block = strstr(text, "\n[mentioned_users:");
 38	    if (!block) {
 39	        block = strstr(text, "[mentioned_users:");
 40	    }
 41	
 42	    size_t text_end = strlen(text);
 43	
 44	    if (block) {
 45	        text_end = (size_t)(block - text);
 46	        const char* start = strchr(block, ':');
 47	        const char* end = strchr(block, ']');
 48	
 49	        if (start && end && start < end) {
 50	            start++;
 51	            while (start < end && mcount < 8) {
 52	                while (start < end && *start == ' ') {
 53	                    start++;
 54	                }
 55	
 56	                const char* eq = memchr(start, '=', (size_t)(end - start));
 57	                if (!eq) {
 58	                    break;
 59	                }
 60	
 61	                const char* comma = memchr(eq, ',', (size_t)(end - eq));
 62	                if (!comma) {
 63	                    comma = end;
 64	                }
 65	
 66	                size_t nlen = (size_t)(eq - start);
 67	                size_t olen = (size_t)(comma - eq - 1);
 68	
 69	                if (nlen > 0 && nlen < 64 && olen > 0 && olen < 64) {
 70	                    memcpy(mmap[mcount].name, start, nlen);
 71	                    mmap[mcount].name[nlen] = '\0';
 72	                    memcpy(mmap[mcount].oid, eq + 1, olen);
 73	                    mmap[mcount].oid[olen] = '\0';
 74	                    mcount++;
 75	                }
 76	                start = comma < end ? comma + 1 : end;
 77	            }
 78	        }
 79	    }
 80	
 81	    *clean_end = text_end;
 82	
 83	    bool need_convert = (mcount > 0) || strstr(text, "(open_id:");
 84	    if (!need_convert) {
 85	        return NULL;
 86	    }
 87	
 88	    size_t alloc = text_end * 3 + 1;
 89	    char* out = malloc(alloc);
 90	    if (!out) {
 91	        return NULL;
 92	    }
 93	
 94	    size_t out_off = 0;
 95	    const char* p = text;
 96	    const char* p_end = text + text_end;
 97	
 98	    while (p < p_end && out_off < alloc - 1) {
 99	        if (*p == '@') {
100	            /* Try inline: @name(open_id:ou_xxx) */
101	            const char* ns = p + 1;
102	            const char* paren = NULL;
103	
104	            for (const char* s = ns; s < p_end && *s != ' ' && *s != '\n'; s++) {
105	                if (*s == '(') {
106	                    paren = s;
107	                    break;
108	                }
109	            }
110	
111	            if (paren && (size_t)(p_end - paren) > 9 &&
112	                strncmp(paren, "(open_id:", 9) == 0) {
113	                const char* id_s = paren + 9;
114	                const char* id_e = strchr(id_s, ')');
115	
116	                if (id_e && id_e <= p_end && (size_t)(id_e - id_s) < 64) {
117	                    int n = snprintf(out + out_off, alloc - out_off,
118	                        "<at user_id=\"%.*s\">%.*s</at>",
119	                        (int)(id_e - id_s), id_s,
120	                        (int)(paren - ns), ns);
121	                    if (n > 0) {
122	                        out_off += (size_t)n;
123	                    }
124	                    p = id_e + 1;
125	                    continue;
126	                }
127	            }
128	
129	            /* Try map-based: @name from mention map */
130	            if (mcount > 0) {
131	                bool matched = false;
132	
133	                for (int i = 0; i < mcount; i++) {
134	                    size_t nlen = strlen(mmap[i].name);
135	
136	                    if (ns + nlen <= p_end &&
137	                        strncmp(ns, mmap[i].name, nlen) == 0) {
138	                        char next = (ns + nlen < p_end) ? ns[nlen] : ' ';
139	                        if (next == ' ' || next == '\n' || next == ',' ||
140	                            next == '\0' || (unsigned char)next >= 0x80) {
141	                            int n = snprintf(out + out_off, alloc - out_off,
142	                                "<at user_id=\"%s\">%s</at>",
143	                                mmap[i].oid, mmap[i].name);
144	                            if (n > 0) {
145	                                out_off += (size_t)n;
146	                            }
147	                            p = ns + nlen;
148	                            matched = true;
149	                            break;
150	                        }
151	                    }
152	                }
153	                if (matched) {
154	                    continue;
155	                }
156	            }
157	        }
158	        out[out_off++] = *p++;
159	    }
160	    out[out_off] = '\0';
161	    return out;
162	}
