  4921	void robot_voice_llm_stream_commit(void *arg)
  4922	{
  4923	  struct rv_llm_speech_s *s = arg;
  4924	  if (!s) return;
  4925	  pthread_mutex_lock(&s->lock);
  4926	  if (!s->cancel && s->hold && s->retry_text) {
  4927	    /* cursor includes queued audio. Matching retries resume after it once.
  4928	     * If the retry changes that text, cancel this stream and let the final
  4929	     * Agent reply use the existing fallback rather than splice two answers. */
  4930	    if (s->retry_used < s->cursor ||
  4931	        memcmp(s->text, s->retry_text, s->cursor)) {
  4932	      s->cancel = true;
  4933	      RV_EVENT("[RV-LLM-TTS] retry changed submitted text; using final reply\n");
  4934	    } else {
  4935	      memcpy(s->text, s->retry_text, s->retry_used + 1);
  4936	      s->used = s->retry_used;
  4937	      s->phrase_wait_since_ms = 0;
  4938	    }
  4939	    free(s->retry_text); s->retry_text = NULL; s->retry_used = 0;
  4940	  }
  4941	  if (!s->cancel) s->hold = false;
  4942	  pthread_cond_broadcast(&s->changed);
  4943	  pthread_mutex_unlock(&s->lock);
  4944	}
