  4964	void robot_voice_llm_stream_delta(void *arg, const char *text, size_t n, bool tools)
  4965	{
  4966	  struct rv_llm_speech_s *s = arg;
  4967	  if (!s) return;
  4968	  if (tools || (text && n)) {
  4969	    pthread_mutex_lock(&g_monitor.lock);
  4970	    if (s->run_token == rv_run_token_load()) rv_lock_reply_locked(s->run_id);
  4971	    pthread_mutex_unlock(&g_monitor.lock);
  4972	  }
  4973	  pthread_mutex_lock(&s->lock);
  4974	  if (tools) s->cancel = true;
  4975	  if (!s->cancel && s->hold && text && n) {
  4976	    if (!s->retry_text || n >= ROBOT_VOICE_TEXT_CAP - s->retry_used)
  4977	      s->cancel = true;
  4978	    else {
  4979	      memcpy(s->retry_text + s->retry_used, text, n);
  4980	      s->retry_used += n; s->retry_text[s->retry_used] = 0;
  4981	    }
  4982	  } else if (!s->cancel && text && n) {
  4983	    if (n >= ROBOT_VOICE_TEXT_CAP - s->used) s->cancel = true;
  4984	    else {
  4985	      memcpy(s->text + s->used, text, n); s->used += n; s->text[s->used] = 0;
  4986	      if (!s->first_logged) {
  4987	        for (size_t i = 0; i < s->used; i++) {
  4988	          if (s->text[i] == '.' && i + 1 == s->used && i > 0 &&
  4989	              s->text[i - 1] >= '0' && s->text[i - 1] <= '9') continue;
  4990	          if (rv_sentence_punctuation(s->text + i, s->used - i, i, 0)) {
  4991	            s->first_logged = true;
  4992	            RV_EVENT("[耗时][Flash分句] 首个完整句子=%lldms\n",
  4993	              rv_elapsed_ms(s->started_ms, robot_voice_now_ms()));
  4994	            RV_VERBOSE("[RV-LLM-TTS] first_complete_sentence mono_ms=%llu run=%lu\n",
  4995	                   robot_voice_now_ms(), s->run_id);
  4996	            break;
  4997	          }
  4998	        }
  4999	      }
  5000	    }
  5001	  }
  5002	  pthread_cond_broadcast(&s->changed); pthread_mutex_unlock(&s->lock);
  5003	}
