457	int robotctl_servo_move_all(struct robotctl_servo_ctx_s *ctx,
458	                            const int target[ROBOTCTL_SERVO_COUNT],
459	                            int duration_ms)
460	{
461	  int frame[ROBOTCTL_SERVO_COUNT];
462	  int start[ROBOTCTL_SERVO_COUNT];
463	  int steps;
464	  int ret;
465	  int i;
466	  int step;
467	
468	  memcpy(start, ctx->angle, sizeof(start));
469	  steps = duration_ms / ROBOTCTL_NORMAL_UPDATE_MS;
470	  if (steps < 1)
471	    {
472	      steps = 1;
473	    }
474	
475	  for (step = 1; step <= steps; step++)
476	    {
477	      for (i = 0; i < ROBOTCTL_SERVO_COUNT; i++)
478	        {
479	          frame[i] = start[i] + ((target[i] - start[i]) * step) / steps;
480	        }
481	
482	      ret = robotctl_apply_frame(ctx, frame,
483	                                 (1u << ROBOTCTL_SERVO_COUNT) - 1u);
484	      if (ret < 0)
485	        {
486	          return ret;
487	        }
488	
489	      if (step != steps)
490	        {
491	          usleep(ROBOTCTL_NORMAL_UPDATE_MS * 1000);
492	        }
493	    }
494	
495	  memcpy(ctx->angle, target, sizeof(ctx->angle));
496	  return 0;
497	}

 330	static int robot_motion_home_power_safe(struct robotctl_servo_ctx_s *ctx,
 331	                                        bool include_tail)
 332	{
 333	  int count = include_tail ? ROBOTCTL_SERVO_COUNT : ROBOTCTL_SERVO_COUNT - 1;
 334	  int i;
 335	
 336	  for (i = 0; i < count; i++)
 337	    {
 338	      enum robotctl_servo_e servo = g_home_order[i];
 339	      int ret;
 340	
 341	      if (robot_motion_music_active()) return -ECANCELED;
 342	      printf("[ROBOT-MOTION] home move %s %d -> %d update=%s\n",
 343	             robotctl_servo_name(servo), ctx->angle[servo],
 344	             g_robotctl_home[servo],
 345	             ctx->angle_known[servo] &&
 346	             ctx->angle[servo] == g_robotctl_home[servo] ? "no" : "yes");
 347	      ret = robotctl_servo_move_one(ctx, servo, g_robotctl_home[servo],
 348	                                    ROBOT_MOTION_HOME_INTERVAL_MS,
 349	                                    ROBOT_MOTION_HOME_SETTLE_MS);
 350	      if (ret < 0)
 351	        {
 352	          return ret;
 353	        }
 354	    }
