 359	static enum robot_motion_phase_power_e robot_motion_phase_power(
 360	    const struct robotctl_servo_ctx_s *ctx,
 361	    const struct robot_motion_phase_s *phase, unsigned int *active)
 362	{
 363	  unsigned int count = 0;
 364	  unsigned int delta = 0;
 365	  unsigned int order;
 366	
 367	  for (order = 0; order < 2; order++)
 368	    {
 369	      enum robotctl_servo_e servo = phase->order[order];
 370	      int difference = phase->target[servo] - ctx->angle[servo];
 371	
 372	      if (difference != 0)
 373	        {
 374	          count++;
 375	          delta += (unsigned int)abs(difference);
 376	        }
 377	    }
 378	
 379	  if (active != NULL)
 380	    {
 381	      *active = count;
 382	    }
 383	
 384	  if (count >= 2 && delta >= 45)
 385	    {
 386	      return ROBOT_MOTION_PHASE_HEAVY;
 387	    }
 388	
 389	  return count == 0 ? ROBOT_MOTION_PHASE_LIGHT :
 390	                      ROBOT_MOTION_PHASE_MEDIUM;
 391	}
 392	
 393	static const char *robot_motion_phase_power_name(
 394	    enum robot_motion_phase_power_e power)
 395	{
 396	  static const char *const names[] =
 397	  {
 398	    "light", "medium", "heavy"
 399	  };
 400	
 401	  return power >= ROBOT_MOTION_PHASE_LIGHT &&
 402	         power <= ROBOT_MOTION_PHASE_HEAVY ? names[power] : "unknown";
 403	}
