 405	static int robot_motion_phase_settle(int settle_ms,
 406	                                     enum robot_motion_phase_power_e power)
 407	{
 408	  if (power == ROBOT_MOTION_PHASE_LIGHT)
 409	    {
 410	      settle_ms = settle_ms * 3 / 4;
 411	      return settle_ms < 60 ? 60 : settle_ms;
 412	    }
 413	
 414	  if (power == ROBOT_MOTION_PHASE_HEAVY)
 415	    {
 416	      settle_ms = settle_ms * 5 / 4;
 417	      return settle_ms > 200 ? 200 : settle_ms;
 418	    }
 419	
 420	  return settle_ms;
 421	}
