        {
          next = current + ROBOTCTL_SAFE_STEP_DEG;
          if (next > target)
            {
              next = target;
            }
        }
      else if (current > target)
        {
          next = current - ROBOTCTL_SAFE_STEP_DEG;
          if (next < target)
            {
              next = target;
            }
