static int robot_motion_tail_ramp_to(struct robotctl_servo_ctx_s *ctx,
                                     int target, int interval_ms,
                                     int cooldown_ms)
{
  int current;
  int next;
  int delta;
  int ret;

  if (ctx == NULL)
