   204	/* Keep a PWM step from running early when a task is interrupted by a signal. */
   205	static void robotctl_delay_ms(int delay_ms)
   206	{
   207	  struct timespec request;
   208	  struct timespec remaining;
   209	
   210	  if (delay_ms <= 0)
   211	    {
   212	      return;
   213	    }
   214	
   215	  request.tv_sec = delay_ms / 1000;
   216	  request.tv_nsec = (long)(delay_ms % 1000) * 1000000L;
   217	  while (nanosleep(&request, &remaining) < 0)
   218	    {
   219	      if (errno != EINTR)
   220	        {
   221	          break;
   222	        }
   223	
   224	      request = remaining;
   225	    }
   226	}
