   212	static int robot_motion_safe_interval(unsigned int period_ms)
   213	{
   214	  /* Keep the 3-degree POWER_SAFE increments.  The additional 5/4 time
   215	   * scale lowers limb speed by approximately 25% without changing gait
   216	   * geometry or the independent tail profile. */
   217	  int interval_ms = (int)period_ms / 125;
   218	
   219	  if (interval_ms < 12)
   220	    {
   221	      interval_ms = 12;
   222	    }
   223	  else if (interval_ms > 24)
   224	    {
   225	      interval_ms = 24;
   226	    }
   227	
   228	  interval_ms = robot_motion_scale_interval(interval_ms);
   229	  if (interval_ms < ROBOT_MOTION_LIMB_MIN_INTERVAL_MS)
   230	    {
   231	      interval_ms = ROBOT_MOTION_LIMB_MIN_INTERVAL_MS;
   232	    }
   233	
   234	  return interval_ms;
   235	}
