  1362	  if (robot_motion_music_active()) return -EPERM;
  1363	  pthread_mutex_lock(&g_motion.lock);
  1364	  if (g_motion.request_pending ||
  1365	      g_motion.state == ROBOT_MOTION_STATE_RUNNING)
  1366	    {
