  1371	  pthread_mutex_unlock(&g_motion.lock);
  1372	
  1373	  printf("[ROBOT-MOTION] backend init begin\n");
  1374	  ret = robotctl_servo_open(&ctx);
  1375	  printf("[ROBOT-MOTION] backend init done rc=%d\n", ret);
