   310	    {
   311	      /* A caller may close the context after a multi-servo frame or an
   312	       * error path.  Always remove the PWM waveform before releasing the
   313	       * device so an idle context cannot leave a servo actively driven. */
   314	      if (ctx->pwm_enabled)
