   318	          if (ret < 0)
   319	            {
   320	              fprintf(stderr,
   321	                      "robotctl: close could not stop PWM errno=%d\n",
   322	                      errno);
   323	            }
   324	          else
   325	            {
   326	              ctx->pwm_enabled = false;
   327	            }
   328	        }
   329	
   330	      close(ctx->fd);
   331	      ctx->fd = -1;
   332	    }
