 918	static int robot_motion_submit_request(
 919	    enum robot_motion_source_e source,
 920	    enum robot_motion_request_type_e type,
 921	    enum robot_motion_direction_e direction,
 922	    unsigned int steps, unsigned int period_ms, unsigned int amplitude_deg,
 923	    uint32_t music_session_id)
 924	{
 925	  int ret;
 926	  uint32_t request_id;
 927	
 928	  if (source < 0 || source >= ROBOT_MOTION_SOURCE_COUNT ||
 929	      type < 0 || type >= ROBOT_MOTION_REQUEST_TYPE_COUNT ||
 930	      direction < 0 || direction >= ROBOT_MOTION_DIRECTION_COUNT ||
 931	      steps < ROBOT_MOTION_MIN_STEPS || steps > ROBOT_MOTION_MAX_STEPS ||
 932	      (type == ROBOT_MOTION_REQUEST_GAIT &&
 933	       (period_ms < ROBOT_MOTION_MIN_PERIOD ||
 934	        period_ms > ROBOT_MOTION_MAX_PERIOD)))
 935	    {
 936	      return -EINVAL;
 937	    }
 938	
 939	  if (type == ROBOT_MOTION_REQUEST_TAIL_WAG &&
 940	      source != ROBOT_MOTION_SOURCE_MUSIC &&
 941	      (steps < ROBOT_MOTION_TAIL_MIN_CYCLES ||
 942	       steps > ROBOT_MOTION_TAIL_MAX_CYCLES ||
 943	       period_ms < ROBOT_MOTION_TAIL_MIN_PERIOD ||
 944	       period_ms > ROBOT_MOTION_TAIL_MAX_PERIOD ||
 945	       amplitude_deg < ROBOT_MOTION_TAIL_MIN_AMPLITUDE ||
 946	       amplitude_deg > ROBOT_MOTION_TAIL_MAX_AMPLITUDE))
 947	    {
 948	      return -EINVAL;
 949	    }
 950	
 951	  if (source == ROBOT_MOTION_SOURCE_MUSIC &&
 952	      (type != ROBOT_MOTION_REQUEST_TAIL_WAG ||
 953	       period_ms != ROBOT_MOTION_MUSIC_TAIL_STEP_MS ||
 954	       amplitude_deg != ROBOT_MOTION_MUSIC_TAIL_STEP_DEG))
 955	    {
 956	      return -EINVAL;
 957	    }
 958	
 959	  if (robot_motion_music_active() &&
 960	      (type == ROBOT_MOTION_REQUEST_GAIT || source != ROBOT_MOTION_SOURCE_MUSIC))
 961	    return -EPERM;
 962	  if (source == ROBOT_MOTION_SOURCE_MUSIC &&
 963	      (music_session_id == 0 || !robot_music_media_motion_allowed ||
 964	       !robot_music_media_motion_allowed(music_session_id)))
 965	    return -EAGAIN;
 966	
 967	  ret = robot_motion_init();
 968	  if (ret < 0)
 969	    {
 970	      return ret;
 971	    }
 972	
 973	  pthread_mutex_lock(&g_motion.lock);
 974	  if (g_motion.request_pending ||
 975	      g_motion.state == ROBOT_MOTION_STATE_RUNNING)
 976	    {
 977	      pthread_mutex_unlock(&g_motion.lock);
 978	      if (type == ROBOT_MOTION_REQUEST_TAIL_WAG)
 979	        {
 980	          printf("[ROBOT-MOTION] reject busy action=tail_wag\n");
 981	        }
 982	      else
 983	        {
 984	          printf("[ROBOT-MOTION] reject busy direction=%s\n",
 985	                 robot_motion_direction_name(direction));
 986	        }
 987	      return -EBUSY;
 988	    }
 989	
 990	  request_id = ++g_motion.next_request_id;
 991	  if (request_id == 0)
 992	    {
 993	      request_id = ++g_motion.next_request_id;
 994	    }
 995	  g_motion.request.source = source;
 996	  g_motion.request.type = type;
 997	  g_motion.request.direction = direction;
 998	  g_motion.request.steps = steps;
 999	  g_motion.request.period_ms = period_ms;
1000	  g_motion.request.amplitude_deg = amplitude_deg;
1001	  g_motion.request.music_session_id = music_session_id;
1002	  g_motion.request.request_id = request_id;
1003	  g_motion.cancel_requested = false;
1004	  g_motion.request_pending = true;
1005	  g_motion.state = ROBOT_MOTION_STATE_RUNNING;
1006	  pthread_cond_signal(&g_motion.cond);
1007	  pthread_mutex_unlock(&g_motion.lock);
1008	
1009	  if (type == ROBOT_MOTION_REQUEST_TAIL_WAG)
1010	    {
1011	      printf("[ROBOT-MOTION] submit id=%lu source=%d action=tail_wag "
1012	             "cycles=%u period_ms=%u amplitude=%u\n",
1013	             (unsigned long)request_id, source, steps, period_ms,
1014	             amplitude_deg);
1015	    }
1016	  else
1017	    {
1018	      printf("[ROBOT-MOTION] submit id=%lu source=%d direction=%s steps=%u "
1019	             "period_ms=%u\n", (unsigned long)request_id, source,
1020	             robot_motion_direction_name(direction), steps, period_ms);
1021	    }
1022	  return (int)request_id;
1023	}
