 574	static int robot_motion_execute_tail_wag(
 575	    const struct robot_motion_request_s *request)
 576	{
 577	  struct robotctl_servo_ctx_s ctx;
 578	  const int center = g_robotctl_home[ROBOTCTL_TAIL];
 579	  const int right = center + (int)request->amplitude_deg;
 580	  const int left = center - (int)request->amplitude_deg;
 581	  int interval_ms = robot_motion_tail_interval(request->period_ms);
 582	  int cooldown_ms = robot_motion_tail_cooldown_ms(request->period_ms, request->amplitude_deg);
 583	  int ret;
 584	  unsigned int cycle;
 585	
 586	  printf("[ROBOT-MOTION] tail wag begin cycles=%u requested_amplitude=%u "
 587	         "right_offset=%d left_offset=%d period_ms=%u interval_ms=%d "
 588	         "cooldown_ms=%d segment_deg=%d profile=music_micro_wag\n",
 589	         request->steps, request->amplitude_deg,
 590	         (int)request->amplitude_deg, (int)request->amplitude_deg,
 591	         request->period_ms, interval_ms, cooldown_ms,
 592	         ROBOT_MOTION_TAIL_SEGMENT_DEG);
 593	
 594	  ret = robotctl_servo_open(&ctx);
 595	  if (ret < 0)
 596	    {
 597	      return ret;
 598	    }
 599	
 600	  ctx.cancel_check = robot_motion_cancel_check;
 601	  ctx.cancel_arg = NULL;
 602	  if (abs(ctx.angle[ROBOTCTL_TAIL] - center) > ROBOT_MOTION_TAIL_MAX_AMPLITUDE)
 603	    {
 604	      robotctl_servo_close(&ctx);
 605	      return -ERANGE; /* Do not make a large centering move during music. */
 606	    }
 607	
 608	  /*
 609	   * Give the supply rail time to settle after opening the PWM backend.  This
 610	   * is especially useful when music/TTS/audio amplification is already active.
 611	   */
 612	  ret = robot_motion_tail_cooldown(ROBOT_MOTION_TAIL_OPEN_RECOVERY_MS);
 613	
 614	  /* Return through center using only bounded one-degree tail pulses. */
 615	  if (ret >= 0)
 616	    {
 617	      ret = robot_motion_tail_ramp_to(&ctx, center, interval_ms, cooldown_ms);
 618	    }
 619	
 620	  for (cycle = 0; ret >= 0 && cycle < request->steps; cycle++)
 621	    {
 622	      if (robot_motion_cancel_check(NULL))
 623	        {
 624	          ret = -ECANCELED;
 625	          break;
 626	        }
 627	
 628	      printf("[ROBOT-MOTION] tail wag cycle=%u/%u sweep=center->right\n",
 629	             cycle + 1, request->steps);
 630	      ret = robot_motion_tail_ramp_to(&ctx, right, interval_ms, cooldown_ms);
 631	
 632	      if (ret >= 0)
 633	        {
 634	          printf("[ROBOT-MOTION] tail wag cycle=%u/%u sweep=right->left\n",
 635	                 cycle + 1, request->steps);
 636	          ret = robot_motion_tail_ramp_to(&ctx, left, interval_ms, cooldown_ms);
 637	        }
 638	
 639	      if (ret >= 0)
 640	        {
 641	          printf("[ROBOT-MOTION] tail wag cycle=%u/%u sweep=left->center\n",
 642	                 cycle + 1, request->steps);
 643	          ret = robot_motion_tail_ramp_to(&ctx, center,
 644	                                          interval_ms, cooldown_ms);
 645	        }
 646	    }
 647	
 648	  if (ret >= 0 && ctx.angle[ROBOTCTL_TAIL] != center)
 649	    {
 650	      ret = robot_motion_tail_ramp_to(&ctx, center,
 651	                                      interval_ms, cooldown_ms);
 652	    }
 653	
 654	  if (ret >= 0) ret = robot_motion_tail_cooldown(ROBOT_MOTION_TAIL_OPEN_RECOVERY_MS);
 655	  robotctl_servo_close(&ctx);
 656	  printf("[ROBOT-MOTION] tail wag done rc=%d\n", ret);
 657	  return ret;
 658	}
