  item = cJSON_GetObjectItem(root, "cycles");
  if (item != NULL &&
      robot_motion_tool_number(item, ROBOT_MOTION_TAIL_MIN_CYCLES,
                               ROBOT_MOTION_TAIL_MAX_CYCLES, &cycles) < 0)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"cycles must be 1\"}");
      return ERROR;
    }

