static int robot_motion_tool_execute_move(const char *name,
                                          const char *input_json,
                                          char *output, size_t output_size)
{
  cJSON *root;
  cJSON *direction_item;
  cJSON *steps_item;
  cJSON *period_item;
  const char *direction_name;
  enum robot_motion_direction_e direction;
  unsigned int steps = ROBOT_MOTION_DEFAULT_STEPS;
  unsigned int period_ms;
  int ret;

  if (name == NULL || input_json == NULL || output == NULL ||
      output_size == 0 || strcmp(name, ROBOT_MOTION_TOOL_NAME) != 0)
    {
      return ERROR;
    }

  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_ENTER\n",
         robot_motion_tool_now_ms());
  printf("[ROBOT-MOTION-TOOL] execute input=%s\n", input_json);
  root = cJSON_Parse(input_json);
  if (root == NULL)
    {
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"invalid json\"}");
      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
             robot_motion_tool_now_ms(), -EINVAL);
      return ERROR;
    }

  direction_item = cJSON_GetObjectItem(root, "direction");
  direction_name = cJSON_GetStringValue(direction_item);
  ret = robot_motion_direction_from_name(direction_name, &direction);
  if (ret < 0)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"invalid direction\"}");
      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
             robot_motion_tool_now_ms(), -EINVAL);
      return ERROR;
    }

  period_ms = robot_motion_default_period(direction);
  steps_item = cJSON_GetObjectItem(root, "steps");
  if (steps_item != NULL &&
      robot_motion_tool_number(steps_item, ROBOT_MOTION_MIN_STEPS, 1,
                               &steps) < 0)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"steps must be 1\"}");
      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
             robot_motion_tool_now_ms(), -EINVAL);
      return ERROR;
    }

  period_item = cJSON_GetObjectItem(root, "period_ms");
  if (period_item != NULL &&
      robot_motion_tool_number(period_item, ROBOT_MOTION_MIN_PERIOD,
                               ROBOT_MOTION_MAX_PERIOD, &period_ms) < 0)
    {
      cJSON_Delete(root);
      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"period_ms must be 800..3000\"}");
      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
             robot_motion_tool_now_ms(), -EINVAL);
      return ERROR;
    }

  printf("[ROBOT-MOTION-TOOL] power-safe synchronous execution\n");
  printf("[ROBOT-MOTION-TOOL] direction=%s steps=%u period_ms=%u\n",
         direction_name, steps, period_ms);
  direction_name = robot_motion_direction_name(direction);
  cJSON_Delete(root);
  robot_action_guard_begin(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME);
  ret = robot_motion_submit_and_wait(
    ROBOT_MOTION_SOURCE_AGENT, direction, steps, period_ms,
    robot_motion_default_timeout(steps, period_ms), NULL);
  robot_action_guard_end(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME,
                         ret);

  if (ret < 0)
        {
          pthread_cond_wait(&g_motion.cond, &g_motion.lock);
        }

      request = g_motion.request;
      g_motion.request_pending = false;
      g_motion.state = ROBOT_MOTION_STATE_RUNNING;
      pthread_mutex_unlock(&g_motion.lock);

      if (robot_world_state_set_motion_active) robot_world_state_set_motion_active(true);
      if (request.source == ROBOT_MOTION_SOURCE_MUSIC)
        {
          printf("[ROBOT-MOTION] start id=%lu action=music_tail_step\n",
                 (unsigned long)request.request_id);
          ret = robot_motion_execute_music_tail_step(&request);
        }
      else if (request.type == ROBOT_MOTION_REQUEST_TAIL_WAG)
        {
          printf("[ROBOT-MOTION] start id=%lu action=tail_wag\n",
                 (unsigned long)request.request_id);
          printf("[POWER-SAFE] mono_ms=%llu MOTION_START id=%lu "
                 "action=tail_wag\n",
                 (unsigned long long)robot_motion_now_ms(),
                 (unsigned long)request.request_id);
          ret = robot_motion_execute_tail_wag(&request);
        }
      else
        {
          printf("[ROBOT-MOTION] start id=%lu direction=%s\n",
                 (unsigned long)request.request_id,
                 robot_motion_direction_name(request.direction));
          printf("[POWER-SAFE] mono_ms=%llu MOTION_START id=%lu "
                 "direction=%s\n", (unsigned long long)robot_motion_now_ms(),
                 (unsigned long)request.request_id,
                 robot_motion_direction_name(request.direction));
          ret = robot_motion_execute_gait(&request);
        }

      if (robot_world_state_set_motion_active) robot_world_state_set_motion_active(false);
      pthread_mutex_lock(&g_motion.lock);
      g_motion.last_result = ret;
      g_motion.completed_request_id = request.request_id;
      g_motion.state = ret < 0 ? ROBOT_MOTION_STATE_ERROR :
                            ROBOT_MOTION_STATE_IDLE;
      printf("[POWER-SAFE] mono_ms=%llu MOTION_DONE id=%lu rc=%d\n",
             (unsigned long long)robot_motion_now_ms(),
             (unsigned long)request.request_id, ret);
      pthread_cond_broadcast(&g_motion.cond);
      pthread_mutex_unlock(&g_motion.lock);
      printf("[ROBOT-MOTION] done id=%lu rc=%d\n",
             (unsigned long)request.request_id, ret);
    }

  return NULL;
}

const char *robot_motion_direction_name(
    enum robot_motion_direction_e direction)
{
  static const char *const names[] =
  {
    "forward", "backward", "left", "right"
  };

  return direction >= 0 && direction < ROBOT_MOTION_DIRECTION_COUNT ?
         names[direction] : "unknown";
}

int robot_motion_direction_from_name(const char *name,
                                     enum robot_motion_direction_e *direction)
{
  int i;

  if (name == NULL || direction == NULL)
    {
      return -EINVAL;
    }

