  if (!a) return NULL;
  a->mode = mode;
  a->noise_q8 = 32u * 256u;
  a->vad = fvad_new();
  if (!a->vad) goto failed;
  if (fvad_set_sample_rate(a->vad, ROBOT_VOICE_CAPTURE_RATE) < 0 ||
      fvad_set_mode(a->vad, ROBOT_VOICE_VAD_MODE) < 0)
    goto failed;
  return a;
