#define main legacy_monitor_main
#include "test_monitor.c"
#undef main
extern uint8_t *test_wakeword_pcm;
extern size_t test_wakeword_cap, test_wakeword_bytes;
extern unsigned long test_wakeword_frames;

static void test_continuous_kws(void)
{
  enum { N=16384+17 };
  int16_t *in=malloc(N*2),*seen=malloc(N*2);
  struct rv_segmenter_s s;
  reset_monitor(RV_MON_WAKE);init_segment(&s);
  s.afe=robot_voice_afe_create(ROBOT_AFE_RAW);assert(s.afe&&in&&seen);
  for(size_t i=0;i<N;i++)in[i]=(i%7)-3;
  test_wakeword_pcm=(uint8_t *)seen;test_wakeword_cap=N*2;
  test_wakeword_bytes=test_wakeword_frames=0;
  memset(&g_monitor.afe_stats,0,sizeof(g_monitor.afe_stats));
  for(size_t off=0;off<N*2;){
    size_t n=N*2-off;if(n>1024)n=1024;
    assert(!rv_monitor_frame((uint8_t *)in+off,n,&s));off+=n;
  }
  assert(!s.active&&!g_monitor.queued);
  assert(test_wakeword_frames==N/ROBOT_AFE_SAMPLES);
  assert(test_wakeword_bytes==N/ROBOT_AFE_SAMPLES*ROBOT_AFE_BYTES);
  assert(!memcmp(in,seen,test_wakeword_bytes));
  assert(g_monitor.afe_stats.input_samples==N);
  assert(g_monitor.afe_stats.output_samples+g_monitor.afe_stats.partial_samples==N);
  g_monitor.muted=true;
  unsigned long frames=test_wakeword_frames;
  assert(!rv_monitor_frame((uint8_t *)in,1024,&s));
  assert(test_wakeword_frames==frames&&!s.pre_used&&!s.onset);
  robot_voice_afe_destroy(s.afe);free(s.pre);free(s.speech);free(in);free(seen);
  test_wakeword_pcm=NULL;
}
static void test_pre_roll_and_gaps(void)
{
  struct rv_segmenter_s s;reset_monitor(RV_MON_LISTEN);init_segment(&s);
  int16_t pcm[ROBOT_AFE_SAMPLES];
  struct robot_voice_afe_frame_s f={.raw=pcm,.clean=pcm,.audio=pcm,.kws=pcm,
    .threshold=80,.level=1600};
  const bool onset[]={true,false,true,true,false,true};
  for(unsigned int frame=0;frame<26;frame++){
    for(size_t i=0;i<ROBOT_AFE_SAMPLES;i++)pcm[i]=frame;
    f.voiced=frame<20?false:onset[frame-20];
    assert(!rv_monitor_pcm(&f,&s));
    assert(s.active==(frame==25));
  }
  assert(s.used==RV_MS_BYTES(ROBOT_VOICE_PRE_ROLL_MS)+ROBOT_AFE_BYTES);
  for(size_t i=0;i<s.used/2;i++){
    int16_t sample;memcpy(&sample,s.speech+i*2,2);
    assert(sample==10+i/ROBOT_AFE_SAMPLES);
  }
  /* VAD-negative frames inside an active utterance remain on its timeline. */
  for(unsigned int frame=26;frame<30;frame++){
    for(size_t i=0;i<ROBOT_AFE_SAMPLES;i++)pcm[i]=frame;
    f.voiced=frame!=27;assert(!rv_monitor_pcm(&f,&s));
  }
  for(size_t i=0;i<s.used/2;i++){
    int16_t sample;memcpy(&sample,s.speech+i*2,2);
    assert(sample==10+i/ROBOT_AFE_SAMPLES);
  }
  g_monitor.muted=true;assert(!rv_monitor_pcm(&f,&s));
  assert(!s.active&&!s.pre_used&&!s.onset);
  free(s.pre);free(s.speech);
}
int main(void)
{
  test_continuous_kws();test_pre_roll_and_gaps();
  puts("PASS: real DMA/AFE adapter sends every silent sample to KWS, reports exact counters, excludes muted audio, and preserves pre-roll plus internal VAD-negative gaps");
}
