static void pcm_frames(struct rv_segmenter_s *s,unsigned ms,bool voiced)
{
  int16_t samples[ROBOT_AFE_SAMPLES];
  for(size_t i=0;i<ROBOT_AFE_SAMPLES;i++)samples[i]=(i%2)?1200:-1200;
  struct robot_voice_afe_frame_s f={.raw=samples,.clean=samples,.audio=samples,
    .kws=samples,.level=voiced?1200:0,.threshold=80,.voiced=voiced};
  for(unsigned i=0;i<ms;i+=20)assert(!rv_monitor_pcm(&f,s));
}
static void seg_init(struct rv_segmenter_s *s)
{
  memset(s,0,sizeof(*s));s->epoch=g_monitor.epoch;
  s->pre=calloc(1,RV_MS_BYTES(ROBOT_VOICE_PRE_ROLL_MS));
  s->speech=malloc(RV_MS_BYTES(ROBOT_VOICE_SEGMENT_MAX_MS));assert(s->pre&&s->speech);
}
static struct rv_monitor_job_s *candidate(struct rv_segmenter_s *s)
{
  pcm_frames(s,200,true);pcm_frames(s,640,false);
  pthread_mutex_lock(&g_monitor.lock);
  assert(g_monitor.queued==1);
  struct rv_monitor_job_s *j=g_monitor.queue[0];
  g_monitor.queued=0;g_monitor.queued_pcm=0;
  pthread_mutex_unlock(&g_monitor.lock);
  assert(j->pcm_len==RV_MS_BYTES(840));
  free(j->pcm);j->pcm=NULL;
  return j;
}
