  struct robot_voice_afe_frame_s f={.raw=pcm,.clean=pcm,.audio=pcm,.kws=pcm,
    .threshold=80,.level=voice?1600:0,.voiced=voice};
  for(unsigned int frame=start;frame<start+count;frame++){
    for(size_t j=0;j<ROBOT_AFE_SAMPLES;j++)pcm[j]=(int16_t)frame;
    atomic_fetch_add(&fake_now,ROBOT_VOICE_AFE_FRAME_MS);
