  const char *texts[]={"你好，openvela。北京有哪些好玩的地方",
    "你好 Open Vela，北京有哪些好玩的地方","OpenVela，北京有哪些好玩的地方",
    "刚才的背景谈话。你好，OpenVela。北京有哪些好玩的地方",cmd};
