  assert(!strcmp(rv_wake_command_tail("OpenVelax，北京"),"OpenVelax，北京"));
  assert(!strcmp(rv_wake_command_tail("北京有没有叫你好openvela的店"),"北京有没有叫你好openvela的店"));
