static void test_final_keeps_all_handoff_audio(void)
{
  struct rv_segmenter_s s;reset_monitor(RV_MON_WAKE);init_segment(&s);
  marked(&s,0,80,true);wake_at(80*ROBOT_AFE_SAMPLES,true);
  marked(&s,80,20,true);marked(&s,100,8,false);
