+      if (!probe->first) probe->first = now;
+      if (probe->last && now - probe->last > probe->max_gap)
+        probe->max_gap = now - probe->last;
+      probe->last = now;
+      probe->bytes += bytes;
+      probe->chunks++;
+    }
+  return 0; /* Network + TLS + SSE only; no I2S, scaling or playback pacing. */
