    hit = strstr(p, "；");
    if (hit != NULL && hit < end) end = hit;
    hit = strstr(p, "然后");
    if (hit != NULL && hit < end) end = hit;
    hit = strstr(p, "并在");
    if (hit != NULL && hit < end) end = hit;
    hit = strstr(p, "之后");
    if (hit != NULL && hit < end) end = hit;
    hit = strstr(p, "后关闭");
    if (hit != NULL && hit < end) end = hit;
    hit = strstr(p, "后停止");
    if (hit != NULL && hit < end) end = hit;

    length = (size_t)(end - p);
    if (length >= keyword_size) {
        length = keyword_size - 1;
    }
    memcpy(keyword, p, length);
    keyword[length] = '\0';

    while (length > 0 && keyword[length - 1] == ' ') {
        keyword[--length] = '\0';
    }
    if (length == 0 || strcmp(keyword, "歌") == 0) {
        snprintf(keyword, keyword_size, "音乐");
    }
}

