      case ROBOT_VOICE_ACTION_RIGHT:
        direction = ROBOT_MOTION_RIGHT;
        break;

      case ROBOT_VOICE_ACTION_HAPPY:
        return robot_expression_set(ROBOT_EXPRESSION_SOURCE_AGENT,
