 71	int robot_voice_wifi_ensure_connected(uint32_t timeout_ms)
 72	{
 73	  unsigned long long deadline;
 74	  unsigned long long now;
 75	  unsigned int attempt = 0;
 76	  int last = -ENETDOWN;
 77	  bool recovery_started = false;
 78	
 79	  if (timeout_ms == 0)
 80	    {
 81	      timeout_ms = ROBOT_VOICE_ACTION_NET_TIMEOUT_MS;
 82	    }
 83	
 84	  now = rv_diag_now_ms();
 85	  deadline = now + timeout_ms;
 86	  if (network_is_connected())
 87	    {
 88	      return 0;
 89	    }
 90	
 91	  RV_EVENT("[网络确认] action gate waiting timeout=%ums\n", timeout_ms);
 92	  while (rv_diag_now_ms() < deadline)
 93	    {
 94	      unsigned long long remaining;
 95	
 96	      if (robot_voice_http_network_recovery_begin != NULL &&
 97	          robot_voice_http_network_recovery_end != NULL)
 98	        {
 99	          if (!robot_voice_http_network_recovery_begin())
100	            {
101	              usleep(100 * 1000);
102	              continue;
103	            }
104	          recovery_started = true;
105	        }
106	
107	      attempt++;
108	      RV_EVENT("[网络确认] reconnect attempt=%u\n", attempt);
109	      last = robot_voice_wifi_recover_once();
110	      if (recovery_started)
111	        {
112	          robot_voice_http_network_recovery_end();
113	          recovery_started = false;
114	        }
115	
116	      if (last == 0 && network_is_connected())
117	        {
118	          RV_EVENT("[网络确认] connected attempt=%u\n", attempt);
119	          return 0;
120	        }
121	
122	      now = rv_diag_now_ms();
123	      if (now >= deadline)
124	        {
125	          break;
126	        }
127	
128	      remaining = deadline - now;
129	      if (remaining > ROBOT_VOICE_ACTION_NET_RETRY_MS)
130	        {
131	          remaining = ROBOT_VOICE_ACTION_NET_RETRY_MS;
132	        }
133	      usleep((useconds_t)remaining * 1000);
134	    }
135	
136	  if (recovery_started)
137	    {
138	      robot_voice_http_network_recovery_end();
139	    }
140	  RV_EVENT("[网络确认] failed rc=%d attempts=%u\n", last, attempt);
141	  return last < 0 ? last : -ETIMEDOUT;
142	}
