 100	      int32_t y = x - a->hp_x + a->hp_y * 31 / 32;
 101	      a->hp_x = x;
 102	      if (y > 32767) y = 32767;
 103	      if (y < -32768) y = -32768;
 104	      a->hp_y = y;
 105	      a->clean[i] = (int16_t)y;
 106	      if (a->raw[i] == INT16_MIN || a->raw[i] == INT16_MAX)
 107	        a->stats.clipped_samples++;
 108	    }
 109	  frame.raw = a->raw;
 110	  frame.clean = a->clean;
 111	  frame.audio = a->raw;
 112	  frame.kws = a->mode == ROBOT_AFE_CLEAN ? a->clean : a->raw;
 113	  vad_audio = a->mode == ROBOT_AFE_RAW ? a->raw : a->clean;
 114	  level = rv_afe_level(vad_audio);
 115	  threshold = (a->noise_q8 / 256u) * 3u / 2u + 20u;
 116	  if (threshold < ROBOT_VOICE_VAD_MIN_LEVEL)
 117	    threshold = ROBOT_VOICE_VAD_MIN_LEVEL;
 118	  if (!a->suppressed)
 119	    {
 120	      decision = robot_afe_vad_evidence(a->vad, vad_audio, ROBOT_AFE_SAMPLES);
 121	      if (decision < 0) return -EIO;
 122	      /* >1 is WebRTC's own hangover, NOT a new speech observation. */
 123	      if (decision != 1 || level < threshold)
 124	        {
 125	          unsigned int target = level * 256u;
 126	          /* Fast downward, slow upward, with fractional precision. */
 127	          if (target < a->noise_q8)
 128	            a->noise_q8 -= (a->noise_q8 - target + 7u) / 8u;
 129	          else
 130	            a->noise_q8 += (target - a->noise_q8 + 63u) / 64u;
 131	        }
 132	    }
 133	  frame.level = level;
 134	  frame.threshold = threshold;
 135	  frame.voiced = !a->suppressed && decision == 1 && level >= threshold;
 136	  a->stats.frames++;
 137	  a->stats.output_samples += ROBOT_AFE_SAMPLES;
 138	  a->stats.speech_frames += frame.voiced ? 1u : 0u;
 139	  a->stats.raw_level = rv_afe_level(a->raw);
 140	  a->stats.clean_level = rv_afe_level(a->clean);
 141	  a->stats.noise_level = a->noise_q8 / 256u;
 142	  a->stats.threshold = threshold;
 143	  elapsed = rv_afe_us();
 144	  elapsed = elapsed >= start ? elapsed - start : 0;
 145	  if (elapsed > a->stats.max_process_us)
 146	    a->stats.max_process_us = elapsed > UINT32_MAX ? UINT32_MAX : elapsed;
 147	  if (elapsed > ROBOT_VOICE_AFE_FRAME_MS * 1000u) a->stats.overruns++;
 148	  return sink(&frame, arg);
 149	}
