 151	int robot_voice_afe_push(struct robot_voice_afe_s *a, const uint8_t *pcm,
 152	                         size_t len, robot_voice_afe_sink_t sink, void *arg)
 153	{
 154	  size_t take;
 155	  int ret;
 156	  if (!a || !sink || (!pcm && len) || (len & 1u)) return -EINVAL;
 157	  while (len)
 158	    {
 159	      take = ROBOT_AFE_BYTES - a->used;
 160	      if (take > len) take = len;
 161	      memcpy((uint8_t *)a->raw + a->used, pcm, take);
 162	      a->stats.input_samples += take / sizeof(int16_t);
 163	      pcm += take;
 164	      len -= take;
 165	      a->used += take;
 166	      if (a->used == ROBOT_AFE_BYTES)
 167	        {
 168	          a->used = 0;
 169	          ret = rv_afe_frame(a, sink, arg);
 170	          if (ret != 0) return ret;
 171	        }
 172	    }
 173	  return 0;
 174	}
