   102	    {
   103	      g_total = g_last_scored = g_last_trigger = 0;
   104	      g_generation++; g_active = active; g_epoch = epoch;
   105	      g_candidate_last_end = 0; g_candidate_hits = 0;
   106	      reset_score_average();
