   112	        g_ring[g_total % g_capacity] =
   113	          (int16_t)((uint16_t)pcm[i] | ((uint16_t)pcm[i + 1] << 8));
   114	        g_total++;
   115	      }
   116	  pthread_mutex_unlock(&g_wake_lock);
   117	  return 0;
