140	extern "C" int robot_wakeword_model_predict(const float *features, float *score)
141	{
142	  if (!features || !score)
143	    {
144	      return -EINVAL;
145	    }
146	
147	  *score = 0.0f;
148	  if (!g_interpreter)
149	    {
150	      return -ENODEV;
151	    }
152	
153	  const size_t count =
154	    static_cast<size_t>(g_robot_wakeword_model_config.time_bins) *
155	    g_robot_wakeword_model_config.mel_bins;
156	  for (size_t i = 0; i < count; ++i)
157	    {
158	      if (!isfinite(features[i]))
159	        {
160	          return -EINVAL;
161	        }
162	
163	      const float quantized = features[i] / g_input->params.scale +
164	                              g_input->params.zero_point;
165	      g_input->data.int8[i] = quantized <= -128.0f ? -128 :
166	                             quantized >= 127.0f ? 127 :
167	                             static_cast<int8_t>(lrintf(quantized));
168	    }
169	
170	  return invoke(score);
171	}
