 55	int robot_wakeword_init(void)
 56	{
 57	  const struct robot_wakeword_model_config_s *c = &g_robot_wakeword_model_config;
 58	  if (g_ring) return -EBUSY;
 59	  int ret = robot_wakeword_model_init();
 60	  if (ret < 0) return ret;
