#pragma once
#include <limits>
#include "robot_wakeword_model_params.h"

// Pair with wakeword.py EventDetector. Feed the dequantized positive score,
// normalized-window RMS, and absolute end time in seconds on every inference hop.
// Keep this object alive between hops; Reset only when starting a new stream.
struct RobotWakewordDetection {
  bool wake;
  double score;
};

class RobotWakewordDetector {
 public:
  RobotWakewordDetector() { Reset(); }
  void Reset() {
    for (int i = 0; i < ROBOT_WAKEWORD_SCORE_AVERAGE_WINDOW; ++i) history_[i] = 0.0;
    armed_ = true;
    last_ = -std::numeric_limits<double>::infinity();
  }
  RobotWakewordDetection Update(float raw_score, double window_rms, double end_seconds) {
    for (int i = 1; i < ROBOT_WAKEWORD_SCORE_AVERAGE_WINDOW; ++i) history_[i - 1] = history_[i];
    history_[ROBOT_WAKEWORD_SCORE_AVERAGE_WINDOW - 1] =
        window_rms >= ROBOT_WAKEWORD_MIN_RMS ? static_cast<double>(raw_score) : 0.0;
    double score = 0.0;
    for (int i = 0; i < ROBOT_WAKEWORD_SCORE_AVERAGE_WINDOW; ++i) score += history_[i];
    score /= ROBOT_WAKEWORD_SCORE_AVERAGE_WINDOW;
    double reset = ROBOT_WAKEWORD_THRESHOLD - ROBOT_WAKEWORD_HYSTERESIS;
    if (reset < 0.0) reset = 0.0;
    if (score <= reset) armed_ = true;
    const bool wake = armed_ && score >= ROBOT_WAKEWORD_THRESHOLD &&
        end_seconds - last_ >= ROBOT_WAKEWORD_COOLDOWN_SECONDS;
    if (wake) { armed_ = false; last_ = end_seconds; }
    return RobotWakewordDetection{wake, score};
  }
 private:
  double history_[ROBOT_WAKEWORD_SCORE_AVERAGE_WINDOW];
  bool armed_;
  double last_;
};

