int robot_wakeword_poll(struct robot_wakeword_result_s *out)
{
  const struct robot_wakeword_model_config_s *c = &g_robot_wakeword_model_config;
  uint64_t end, gen, old_end;
  unsigned int epoch;
  size_t count, start, first;
