      g_candidate_last_end = 0;
    }
  else if (out->score <= fmaxf(0, out->threshold - c->hysteresis))
    {
      g_armed = true;
      g_candidate_hits = 0;
      g_candidate_last_end = 0;
    }
  else if (out->score >= out->threshold)
    {
      if (out->skipped_windows != 0 || !g_candidate_hits ||
          end - g_candidate_last_end != c->hop_samples)
        g_candidate_hits = 1;
      else
