 52	static void fft(struct robot_wakeword_frontend_s *s)
 53	{
 54	  const uint32_t n = s->c->fft_length;
 55	  uint32_t i, j = 0;
 56	  for (i = 1; i < n; i++)
 57	    {
 58	      uint32_t bit = n >> 1;
 59	      while (j & bit) { j ^= bit; bit >>= 1; }
 60	      j ^= bit;
 61	      if (i < j)
 62	        {
 63	          float t = s->real[i]; s->real[i] = s->real[j]; s->real[j] = t;
 64	          t = s->imag[i]; s->imag[i] = s->imag[j]; s->imag[j] = t;
 65	        }
 66	    }
 67	  for (uint32_t length = 2; length <= n; length <<= 1)
 68	    for (uint32_t base = 0; base < n; base += length)
 69	      for (j = 0; j < length / 2; j++)
 70	        {
 71	          uint32_t k = j * (n / length), a = base + j, b = a + length / 2;
 72	          float wr = s->c->twiddle_real[k], wi = s->c->twiddle_imag[k];
 73	          float tr = wr * s->real[b] - wi * s->imag[b];
 74	          float ti = wr * s->imag[b] + wi * s->real[b];
 75	          s->real[b] = s->real[a] - tr; s->imag[b] = s->imag[a] - ti;
 76	          s->real[a] += tr; s->imag[a] += ti;
 77	        }
 78	}
