100	    }
101	  const float floor_power = powf(10.0f, c->db_floor / 10.0f);
102	  for (i = 0; i < c->mel_bins; i++)
103	    {
104	      float energy = 0;
105	      for (uint32_t j = 0; j < c->mel_length[i]; j++)
106	        energy += s->power[c->mel_start[i] + j] *
107	                  c->mel_weights[c->mel_offset[i] + j];
108	      float db = 10.0f * log10f(fmaxf(energy, floor_power));
