 121	{
 122	  const struct robot_wakeword_model_config_s *c = &g_robot_wakeword_model_config;
 123	  uint64_t end, gen, old_end;
 124	  unsigned int epoch;
 125	  size_t count, start, first;
 126	  float raw, rms, gated_score;
 127	  double energy = 0;
 128	  int ret;
 129	  if (!out) return -EINVAL;
 130	  pthread_mutex_lock(&g_wake_lock);
 131	  if (!g_ring || !g_active) { pthread_mutex_unlock(&g_wake_lock); return 0; }
 132	  end = g_total / c->hop_samples * c->hop_samples;
 133	  if (end == g_last_scored) { pthread_mutex_unlock(&g_wake_lock); return 0; }
 134	  gen = g_generation; epoch = g_epoch; old_end = g_last_scored;
 135	  count = end < c->window_samples ? (size_t)end : c->window_samples;
 136	  memset(g_snapshot, 0, (c->window_samples - count) * sizeof(int16_t));
 137	  start = (size_t)((end - count) % g_capacity);
 138	  first = g_capacity - start;
 139	  if (first > count) first = count;
 140	  memcpy(g_snapshot + c->window_samples - count, g_ring + start,
 141	         first * sizeof(int16_t));
 142	  memcpy(g_snapshot + c->window_samples - count + first, g_ring,
 143	         (count - first) * sizeof(int16_t));
 144	  pthread_mutex_unlock(&g_wake_lock);
 145	  ret = robot_wakeword_frontend_compute(g_front, g_snapshot, end, gen, g_features);
 146	  if (ret < 0) return ret;
 147	  ret = robot_wakeword_model_predict(g_features, &raw);
 148	  if (ret < 0) return ret;
 149	  for (size_t i = 0; i < c->window_samples; i++)
 150	    { double value = g_snapshot[i] / 32768.0; energy += value * value; }
 151	  rms = (float)sqrt(energy / c->window_samples);
 152	  pthread_mutex_lock(&g_wake_lock);
 153	  if (gen != g_generation || !g_active || epoch != g_epoch)
 154	    { pthread_mutex_unlock(&g_wake_lock); return 0; }
 155	  g_last_scored = end;
 156	  memset(out, 0, sizeof(*out));
 157	  out->epoch = epoch; out->end_sample = end; out->raw_score = raw;
 158	  gated_score = rms >= c->min_rms ? raw : 0;
 159	  if (g_score_count == ROBOT_WAKEWORD_SCORE_AVG_WINDOW)
 160	    g_score_sum -= g_score_window[g_score_pos];
 161	  else
 162	    g_score_count++;
 163	  g_score_window[g_score_pos] = gated_score;
 164	  g_score_sum += gated_score;
 165	  g_score_pos = (g_score_pos + 1) % ROBOT_WAKEWORD_SCORE_AVG_WINDOW;
 166	  out->score = g_score_sum / g_score_count;
 167	  out->rms = rms;
 168	  out->threshold = threshold();
 169	  out->skipped_windows = (end - old_end) / c->hop_samples - 1;
 170	  /* Do not trigger until a complete configured moving-average window exists. */
 171	  if (g_score_count < ROBOT_WAKEWORD_SCORE_AVG_WINDOW)
 172	    {
 173	      g_candidate_hits = 0;
 174	      g_candidate_last_end = 0;
 175	    }
 176	  else if (out->score <= fmaxf(0, out->threshold - c->hysteresis))
 177	    {
 178	      g_armed = true;
 179	      g_candidate_hits = 0;
 180	      g_candidate_last_end = 0;
 181	    }
 182	  else if (out->score >= out->threshold)
 183	    {
 184	      if (out->skipped_windows != 0 || !g_candidate_hits ||
 185	          end - g_candidate_last_end != c->hop_samples)
 186	        g_candidate_hits = 1;
 187	      else
 188	        g_candidate_hits++;
 189	      g_candidate_last_end = end;
 190	    }
 191	  else
 192	    {
 193	      g_candidate_hits = 0;
 194	      g_candidate_last_end = 0;
 195	    }
 196	  if (g_armed && g_candidate_hits >= ROBOT_WAKEWORD_CONFIRM_HITS &&
 197	      (!g_has_trigger || (double)(end - g_last_trigger) >=
 198	       (double)c->cooldown_seconds * c->sample_rate))
 199	    {
 200	      out->triggered = true; g_armed = false;
 201	      g_has_trigger = true; g_last_trigger = end;
 202	      g_candidate_hits = 0;
 203	      g_candidate_last_end = 0;
 204	    }
 205	  pthread_mutex_unlock(&g_wake_lock);
 206	  return 1;
 207	}
